import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Employee {
  id: string;
  name: string;
  role: string;
  department: string;
  email: string;
  status: 'Active' | 'On Leave' | 'Inactive';
  avatar: string;
  joinDate: string;
}

export interface JobPosting {
  id: string;
  title: string;
  department: string;
  location: string;
  type: string;
  description: string;
  status: 'Open' | 'Closed' | 'Draft';
}

export interface PerformanceReview {
  id: string;
  employeeId: string;
  reviewer: string;
  date: string;
  rating: number;
  comments: string;
  summary?: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateJobDescription = async (title: string, department: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Write a professional and engaging job description for the position of "${title}" in the "${department}" department. Include Key Responsibilities, Required Skills, and Why Join Us sections.`,
    config: {
      temperature: 0.7,
      topP: 0.8,
    }
  });
  return response.text || "Failed to generate job description.";
};

export const summarizePerformanceReview = async (rawNotes: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Summarize the following raw performance review notes into a professional, concise summary suitable for an HR system: "${rawNotes}"`,
    config: {
      temperature: 0.4,
    }
  });
  return response.text || "Failed to summarize review.";
};

export const getHRAssistantResponse = async (query: string, history: { role: 'user' | 'model', text: string }[]): Promise<string> => {
  const chat = ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: "You are NexusAI, the intelligent HR assistant for NexusHR. You provide helpful, accurate, and professional information about HR best practices, policy guidelines (general), and workplace productivity. Keep answers concise and supportive.",
      tools: [{ googleSearch: {} }]
    }
  });

  // Since chat history needs to be passed, we'd normally format it. 
  // For simplicity here, we'll just send the current query but you could rebuild history.
  const response = await chat.sendMessage({ message: query });
  return response.text || "I'm sorry, I couldn't process that request.";
};

