import React, { useState } from 'react';
import { Briefcase, Wand2, Plus, Search, Loader2 } from 'lucide-react';
import { generateJobDescription } from '../services/geminiService';
import { DEPARTMENTS } from '../constants';

const Recruitment: React.FC = () => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [jobTitle, setJobTitle] = useState('');
  const [dept, setDept] = useState(DEPARTMENTS[0]);
  const [generatedJD, setGeneratedJD] = useState('');

  const handleGenerate = async () => {
    if (!jobTitle) return;
    setIsGenerating(true);
    try {
      const jd = await generateJobDescription(jobTitle, dept);
      setGeneratedJD(jd);
    } catch (error) {
      console.error(error);
      alert("Failed to generate JD. Please check your API key.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-8 animate-in zoom-in-95 duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Recruitment Hub</h1>
          <p className="text-gray-500">Manage job postings and use AI to craft perfect descriptions.</p>
        </div>
        <button className="px-4 py-2 bg-indigo-600 text-white rounded-xl font-medium hover:bg-indigo-700 flex items-center gap-2">
          <Plus size={18} /> New Posting
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
              <Wand2 size={20} className="text-indigo-600" />
              JD Assistant
            </h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Job Title</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/20"
                  placeholder="e.g. Senior Frontend Engineer"
                  value={jobTitle}
                  onChange={(e) => setJobTitle(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Department</label>
                <select 
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl outline-none"
                  value={dept}
                  onChange={(e) => setDept(e.target.value)}
                >
                  {DEPARTMENTS.map(d => <option key={d}>{d}</option>)}
                </select>
              </div>
              <button 
                onClick={handleGenerate}
                disabled={isGenerating || !jobTitle}
                className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
                  isGenerating ? 'bg-gray-100 text-gray-400' : 'bg-indigo-600 text-white hover:bg-indigo-700 active:scale-95'
                }`}
              >
                {isGenerating ? <Loader2 className="animate-spin" size={20} /> : 'Generate with Gemini'}
              </button>
            </div>
          </div>

          <div className="bg-indigo-600 p-6 rounded-2xl text-white">
            <h3 className="font-bold mb-2">Pro Tip</h3>
            <p className="text-indigo-100 text-sm">
              Use the Gemini assistant to generate interview questions specifically for the roles you're hiring for.
            </p>
          </div>
        </div>

        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-gray-100 min-h-[500px] flex flex-col">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold">Draft Job Description</h2>
            <button 
              className="text-sm text-indigo-600 font-semibold hover:underline"
              onClick={() => { navigator.clipboard.writeText(generatedJD); alert("Copied!"); }}
              disabled={!generatedJD}
            >
              Copy to Clipboard
            </button>
          </div>

          <div className="flex-1 bg-gray-50 rounded-xl p-6 overflow-y-auto max-h-[600px] border border-gray-100">
            {generatedJD ? (
              <div className="prose prose-sm max-w-none whitespace-pre-wrap text-gray-700">
                {generatedJD}
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-center space-y-3">
                <div className="p-4 bg-white rounded-full">
                  <Briefcase size={48} className="text-gray-200" />
                </div>
                <p className="text-gray-400 font-medium italic">
                  Enter a job title on the left and click generate to see AI-powered magic.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Recruitment;

import React, { useState } from 'react';
import { Star, FileText, Send, CheckCircle, Loader2 } from 'lucide-react';
import { summarizePerformanceReview } from '../services/geminiService';
import { MOCK_EMPLOYEES } from '../constants';

const Performance: React.FC = () => {
  const [selectedEmp, setSelectedEmp] = useState(MOCK_EMPLOYEES[0]);
  const [rawNotes, setRawNotes] = useState('');
  const [summary, setSummary] = useState('');
  const [isSummarizing, setIsSummarizing] = useState(false);

  const handleSummarize = async () => {
    if (!rawNotes) return;
    setIsSummarizing(true);
    try {
      const result = await summarizePerformanceReview(rawNotes);
      setSummary(result);
    } catch (err) {
      console.error(err);
      alert("Error summarizing review.");
    } finally {
      setIsSummarizing(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in slide-in-from-right-4 duration-500">
      <header>
        <h1 className="text-2xl font-bold">Performance Reviews</h1>
        <p className="text-gray-500">Track achievements and generate professional feedback summaries.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-4">
          <h2 className="font-bold text-gray-700 px-2">Team Members</h2>
          <div className="space-y-2 overflow-y-auto max-h-[500px] pr-2">
            {MOCK_EMPLOYEES.map(emp => (
              <button
                key={emp.id}
                onClick={() => setSelectedEmp(emp)}
                className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all border ${
                  selectedEmp.id === emp.id 
                    ? 'bg-white border-indigo-200 shadow-sm' 
                    : 'bg-transparent border-transparent hover:bg-gray-100 text-gray-600'
                }`}
              >
                <img src={emp.avatar} alt={emp.name} className="w-8 h-8 rounded-full" />
                <div className="text-left flex-1 min-w-0">
                  <p className="text-sm font-semibold truncate">{emp.name}</p>
                  <p className="text-xs opacity-70 truncate">{emp.role}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
          <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
            <div className="flex flex-col md:flex-row gap-6 items-start">
              <img src={selectedEmp.avatar} alt="" className="w-20 h-20 rounded-2xl shadow-md" />
              <div className="flex-1 space-y-1">
                <h3 className="text-xl font-bold">{selectedEmp.name}</h3>
                <p className="text-gray-500">{selectedEmp.role} &bull; {selectedEmp.department}</p>
                <div className="flex items-center gap-4 mt-4">
                  <div className="flex items-center gap-1 text-yellow-500">
                    {[1,2,3,4].map(i => <Star key={i} size={16} fill="currentColor" />)}
                    <Star size={16} className="text-gray-200" fill="currentColor" />
                  </div>
                  <span className="text-sm text-gray-400 font-medium">Last Review: 6 months ago</span>
                </div>
              </div>
            </div>

            <div className="mt-8 space-y-6">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-2">Internal Feedback Notes</label>
                <textarea 
                  className="w-full h-32 p-4 bg-gray-50 border border-gray-100 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500/10 focus:bg-white transition-all text-sm leading-relaxed"
                  placeholder="Paste rough bullet points, meeting notes, or specific observations here..."
                  value={rawNotes}
                  onChange={(e) => setRawNotes(e.target.value)}
                />
              </div>

              <div className="flex justify-end">
                <button 
                  onClick={handleSummarize}
                  disabled={isSummarizing || !rawNotes}
                  className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all active:scale-95 disabled:bg-gray-200 disabled:text-gray-400"
                >
                  {isSummarizing ? <Loader2 className="animate-spin" size={20} /> : <FileText size={20} />}
                  Summarize with AI
                </button>
              </div>

              {summary && (
                <div className="p-6 bg-indigo-50 border border-indigo-100 rounded-2xl animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="flex items-center gap-2 text-indigo-700 font-bold mb-3 uppercase tracking-wider text-xs">
                    <CheckCircle size={14} /> AI-Generated Summary
                  </div>
                  <p className="text-gray-700 text-sm leading-relaxed whitespace-pre-wrap">
                    {summary}
                  </p>
                  <div className="mt-6 flex gap-3">
                    <button className="px-4 py-2 bg-white border border-indigo-200 text-indigo-700 rounded-lg text-sm font-bold hover:bg-indigo-100 transition-colors">
                      Save to Profile
                    </button>
                    <button className="px-4 py-2 text-gray-500 text-sm font-bold hover:text-gray-700 transition-colors">
                      Edit Manually
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Performance;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, Info } from 'lucide-react';
import { getHRAssistantResponse } from '../services/geminiService';
import { ChatMessage } from '../types';

const AIAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hello! I am NexusAI, your HR intelligence assistant. How can I help you today? I can answer questions about labor laws, best practices, or help with company templates.' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await getHRAssistantResponse(userMsg, messages);
      setMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I encountered an error. Please check your connection or API key." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto h-[calc(100vh-12rem)] flex flex-col animate-in fade-in duration-500">
      <header className="mb-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 text-white rounded-xl">
            <Bot size={24} />
          </div>
          <div>
            <h1 className="text-xl font-bold">NexusAI Assistant</h1>
            <p className="text-xs text-green-500 font-medium">Online & Ready to Help</p>
          </div>
        </div>
        <div className="flex items-center gap-2 text-xs text-gray-400 bg-gray-50 px-3 py-1.5 rounded-full border border-gray-100">
          <Info size={14} /> Grounded by Google Search
        </div>
      </header>

      <div className="flex-1 bg-white border border-gray-100 rounded-3xl shadow-sm overflow-hidden flex flex-col">
        <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar" ref={scrollRef}>
          {messages.map((m, idx) => (
            <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`flex gap-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                  m.role === 'user' ? 'bg-gray-200 text-gray-600' : 'bg-indigo-100 text-indigo-600'
                }`}>
                  {m.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`p-4 rounded-2xl text-sm leading-relaxed ${
                  m.role === 'user' ? 'bg-indigo-600 text-white' : 'bg-gray-50 text-gray-700'
                }`}>
                  {m.text}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="flex gap-3 max-w-[85%]">
                <div className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 bg-indigo-100 text-indigo-600">
                  <Bot size={16} />
                </div>
                <div className="p-4 rounded-2xl bg-gray-50 flex items-center gap-2">
                  <Loader2 className="animate-spin text-indigo-600" size={16} />
                  <span className="text-xs text-gray-400 font-medium">NexusAI is thinking...</span>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="p-4 border-t border-gray-50 bg-gray-50/50">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Ask about employment laws, draft a policy, or get HR tips..."
              className="w-full pl-6 pr-14 py-4 bg-white border border-gray-200 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all shadow-sm"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 disabled:bg-gray-200 transition-all active:scale-90"
            >
              <Send size={20} />
            </button>
          </div>
          <p className="text-[10px] text-gray-400 text-center mt-3 uppercase tracking-widest font-bold">
            Powered by Gemini 3 Flash
          </p>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

