// Provides HR intelligence assistance with Google Search grounding for accurate information.
export const getHRAssistantResponse = async (userMsg: string, history: ChatMessage[]): Promise<string> => {
  // Construct the conversation history for the model
  const contents = history.map(msg => ({
    role: msg.role,
    parts: [{ text: msg.text }]
  }));

  // Add the current user message to the context
  contents.push({ role: 'user', parts: [{ text: userMsg }] });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: contents,
    config: {
      systemInstruction: 'You are NexusAI, an expert HR Intelligence Assistant. Provide accurate, professional, and helpful advice on HR policies, labor laws, and workplace best practices. Always use Google Search for the most current information.',
      tools: [{ googleSearch: {} }],
    }
  });

  return response.text || "I'm sorry, I encountered an issue processing your request.";
};

