const Employees: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [employees, setEmployees] = useState<Employee[]>(MOCK_EMPLOYEES as Employee[]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showDeptMenu, setShowDeptMenu] = useState(false);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.role.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.department.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredEmployees.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(filteredEmployees.map(e => e.id));
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleBulkDeactivate = () => {
    if (window.confirm(`Are you sure you want to deactivate ${selectedIds.length} selected employees?`)) {
      setEmployees(prev => prev.map(emp => 
        selectedIds.includes(emp.id) ? { ...emp, status: 'Inactive' as const } : emp
      ));
      setSelectedIds([]);
      alert("Selected employees have been deactivated.");
    }
  };

  const handleBulkAssignDept = (newDept: string) => {
    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, department: newDept } : emp
    ));
    setSelectedIds([]);
    setShowDeptMenu(false);
    alert(`Selected employees reassigned to ${newDept}.`);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-24">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
