                  className={`hover:bg-blue-50/30 transition-colors group cursor-pointer ${selectedIds.includes(emp.id) ? 'bg-blue-50/50' : ''}`}
                  onClick={() => toggleSelect(emp.id)}
                >
                  <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                    <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-gray-300 text-blue-900 focus:ring-blue-900 accent-blue-900 cursor-pointer"
                      checked={selectedIds.includes(emp.id)}
                      onChange={() => toggleSelect(emp.id)}
                    />
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-3">
                      <img src={emp.avatar} alt={emp.name} className="w-10 h-10 rounded-xl object-cover border border-gray-100 shadow-sm" />
                      <div>
                        <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                        <p className="text-[11px] text-gray-400 font-medium">{emp.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <p className="text-sm font-semibold text-gray-700">{emp.role}</p>
                    <p className="text-[11px] text-blue-900/50 font-bold uppercase tracking-tight">{emp.department}</p>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`px-2 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
                      emp.status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
                      emp.status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
                      'bg-gray-50 text-gray-700 border-gray-200'
                    }`}>
                      {emp.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 font-medium">
                    {new Date(emp.joinDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right" onClick={(e) => e.stopPropagation()}>
                    <button className="p-2 hover:bg-white hover:shadow-sm border border-transparent hover:border-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all">
                      <MoreVertical size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredEmployees.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-6 py-16 text-center">
                    <div className="flex flex-col items-center gap-3 text-gray-400">
                      <Search size={48} className="opacity-20" />
                      <p className="font-medium italic">No personnel found matching your criteria.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selectedIds.length > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-blue-900 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-8 animate-in fade-in slide-in-from-bottom-8 duration-300 z-50 ring-4 ring-white">
          <div className="flex items-center gap-3 border-r border-blue-800 pr-8">
            <div className="bg-white text-blue-900 w-6 h-6 rounded-lg flex items-center justify-center font-bold text-xs">
              {selectedIds.length}
            </div>
            <span className="text-sm font-bold uppercase tracking-widest text-blue-100">Selected</span>
          </div>

          <div className="flex items-center gap-4 relative">
            <button 
              onClick={handleBulkDeactivate}
              className="flex items-center gap-2 px-3 py-2 hover:bg-blue-800 rounded-xl transition-all text-xs font-bold uppercase tracking-wider"
            >
              <UserMinus size={16} />
              Deactivate
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowDeptMenu(!showDeptMenu)}
                className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-all text-xs font-bold uppercase tracking-wider ${showDeptMenu ? 'bg-white text-blue-900' : 'hover:bg-blue-800'}`}
              >
                <FolderInput size={16} />
                Assign to Dept
              </button>

              {showDeptMenu && (
                <div className="absolute bottom-full mb-4 left-0 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in zoom-in-95">
                  <div className="p-2">
                    <p className="text-[10px] font-bold text-gray-400 uppercase px-3 py-2 tracking-widest">Select Department</p>
                    {DEPARTMENTS.map(dept => (
                      <button
                        key={dept}
                        onClick={() => handleBulkAssignDept(dept)}
                        className="w-full text-left px-4 py-2 text-sm font-bold text-blue-900 hover:bg-blue-50 rounded-xl transition-colors"
                      >
                        {dept}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <button 
              className="flex items-center gap-2 px-3 py-2 hover:bg-blue-800 rounded-xl transition-all text-xs font-bold uppercase tracking-wider"
            >
              <CheckCircle2 size={16} />
              Verify Docs
            </button>
          </div>

          <button 
            onClick={() => setSelectedIds([])}
            className="p-2 hover:bg-blue-800 rounded-full transition-all text-blue-300 ml-4"
          >
            <X size={20} />
          </button>
        </div>
      )}
    </div>
  );
};

export default Employees;

export type UserRole = 'HR' | 'Employee';

