                <img src={viewingEmployee.avatar} className="w-24 h-24 rounded-3xl object-cover shadow-lg border-2 border-white" alt="" />
                <div>
                  <h3 className="text-2xl font-bold text-blue-900">{viewingEmployee.name}</h3>
                  <p className="text-gray-500 font-medium">{viewingEmployee.role}</p>
                  <p className="text-xs text-blue-900/40 font-bold uppercase tracking-widest mt-1">{viewingEmployee.department}</p>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-sm font-bold uppercase tracking-widest text-gray-400 flex items-center gap-2">
                    <ClipboardList size={16} /> Tasks Management
                  </h4>
                  <span className="text-[10px] font-bold px-2 py-0.5 bg-blue-50 text-blue-900 rounded-full uppercase">
                    {viewingEmployee.tasks?.length || 0} Total
                  </span>
                </div>

                {/* Assignment Form */}
                <div className="bg-gray-50 rounded-3xl p-5 border border-gray-100 space-y-4">
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Task Title</label>
                    <input 
                      type="text" 
                      placeholder="What needs to be done?"
                      className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-2xl text-sm focus:ring-4 focus:ring-blue-500/5 outline-none font-medium"
                      value={newTaskTitle}
                      onChange={(e) => setNewTaskTitle(e.target.value)}
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Due Date</label>
                      <div className="relative">
                        <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={14} />
                        <input 
                          type="date"
                          className="w-full pl-9 pr-3 py-2 bg-white border border-gray-200 rounded-2xl text-[11px] font-bold text-gray-600 outline-none"
                          value={newTaskDueDate}
                          onChange={(e) => setNewTaskDueDate(e.target.value)}
                        />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Priority</label>
                      <select 
                        className="w-full px-3 py-2 bg-white border border-gray-200 rounded-2xl text-[11px] font-bold text-gray-600 outline-none appearance-none"
                        value={newTaskPriority}
                        onChange={(e) => setNewTaskPriority(e.target.value as any)}
                      >
                        <option value="Low">Low Priority</option>
                        <option value="Medium">Medium Priority</option>
                        <option value="High">High Priority</option>
                      </select>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <div className="flex-1">
                      <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Initial Status</label>
                      <select 
                        className="w-full px-3 py-2 bg-white border border-gray-200 rounded-2xl text-[11px] font-bold text-gray-600 outline-none appearance-none"
                        value={newTaskStatus}
                        onChange={(e) => setNewTaskStatus(e.target.value as any)}
                      >
                        <option value="Pending">Pending</option>
                        <option value="In Progress">In Progress</option>
                        <option value="Completed">Completed</option>
                      </select>
                    </div>
                    <button 
                      onClick={addTask}
                      className="mt-5 px-6 py-2 bg-blue-900 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-blue-800 transition-all shadow-sm active:scale-95 h-9"
                    >
                      Assign Task
                    </button>
                  </div>
                </div>

                {/* Tasks List */}
                <div className="space-y-3">
                  {(viewingEmployee.tasks || []).length === 0 ? (
                    <div className="text-center py-12 text-gray-400">
                      <p className="italic text-sm">No tasks assigned to this employee.</p>
                    </div>
                  ) : (
                    (viewingEmployee.tasks || []).sort((a,b) => a.status === 'Completed' ? 1 : -1).map(task => (
                      <div 
                        key={task.id} 
                        className={`p-4 rounded-2xl border transition-all flex items-center justify-between ${
                          task.status === 'Completed' ? 'bg-gray-50/50 border-gray-100 opacity-60' : 'bg-white border-gray-100 shadow-sm'
                        }`}
                      >
                        <div className="flex items-center gap-4">
                          <button 
                            onClick={() => toggleTaskStatus(task.id)}
                            className={`p-1 rounded-lg transition-colors ${
                              task.status === 'Completed' ? 'text-green-600 bg-green-50' : 
                              task.status === 'In Progress' ? 'text-blue-600 bg-blue-50' : 'text-gray-300 hover:text-blue-900'
                            }`}
                          >
                            {task.status === 'Completed' ? <CheckCircle size={24} /> : 
                             task.status === 'In Progress' ? <Clock size={24} className="animate-pulse" /> : 
                             <div className="w-6 h-6 border-2 border-gray-200 rounded-full" />}
                          </button>
                          <div>
                            <p className={`text-sm font-bold ${task.status === 'Completed' ? 'line-through text-gray-400' : 'text-blue-900'}`}>
                              {task.title}
                            </p>
                            <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-bold uppercase px-1.5 py-0.5 rounded-md ${
                                task.priority === 'High' ? 'bg-red-50 text-red-600' :
                                task.priority === 'Medium' ? 'bg-yellow-50 text-yellow-600' : 'bg-gray-100 text-gray-500'
                              }`}>
                                {task.priority}
                              </span>
                              <span className="text-[10px] text-gray-400 font-medium flex items-center gap-1">
                                <CalendarIcon size={10} /> {task.dueDate}
                              </span>
                            </div>
                          </div>
                        </div>
                        <span className={`text-[10px] font-bold uppercase tracking-tight ${
                           task.status === 'Completed' ? 'text-green-600' : 
                           task.status === 'In Progress' ? 'text-blue-600' : 'text-gray-400'
                        }`}>
                          {task.status}
                        </span>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>

            <div className="p-6 bg-gray-50 border-t border-gray-100">
              <button className="w-full py-3 bg-white border border-gray-200 text-blue-900 rounded-xl font-bold hover:bg-blue-50 transition-all text-sm uppercase tracking-widest shadow-sm">
                Generate Performance Report
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bulk Actions Toolbar */}
      {selectedIds.length > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-blue-900 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-8 animate-in fade-in slide-in-from-bottom-8 duration-300 z-50 ring-4 ring-white">
          <div className="flex items-center gap-3 border-r border-blue-800 pr-8">
            <div className="bg-white text-blue-900 w-6 h-6 rounded-lg flex items-center justify-center font-bold text-xs">
              {selectedIds.length}
            </div>
            <span className="text-sm font-bold uppercase tracking-widest text-blue-100">Selected</span>
          </div>

          <div className="flex items-center gap-4 relative">
            <button 
              onClick={handleBulkDeactivate}
              className="flex items-center gap-2 px-3 py-2 hover:bg-blue-800 rounded-xl transition-all text-xs font-bold uppercase tracking-wider"
            >
              <UserMinus size={16} />
              Deactivate
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowDeptMenu(!showDeptMenu)}
                className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-all text-xs font-bold uppercase tracking-wider ${showDeptMenu ? 'bg-white text-blue-900' : 'hover:bg-blue-800'}`}
              >
                <FolderInput size={16} />
                Assign to Dept
              </button>

              {showDeptMenu && (
                <div className="absolute bottom-full mb-4 left-0 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in zoom-in-95">
                  <div className="p-2">
                    <p className="text-[10px] font-bold text-gray-400 uppercase px-3 py-2 tracking-widest">Select Department</p>
                    {DEPARTMENTS.map(dept => (
                      <button
                        key={dept}
                        onClick={() => handleBulkAssignDept(dept)}
                        className="w-full text-left px-4 py-2 text-sm font-bold text-blue-900 hover:bg-blue-50 rounded-xl transition-colors"
                      >
                        {dept}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <button 
              className="flex items-center gap-2 px-3 py-2 hover:bg-blue-800 rounded-xl transition-all text-xs font-bold uppercase tracking-wider"
            >
              <CheckCircle2 size={16} />
              Verify Docs
            </button>
          </div>

          <button 
            onClick={() => setSelectedIds([])}
            className="p-2 hover:bg-blue-800 rounded-full transition-all text-blue-300 ml-4"
          >
            <X size={20} />
          </button>
        </div>
      )}
    </div>
  );
};

export default Employees;

import React, { useState } from 'react';
import { Search, Filter, MoreVertical, Plus, Trash2, UserMinus, FolderInput, CheckCircle2, X, ClipboardList, Clock, AlertCircle, CheckCircle, UserPlus, Mail, Briefcase, Building2, ShieldCheck, Calendar as CalendarIcon } from 'lucide-react';
import { MOCK_EMPLOYEES, DEPARTMENTS } from '../constants';
import { Employee, Task } from '../types';

const Employees: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [employees, setEmployees] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showDeptMenu, setShowDeptMenu] = useState(false);
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);

  // New employee form state
  const [newEmp, setNewEmp] = useState({
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    status: 'Active' as const
  });

  // Task assignment state
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.role.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.department.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredEmployees.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(filteredEmployees.map(e => e.id));
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleBulkDeactivate = () => {
    if (window.confirm(`Are you sure you want to deactivate ${selectedIds.length} selected employees?`)) {
      setEmployees(prev => prev.map(emp => 
        selectedIds.includes(emp.id) ? { ...emp, status: 'Inactive' as const } : emp
      ));
      setSelectedIds([]);
      alert("Selected employees have been deactivated.");
    }
  };

  const handleBulkAssignDept = (newDept: string) => {
    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, department: newDept } : emp
    ));
    setSelectedIds([]);
    setShowDeptMenu(false);
    alert(`Selected employees reassigned to ${newDept}.`);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEmp.name || !newEmp.role || !newEmp.email) {
      alert("Please fill in all required fields.");
      return;
    }

    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: []
    };

    setEmployees([employee, ...employees]);
    setIsAddingEmployee(false);
    setNewEmp({
      name: '',
      role: '',
      department: DEPARTMENTS[0],
      email: '',
      status: 'Active'
    });
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;

    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };

    const updatedEmployees = employees.map(emp => {
      if (emp.id === viewingEmployee.id) {
        const updatedTasks = [...(emp.tasks || []), newTask];
        const updatedEmp = { ...emp, tasks: updatedTasks };
        setViewingEmployee(updatedEmp);
        return updatedEmp;
      }
      return emp;
    });

    setEmployees(updatedEmployees);
    setNewTaskTitle('');
    // Reset to defaults
    setNewTaskStatus('Pending');
    setNewTaskPriority('Medium');
    setNewTaskDueDate(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  };

  const toggleTaskStatus = (taskId: string) => {
    if (!viewingEmployee) return;

    const taskToUpdate = viewingEmployee.tasks?.find(t => t.id === taskId);
    if (!taskToUpdate) return;

    const nextStatusMap: Record<string, Task['status']> = {
      'Pending': 'In Progress',
      'In Progress': 'Completed',
      'Completed': 'Pending'
    };

    const nextStatus = nextStatusMap[taskToUpdate.status];

    if (nextStatus === 'Completed') {
      const confirmed = window.confirm(`Are you sure you want to mark the task "${taskToUpdate.title}" as completed?`);
      if (!confirmed) return;
    }

    const updatedEmployees = employees.map(emp => {
      if (emp.id === viewingEmployee.id) {
        const updatedTasks = (emp.tasks || []).map(task => {
          if (task.id === taskId) {
            return { ...task, status: nextStatus };
          }
          return task;
        });
        const updatedEmp = { ...emp, tasks: updatedTasks };
        setViewingEmployee(updatedEmp);
        return updatedEmp;
      }
      return emp;
    });

    setEmployees(updatedEmployees);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Employee Directory</h1>
          <p className="text-gray-500">Manage organizational members and perform bulk actions.</p>
        </div>
        <button 
          onClick={() => setIsAddingEmployee(true)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-900 text-white rounded-xl font-medium hover:bg-blue-800 shadow-sm transition-all active:scale-95"
        >
          <Plus size={18} /> Add Employee
        </button>
      </header>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by name, role, or department..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-900/30 transition-all shadow-sm font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button className="flex items-center gap-2 px-4 py-3 bg-white border border-gray-200 rounded-xl text-gray-600 hover:bg-gray-50 shadow-sm font-bold text-xs uppercase tracking-widest">
          <Filter size={18} /> Filters
        </button>
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100">
                <th className="px-6 py-4 w-10">
                  <input 
                    type="checkbox" 
                    className="w-4 h-4 rounded border-gray-300 text-blue-900 focus:ring-blue-900 accent-blue-900 cursor-pointer"
                    checked={selectedIds.length > 0 && selectedIds.length === filteredEmployees.length}
                    ref={el => { if (el) el.indeterminate = selectedIds.length > 0 && selectedIds.length < filteredEmployees.length; }}
                    onChange={toggleSelectAll}
                  />
                </th>
                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Employee</th>
                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Role & Dept</th>
                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Tasks</th>
                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredEmployees.map((emp) => (
                <tr 
                  key={emp.id} 
                  className={`hover:bg-blue-50/30 transition-colors group cursor-pointer ${selectedIds.includes(emp.id) ? 'bg-blue-50/50' : ''}`}
                  onClick={() => setViewingEmployee(emp)}
                >
                  <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                    <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-gray-300 text-blue-900 focus:ring-blue-900 accent-blue-900 cursor-pointer"
                      checked={selectedIds.includes(emp.id)}
                      onChange={() => toggleSelect(emp.id)}
                    />
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-3">
                      <img src={emp.avatar} alt={emp.name} className="w-10 h-10 rounded-xl object-cover border border-gray-100 shadow-sm" />
                      <div>
                        <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                        <p className="text-[11px] text-gray-400 font-medium">{emp.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <p className="text-sm font-semibold text-gray-700">{emp.role}</p>
                    <p className="text-[11px] text-blue-900/50 font-bold uppercase tracking-tight">{emp.department}</p>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`px-2 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
                      emp.status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
                      emp.status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
                      'bg-gray-50 text-gray-700 border-gray-200'
                    }`}>
                      {emp.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      <div className="w-16 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-blue-600 transition-all" 
                          style={{ width: `${emp.tasks?.length ? (emp.tasks.filter(t => t.status === 'Completed').length / emp.tasks.length) * 100 : 0}%` }}
                        ></div>
                      </div>
                      <span className="text-[10px] font-bold text-gray-400 uppercase">
                        {emp.tasks?.filter(t => t.status === 'Completed').length || 0}/{emp.tasks?.length || 0}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right" onClick={(e) => e.stopPropagation()}>
                    <button className="p-2 hover:bg-white hover:shadow-sm border border-transparent hover:border-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all">
                      <MoreVertical size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Employee Slide-over */}
      {isAddingEmployee && (
        <div className="fixed inset-0 z-[70] overflow-hidden">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setIsAddingEmployee(false)} />
          <div className="absolute inset-y-0 right-0 max-w-md w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-white/10 rounded-xl">
                  <UserPlus size={20} />
                </div>
                <div>
                  <h2 className="text-lg font-bold">New Personnel</h2>
                  <p className="text-[10px] text-blue-200 uppercase font-bold tracking-widest">Srinidhi Associates Registry</p>
                </div>
              </div>
              <button onClick={() => setIsAddingEmployee(false)} className="p-2 hover:bg-white/10 rounded-xl transition-all">
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleAddEmployee} className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar">
              <div className="space-y-4">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Full Name</label>
                  <div className="relative">
                    <Plus className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                    <input 
                      autoFocus
                      type="text" 
                      required
                      placeholder="e.g. Robert Downey"
                      className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-medium"
                      value={newEmp.name}
                      onChange={e => setNewEmp({...newEmp, name: e.target.value})}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Professional Email</label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                    <input 
                      type="email" 
                      required
                      placeholder="name@srinidhi.com"
                      className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-medium"
                      value={newEmp.email}
                      onChange={e => setNewEmp({...newEmp, email: e.target.value})}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Position</label>
                    <div className="relative">
                      <Briefcase className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                      <input 
                        type="text" 
                        required
                        placeholder="e.g. Lead Analyst"
                        className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-medium text-sm"
                        value={newEmp.role}
                        onChange={e => setNewEmp({...newEmp, role: e.target.value})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Department</label>
                    <div className="relative">
                      <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                      <select 
                        className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-medium text-sm appearance-none"
                        value={newEmp.department}
                        onChange={e => setNewEmp({...newEmp, department: e.target.value})}
                      >
                        {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Initial Status</label>
                  <div className="relative">
                    <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={16} />
                    <select 
                      className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-medium text-sm appearance-none"
                      value={newEmp.status}
                      onChange={e => setNewEmp({...newEmp, status: e.target.value as any})}
                    >
                      <option value="Active">Active</option>
                      <option value="On Leave">On Leave</option>
                      <option value="Inactive">Inactive</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="pt-6">
                <button 
                  type="submit"
                  className="w-full py-4 bg-blue-900 text-white rounded-2xl font-bold hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/10 active:scale-95 flex items-center justify-center gap-2"
                >
                  <Plus size={20} /> Register Employee
                </button>
                <button 
                  type="button"
                  onClick={() => setIsAddingEmployee(false)}
                  className="w-full mt-3 py-3 text-gray-400 font-bold uppercase text-[10px] tracking-widest hover:text-gray-600 transition-colors"
                >
                  Discard Changes
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Employee Detail Slide-over */}
      {viewingEmployee && (
        <div className="fixed inset-0 z-[60] overflow-hidden">
          <div className="absolute inset-0 bg-black/20 backdrop-blur-sm" onClick={() => setViewingEmployee(null)} />
          <div className="absolute inset-y-0 right-0 max-w-lg w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white">
              <h2 className="text-xl font-bold text-blue-900">Employee Details</h2>
              <button onClick={() => setViewingEmployee(null)} className="p-2 hover:bg-gray-100 rounded-xl transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 no-scrollbar space-y-8">
              <div className="flex items-center gap-6">
                <img src={viewingEmployee.avatar} className="w-24 h-24 rounded-3xl object-cover shadow-lg border-2 border-white" alt="" />
                <div>
                  <h3 className="text-2xl font-bold text-blue-900">{viewingEmployee.name}</h3>
                  <p className="text-gray-500 font-medium">{viewingEmployee.role}</p>
                  <p className="text-xs text-blue-900/40 font-bold uppercase tracking-widest mt-1">{viewingEmployee.department}</p>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-sm font-bold uppercase tracking-widest text-gray-400 flex items-center gap-2">
                    <ClipboardList size={16} /> Tasks Management
                  </h4>
                  <span className="text-[10px] font-bold px-2 py-0.5 bg-blue-50 text-blue-900 rounded-full uppercase">
                    {viewingEmployee.tasks?.length || 0} Total
                  </span>
                </div>

                {/* Assignment Form */}
                <div className="bg-gray-50 rounded-3xl p-5 border border-gray-100 space-y-4">
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Task Title</label>
                    <input 
                      type="text" 
                      placeholder="What needs to be done?"
                      className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-2xl text-sm focus:ring-4 focus:ring-blue-500/5 outline-none font-medium"
                      value={newTaskTitle}
                      onChange={(e) => setNewTaskTitle(e.target.value)}
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Due Date</label>
                      <div className="relative">
                        <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={14} />
                        <input 
                          type="date"
                          className="w-full pl-9 pr-3 py-2 bg-white border border-gray-200 rounded-2xl text-[11px] font-bold text-gray-600 outline-none"
                          value={newTaskDueDate}
                          onChange={(e) => setNewTaskDueDate(e.target.value)}
                        />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Priority</label>
                      <select 
                        className="w-full px-3 py-2 bg-white border border-gray-200 rounded-2xl text-[11px] font-bold text-gray-600 outline-none appearance-none"
                        value={newTaskPriority}
                        onChange={(e) => setNewTaskPriority(e.target.value as any)}
                      >
                        <option value="Low">Low Priority</option>
                        <option value="Medium">Medium Priority</option>
                        <option value="High">High Priority</option>
                      </select>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <div className="flex-1">
                      <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Initial Status</label>
                      <select 
                        className="w-full px-3 py-2 bg-white border border-gray-200 rounded-2xl text-[11px] font-bold text-gray-600 outline-none appearance-none"
                        value={newTaskStatus}
                        onChange={(e) => setNewTaskStatus(e.target.value as any)}
                      >
                        <option value="Pending">Pending</option>
                        <option value="In Progress">In Progress</option>
                        <option value="Completed">Completed</option>
                      </select>
                    </div>
                    <button 
                      onClick={addTask}
                      className="mt-5 px-6 py-2 bg-blue-900 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-blue-800 transition-all shadow-sm active:scale-95 h-9"
                    >
                      Assign Task
                    </button>
                  </div>
                </div>

                {/* Tasks List */}
                <div className="space-y-3">
                  {(viewingEmployee.tasks || []).length === 0 ? (
                    <div className="text-center py-12 text-gray-400">
                      <p className="italic text-sm">No tasks assigned to this employee.</p>
                    </div>
                  ) : (
                    (viewingEmployee.tasks || []).sort((a,b) => a.status === 'Completed' ? 1 : -1).map(task => (
                      <div 
                        key={task.id} 
                        className={`p-4 rounded-2xl border transition-all flex items-center justify-between ${
                          task.status === 'Completed' ? 'bg-gray-50/50 border-gray-100 opacity-60' : 'bg-white border-gray-100 shadow-sm'
                        }`}
                      >
                        <div className="flex items-center gap-4">
                          <button 
                            onClick={() => toggleTaskStatus(task.id)}
                            className={`p-1 rounded-lg transition-colors ${
                              task.status === 'Completed' ? 'text-green-600 bg-green-50' : 
                              task.status === 'In Progress' ? 'text-blue-600 bg-blue-50' : 
                              'text-gray-300 hover:text-blue-900'
                            }`}
                          >
                            {task.status === 'Completed' ? <CheckCircle size={24} /> : 
                             task.status === 'In Progress' ? <Clock size={24} className="animate-pulse" /> : 
                             <div className="w-6 h-6 border-2 border-gray-200 rounded-full" />}
                          </button>
                          <div>
                            <p className={`text-sm font-bold ${task.status === 'Completed' ? 'line-through text-gray-400' : 'text-blue-900'}`}>
                              {task.title}
                            </p>
                            <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-bold uppercase px-1.5 py-0.5 rounded-md ${
                                task.priority === 'High' ? 'bg-red-50 text-red-600' :
                                task.priority === 'Medium' ? 'bg-yellow-50 text-yellow-600' : 'bg-gray-100 text-gray-500'
                              }`}>
                                {task.priority}
                              </span>
                              <span className="text-[10px] text-gray-400 font-medium flex items-center gap-1">
                                <CalendarIcon size={10} /> {task.dueDate}
                              </span>
                            </div>
                          </div>
                        </div>
                        <span className={`text-[10px] font-bold uppercase tracking-tight ${
                           task.status === 'Completed' ? 'text-green-600' : 
                           task.status === 'In Progress' ? 'text-blue-600' : 'text-gray-400'
                        }`}>
                          {task.status}
                        </span>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>

            <div className="p-6 bg-gray-50 border-t border-gray-100">
              <button className="w-full py-3 bg-white border border-gray-200 text-blue-900 rounded-xl font-bold hover:bg-blue-50 transition-all text-sm uppercase tracking-widest shadow-sm">
                Generate Performance Report
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bulk Actions Toolbar */}
      {selectedIds.length > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-blue-900 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-8 animate-in fade-in slide-in-from-bottom-8 duration-300 z-50 ring-4 ring-white">
          <div className="flex items-center gap-3 border-r border-blue-800 pr-8">
            <div className="bg-white text-blue-900 w-6 h-6 rounded-lg flex items-center justify-center font-bold text-xs">
              {selectedIds.length}
            </div>
            <span className="text-sm font-bold uppercase tracking-widest text-blue-100">Selected</span>
          </div>

          <div className="flex items-center gap-4 relative">
            <button 
              onClick={handleBulkDeactivate}
              className="flex items-center gap-2 px-3 py-2 hover:bg-blue-800 rounded-xl transition-all text-xs font-bold uppercase tracking-wider"
            >
              <UserMinus size={16} />
              Deactivate
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowDeptMenu(!showDeptMenu)}
                className={`flex items-center gap-2 px-3 py-2 rounded-xl transition-all text-xs font-bold uppercase tracking-wider ${showDeptMenu ? 'bg-white text-blue-900' : 'hover:bg-blue-800'}`}
              >
                <FolderInput size={16} />
                Assign to Dept
              </button>

              {showDeptMenu && (
                <div className="absolute bottom-full mb-4 left-0 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in zoom-in-95">
                  <div className="p-2">
                    <p className="text-[10px] font-bold text-gray-400 uppercase px-3 py-2 tracking-widest">Select Department</p>
                    {DEPARTMENTS.map(dept => (
                      <button
                        key={dept}
                        onClick={() => handleBulkAssignDept(dept)}
                        className="w-full text-left px-4 py-2 text-sm font-bold text-blue-900 hover:bg-blue-50 rounded-xl transition-colors"
                      >
                        {dept}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <button 
              className="flex items-center gap-2 px-3 py-2 hover:bg-blue-800 rounded-xl transition-all text-xs font-bold uppercase tracking-wider"
            >
              <CheckCircle2 size={16} />
              Verify Docs
            </button>
          </div>

          <button 
            onClick={() => setSelectedIds([])}
            className="p-2 hover:bg-blue-800 rounded-full transition-all text-blue-300 ml-4"
          >
            <X size={20} />
          </button>
        </div>
      )}
    </div>
  );
};

