                            <button 
                              onClick={() => setReassigningTaskId(null)}
                              className="w-full mt-2 py-1 text-[9px] font-bold uppercase tracking-widest text-gray-400 hover:text-gray-600 transition-colors"
                            >
                              Cancel
                            </button>
                          </div>
                        )}
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

