                  <div className="space-y-3">
                    {(viewingEmployee.tasks || []).length === 0 ? (
                      <div className="text-center py-12 text-gray-400 italic text-sm">No tasks assigned.</div>
                    ) : (
                      (viewingEmployee.tasks || [])
                        .filter(t => t.title.toLowerCase().includes(taskSearchTerm.toLowerCase()))
                        .sort((a,b) => a.status === 'Completed' ? 1 : -1)
                        .map(task => (
                        <div 
