                <div className="p-2.5 bg-white/10 rounded-2xl"><UserPlus size={24} /></div>
                <div>
                  <h2 className="text-xl font-bold">New Personnel</h2>
                  <p className="text-[10px] text-blue-200 uppercase font-black tracking-[0.2em] mt-0.5">Registry Onboarding</p>
                </div>
