const Documents: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([
    { 
      id: 'doc-1', 
      name: 'Aadhar Card', 
      type: 'Identification', 
      uploadDate: '2023-08-15', 
      status: 'Verified',
