        { status: 'Pending', timestamp: 'Aug 15, 2023, 09:30 AM' },
        { status: 'Verified', timestamp: 'Aug 16, 2023, 02:15 PM' }
      ]
    },
    { 
      id: 'doc-2', 
      name: 'Degree Certificate', 
      type: 'Education', 
      uploadDate: '2023-08-16', 
      status: 'Verified',
      statusHistory: [
        { status: 'Pending', timestamp: 'Aug 16, 2023, 11:00 AM' },
        { status: 'Verified', timestamp: 'Aug 17, 2023, 10:45 AM' }
      ]
    },
    { 
      id: 'doc-3', 
      name: 'Previous Salary Slips', 
      type: 'Experience', 
      uploadDate: '2024-01-10', 
      status: 'Pending',
      statusHistory: [
        { status: 'Pending', timestamp: 'Jan 10, 2024, 04:20 PM' }
      ]
    },
