  const [isUploading, setIsUploading] = useState(false);
  const [expandedDocId, setExpandedDocId] = useState<string | null>(null);
  const [editingDocId, setEditingDocId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editType, setEditType] = useState('');

  const handleUpload = () => {
    setIsUploading(true);
    // Simulate upload delay
    setTimeout(() => {
      const now = new Date();
      // Format: MMM DD, YYYY, hh:mm AM/PM
      const timestamp = now.toLocaleString('en-US', { 
        month: 'short', 
        day: '2-digit', 
        year: 'numeric', 
        hour: '2-digit', 
        minute: '2-digit', 
        hour12: true 
      });

      const newDoc: Document = {
        id: `doc-${Date.now()}`,
        name: 'Untitled Document',
        type: 'Misc',
        uploadDate: now.toISOString().split('T')[0],
        status: 'Pending',
        statusHistory: [
          { status: 'Pending', timestamp }
        ]
      };
      setDocuments([newDoc, ...documents]);
      setIsUploading(false);
    }, 1500);
  };

  const toggleHistory = (docId: string) => {
    setExpandedDocId(expandedDocId === docId ? null : docId);
  };

  const startEditing = (doc: Document) => {
    setEditingDocId(doc.id);
    setEditName(doc.name);
    setEditType(doc.type);
  };

  const cancelEditing = () => {
    setEditingDocId(null);
    setEditName('');
    setEditType('');
  };

  const saveEdit = (docId: string) => {
    if (!editName.trim()) return;
    setDocuments(prev => prev.map(doc => 
      doc.id === docId ? { ...doc, name: editName, type: editType } : doc
    ));
    setEditingDocId(null);
  };

  const deleteDocument = (docId: string) => {
    if (window.confirm('Are you sure you want to delete this document from your records?')) {
      setDocuments(prev => prev.filter(d => d.id !== docId));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900">Document Repository</h1>
          <p className="text-gray-500 font-medium">Manage and track the verification status of your credentials.</p>
        </div>
        <div className="flex gap-3">
          <input 
            type="file" 
            id="file-upload" 
            className="hidden" 
            onChange={handleUpload}
          />
          <label 
            htmlFor="file-upload"
            className="cursor-pointer flex items-center gap-2 px-6 py-3 bg-blue-900 text-white rounded-xl font-bold hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95"
          >
            {isUploading ? <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin"></div> : <Upload size={18} />}
            Upload Document
          </label>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {documents.map(doc => (
          <div key={doc.id} className="flex flex-col h-fit">
            <div className={`bg-white rounded-2xl border transition-all duration-300 shadow-sm hover:border-blue-200 overflow-hidden ${expandedDocId === doc.id ? 'ring-2 ring-blue-900/5' : 'border-gray-100'}`}>
              <div className="p-6">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-3 bg-blue-50 text-blue-900 rounded-xl">
                    <FileText size={24} />
                  </div>
                  <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest border ${
                    doc.status === 'Verified' 
                      ? 'bg-green-50 text-green-700 border-green-100' 
                      : 'bg-yellow-50 text-yellow-700 border-yellow-100'
                  }`}>
                    {doc.status}
                  </span>
                </div>

                {editingDocId === doc.id ? (
                  <div className="space-y-3 mb-4 animate-in fade-in zoom-in-95 duration-200">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Document Name</label>
                      <input 
                        type="text"
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        className="w-full px-4 py-2 bg-gray-50 border border-blue-100 rounded-xl outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white font-bold text-blue-900 text-sm"
                        autoFocus
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Category</label>
                      <select 
                        value={editType}
                        onChange={(e) => setEditType(e.target.value)}
                        className="w-full px-4 py-2 bg-gray-50 border border-blue-100 rounded-xl outline-none font-bold text-blue-900 text-xs appearance-none cursor-pointer"
                      >
                        <option value="Identification">Identification</option>
                        <option value="Education">Education</option>
                        <option value="Experience">Experience</option>
                        <option value="Address Proof">Address Proof</option>
                        <option value="Misc">Misc</option>
                      </select>
                    </div>
                    <div className="flex gap-2">
                      <button 
                        onClick={() => saveEdit(doc.id)}
                        className="flex-1 py-2.5 bg-blue-900 text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-blue-800 transition-all flex items-center justify-center gap-2"
                      >
                        <Save size={14} /> Save Changes
                      </button>
                      <button 
                        onClick={cancelEditing}
                        className="px-4 py-2.5 bg-gray-100 text-gray-400 rounded-xl hover:bg-gray-200 transition-all"
                      >
                        <CloseIcon size={14} />
                      </button>
                    </div>
                  </div>
                ) : (
                  <>
                    <h3 className="font-bold text-lg truncate mb-1 text-blue-900">{doc.name}</h3>
                    <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mb-4">{doc.type}</p>
                  </>
                )}

                <div className="flex items-center justify-between pt-4 border-t border-gray-50 mt-4">
                  <div className="flex items-center gap-4">
                    <div className="flex items-center gap-1.5 text-gray-400">
                      <Clock size={14} />
                      <span className="text-[10px] font-bold uppercase tracking-tight">{doc.uploadDate}</span>
                    </div>
                    <button 
                      onClick={() => toggleHistory(doc.id)}
                      aria-expanded={expandedDocId === doc.id}
                      className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest transition-all ${
                        expandedDocId === doc.id ? 'text-blue-900' : 'text-gray-400 hover:text-blue-900'
                      }`}
                    >
                      <History size={14} />
                      History
                      <ChevronDown size={12} className={`transition-transform duration-300 ${expandedDocId === doc.id ? 'rotate-180' : ''}`} />
                    </button>
                  </div>
                  <div className="flex gap-1">
                    <button 
                      onClick={() => startEditing(doc)}
                      className="p-2 text-gray-300 hover:text-blue-900 hover:bg-blue-50 rounded-lg transition-all"
                      title="Edit details"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => deleteDocument(doc.id)}
                      className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                      title="Delete document"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              </div>

              {/* Verification Status History Section */}
              {expandedDocId === doc.id && (
                <div className="bg-gray-50/50 border-t border-gray-100 p-6 animate-in slide-in-from-top-2 duration-300">
                  <div className="flex items-center justify-between mb-4">
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Verification Journey</h4>
                    <span className="text-[9px] font-bold text-blue-900 bg-blue-50 px-2 py-0.5 rounded uppercase">{doc.statusHistory?.length} Records</span>
                  </div>

                  <div className="space-y-6 relative ml-1">
                    {/* Vertical Timeline Thread */}
                    <div className="absolute left-[7px] top-2 bottom-2 w-[2px] bg-gray-200"></div>

                    {doc.statusHistory?.map((entry, idx) => (
                      <div key={idx} className="flex gap-4 relative z-10">
                        <div className={`w-4 h-4 rounded-full border-2 border-white shadow-sm mt-0.5 flex-shrink-0 flex items-center justify-center ${
                          entry.status === 'Verified' ? 'bg-green-500' : 'bg-yellow-500'
                        }`}>
                          {entry.status === 'Verified' ? <ShieldCheck size={8} className="text-white" /> : <AlertCircle size={8} className="text-white" />}
