                        <div className="flex-1">
                          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1">
                            <p className="text-xs font-bold text-blue-900">
                              Status: <span className={entry.status === 'Verified' ? 'text-green-600' : 'text-yellow-600'}>{entry.status}</span>
                            </p>
                            <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tight flex items-center gap-1">
                              <Clock size={10} /> {entry.timestamp}
                            </p>
                          </div>
                          <p className="text-[10px] text-gray-500 mt-0.5 italic">
                            {entry.status === 'Verified' 
                              ? 'Document successfully validated by HR Compliance.' 
                              : 'Initial upload received. Awaiting review.'}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Guidelines Footer */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 flex flex-col md:flex-row items-center gap-6 shadow-sm">
        <div className="w-16 h-16 bg-blue-900 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-blue-900/20 flex-shrink-0">
          <ShieldCheck size={32} />
