        <button className="px-6 py-3 bg-gray-50 text-blue-900 rounded-xl font-black text-xs uppercase tracking-widest border border-gray-100 hover:bg-gray-100 transition-all active:scale-95">
          Privacy Policy
        </button>
      </div>
    </div>
  );
};

