                           <input 
                            type="checkbox" 
                            className="w-3.5 h-3.5 rounded border-gray-300 text-blue-900 accent-blue-900"
                            checked={selectedIds.includes(emp.id)}
                            onChange={() => setSelectedIds(prev => prev.includes(emp.id) ? prev.filter(i => i !== emp.id) : [...prev, emp.id])}
