      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };
    setNotifications(prev => [newNotif, ...prev]);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const userNotifications = notifications.filter(n => n.userId === user?.id || (user?.role === 'HR'));
  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const currentEmployee = employees.find(e => e.id === user?.id);

  const handleUpdateTaskStatus = (taskId: string, status: Task['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === user?.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status } : t)
        };
      }
      return emp;
    }));
  };

  const renderContent = () => {
    if (!user) return null;
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'tasks': return currentEmployee ? <MyTasks employee={currentEmployee} onUpdateTask={handleUpdateTaskStatus} /> : <Dashboard />;
      case 'profiles': return user.role === 'HR' ? <Employees employees={employees} setEmployees={setEmployees} addNotification={addNotification} /> : <Dashboard />;
      case 'recruitment': return user.role === 'HR' ? <Recruitment /> : <Dashboard />;
      case 'performance': return <Performance />;
      case 'attendance': return <Attendance user={user} />;
      case 'documents': return (
        <Documents 
          user={user} 
          allEmployees={employees} 
          setEmployees={setEmployees} 
          addNotification={addNotification}
        />
      );
      case 'security': return <Security user={user} employees={employees} setEmployees={setEmployees} />;
      default: return <Dashboard />;
    }
  };

  // If user is not logged in, show the Login page
  if (!user) {
    return <Login onLogin={handleLogin} employees={employees} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} user={user} />

      <main className="flex-1 md:ml-64 p-4 md:p-8">
        <nav className="flex items-center justify-between mb-8 sticky top-0 bg-gray-50/80 backdrop-blur-md z-10 py-4">
          <div className="md:hidden flex items-center gap-2">
             <Logo className="w-8 h-8" />
             <span className="font-bold text-sm tracking-tight text-[#1e3a8a] uppercase">Srinidhi</span>
          </div>

          <div className="hidden md:flex items-center bg-white rounded-xl border border-gray-200 px-4 py-2 w-96 shadow-sm focus-within:ring-2 focus-within:ring-blue-500/20 transition-all">
            <Search className="text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Quick search records..." 
              className="bg-transparent border-none outline-none text-sm ml-2 w-full font-medium"
            />
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <button 
                onClick={() => {
                  setShowNotifications(!showNotifications);
                  if (!showNotifications) markAllAsRead();
                }}
                className="p-2 text-gray-400 hover:bg-white hover:text-blue-900 rounded-xl transition-all relative"
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-gray-50"></span>
                )}
              </button>

              {showNotifications && (
                <div className="absolute right-0 mt-4 w-80 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
                    <h3 className="font-bold text-sm">Notifications</h3>
                    <button onClick={() => setShowNotifications(false)}><X size={16} /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto no-scrollbar">
                    {userNotifications.length === 0 ? (
                      <div className="p-8 text-center text-gray-400 text-sm italic">No recent notifications.</div>
                    ) : (
                      userNotifications.map(notif => (
                        <div key={notif.id} className="p-4 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                          <p className="text-sm font-bold text-blue-900">{notif.title}</p>
                          <p className="text-xs text-gray-600 mt-1">{notif.message}</p>
                          <div className="flex items-center gap-1 text-[10px] text-gray-400 mt-2 uppercase font-bold">
                            <Clock size={10} /> {notif.timestamp}
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  <div className="p-3 text-center bg-gray-50">
                    <button className="text-[10px] font-bold uppercase tracking-widest text-blue-900 hover:underline">View All Notifications</button>
                  </div>
                </div>
              )}
            </div>

            <button onClick={handleLogout} className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-xl transition-all"><LogOut size={20} /></button>
            <div className="h-8 w-[1px] bg-gray-200 mx-1"></div>
            <div className="flex items-center gap-3 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold group-hover:text-blue-900 transition-colors uppercase tracking-tight">{user.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-blue-900 flex items-center justify-center text-white border-2 border-white shadow-md overflow-hidden">
                <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
              </div>
            </div>
          </div>
        </nav>

        <div className="max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { 
  Upload, 
  FileText, 
  Clock, 
  Trash2, 
  ChevronDown, 
  History, 
  Edit2, 
  Save, 
  ShieldCheck, 
  AlertCircle, 
  TriangleAlert, 
  Loader2, 
  FileUp, 
  X, 
  FileSearch,
  Search,
  UserCircle,
  Hash,
  Filter
} from 'lucide-react';
import { Document, Employee, User } from '../types';

interface DocumentsProps {
  user: User;
  allEmployees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

interface UploadingFile {
  id: string;
  name: string;
  progress: number;
  size: string;
}

const Documents: React.FC<DocumentsProps> = ({ user, allEmployees, setEmployees, addNotification }) => {
  const isHR = user.role === 'HR';

  // States for search and filter
  const [searchTerm, setSearchTerm] = useState('');
  const [personnelSearch, setPersonnelSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Verified' | 'Pending'>('All');

  // UI States
  const [uploadQueue, setUploadQueue] = useState<UploadingFile[]>([]);
  const [expandedDocId, setExpandedDocId] = useState<string | null>(null);
  const [editingDocId, setEditingDocId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editType, setEditType] = useState('');
  const [docToDelete, setDocToDelete] = useState<{ docId: string; ownerId: string } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Computed: Get all documents with owner information if HR, or just own documents if Employee
  const processedDocs = useMemo(() => {
    let list: Array<Document & { ownerName: string; ownerId: string; ownerEmployeeId: string }> = [];

    if (isHR) {
      allEmployees.forEach(emp => {
        (emp.documents || []).forEach(doc => {
          list.push({
            ...doc,
            ownerName: emp.name,
            ownerId: emp.id,
            ownerEmployeeId: emp.employeeId
          });
        });
      });
    } else {
      const currentEmp = allEmployees.find(e => e.id === user.id);
      if (currentEmp) {
        (currentEmp.documents || []).forEach(doc => {
          list.push({
            ...doc,
            ownerName: currentEmp.name,
            ownerId: currentEmp.id,
            ownerEmployeeId: currentEmp.employeeId
          });
        });
      }
    }

    // Apply filters
    return list.filter(doc => {
      const matchesSearch = doc.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesPersonnel = isHR ? (
        doc.ownerName.toLowerCase().includes(personnelSearch.toLowerCase()) ||
        doc.ownerEmployeeId.toLowerCase().includes(personnelSearch.toLowerCase())
      ) : true;
      const matchesStatus = statusFilter === 'All' || doc.status === statusFilter;

      return matchesSearch && matchesPersonnel && matchesStatus;
    });
  }, [allEmployees, isHR, user.id, searchTerm, personnelSearch, statusFilter]);

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const selectedFiles = Array.from(files);

    selectedFiles.forEach(file => {
      const uploadId = `upload-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const newUpload: UploadingFile = {
        id: uploadId,
        name: file.name,
        progress: 0,
        size: formatFileSize(file.size)
      };

      setUploadQueue(prev => [...prev, newUpload]);

      let progress = 0;
      const interval = setInterval(() => {
        progress += Math.floor(Math.random() * 15) + 5;
        if (progress >= 100) {
          progress = 100;
          clearInterval(interval);

          setTimeout(() => {
            const now = new Date();
            const timestamp = now.toLocaleString('en-US', { month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true });

            const newDoc: Document = {
              id: `doc-${Date.now()}-${Math.random()}`,
              name: file.name.split('.').slice(0, -1).join('.') || file.name,
              type: 'Misc',
              uploadDate: now.toISOString().split('T')[0],
              status: 'Pending',
              statusHistory: [{ status: 'Pending', timestamp }]
            };

            setEmployees(prev => prev.map(emp => 
              emp.id === user.id ? { ...emp, documents: [newDoc, ...(emp.documents || [])] } : emp
            ));

            setUploadQueue(prev => prev.filter(u => u.id !== uploadId));
          }, 500);
        }

        setUploadQueue(prev => prev.map(u => u.id === uploadId ? { ...u, progress } : u));
      }, 300);
    });

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const toggleHistory = (docId: string) => {
    setExpandedDocId(expandedDocId === docId ? null : docId);
  };

  const startEditing = (doc: Document) => {
    setEditingDocId(doc.id);
    setEditName(doc.name);
    setEditType(doc.type);
  };

  const saveEdit = (docId: string, ownerId: string) => {
    if (!editName.trim()) return;
    setEmployees(prev => prev.map(emp => {
      if (emp.id === ownerId) {
        return {
          ...emp,
          documents: (emp.documents || []).map(d => 
            d.id === docId ? { ...d, name: editName, type: editType } : d
          )
        };
      }
      return emp;
    }));
    setEditingDocId(null);
  };

  const verifyDoc = (docId: string, ownerId: string) => {
    if (!isHR) return;
    const now = new Date();
    const timestamp = now.toLocaleString('en-US', { month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true });

    setEmployees(prev => prev.map(emp => {
      if (emp.id === ownerId) {
        const docName = emp.documents?.find(d => d.id === docId)?.name;
        addNotification(ownerId, "Document Verified", `HR has verified your document: "${docName}".`);
        return {
          ...emp,
          documents: (emp.documents || []).map(d => {
            if (d.id === docId) {
              const history = d.statusHistory || [];
              return {
                ...d,
                status: 'Verified' as const,
                statusHistory: [...history, { status: 'Verified' as const, timestamp }]
              };
            }
            return d;
          })
        };
      }
      return emp;
    }));
  };

  const finalizeDelete = () => {
    if (docToDelete) {
      const { docId, ownerId } = docToDelete;
      setEmployees(prev => prev.map(emp => {
        if (emp.id === ownerId) {
          return {
            ...emp,
            documents: (emp.documents || []).filter(d => d.id !== docId)
          };
        }
        return emp;
      }));
      setDocToDelete(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900 uppercase tracking-tighter">
            {isHR ? 'Document Management' : 'Document Registry'}
          </h1>
          <p className="text-gray-500 font-medium">
            {isHR ? 'Audit and verify personnel credentials organization-wide.' : 'Tracking the verification status of your professional credentials.'}
          </p>
        </div>
        {!isHR && (
          <div className="flex gap-3">
            <input 
              type="file" 
              id="file-upload" 
              multiple
              className="hidden" 
              ref={fileInputRef}
              onChange={handleFileChange}
            />
            <label 
              htmlFor="file-upload"
              className="cursor-pointer flex items-center gap-2 px-6 py-3 bg-blue-900 text-white rounded-xl font-bold hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95 text-xs uppercase tracking-widest"
            >
              <Upload size={16} />
              Upload Records
            </label>
          </div>
        )}
      </header>

      {/* Control Bar */}
      <div className="flex flex-col xl:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by document name..." 
            className="w-full pl-12 pr-4 py-4 bg-white border border-gray-100 rounded-[2rem] shadow-sm outline-none focus:ring-4 focus:ring-blue-900/5 transition-all text-sm font-bold text-blue-900"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {isHR && (
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="relative flex-1 sm:w-64">
              <UserCircle className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Search by personnel..." 
                className="w-full pl-12 pr-4 py-4 bg-white border border-gray-100 rounded-[2rem] shadow-sm outline-none focus:ring-4 focus:ring-blue-900/5 transition-all text-sm font-bold text-blue-900"
                value={personnelSearch}
                onChange={(e) => setPersonnelSearch(e.target.value)}
              />
            </div>

            <div className="relative">
              <Filter className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
              <select 
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value as any)}
                className="pl-12 pr-10 py-4 bg-white border border-gray-100 rounded-[2rem] shadow-sm outline-none text-xs font-black uppercase tracking-widest appearance-none cursor-pointer text-blue-900"
              >
                <option value="All">All Statuses</option>
                <option value="Verified">Verified Only</option>
                <option value="Pending">Pending Audit</option>
              </select>
              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={14} />
            </div>
          </div>
        )}
      </div>

      {/* Upload Queue for Employees */}
      {!isHR && uploadQueue.length > 0 && (
        <div className="bg-white rounded-[2.5rem] border border-blue-100 p-8 shadow-sm animate-in slide-in-from-top-4 duration-500 overflow-hidden">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-sm font-black text-blue-900 uppercase tracking-widest flex items-center gap-2">
              <Loader2 size={16} className="animate-spin text-blue-600" /> Active Uploads
            </h2>
            <span className="text-[10px] font-bold text-blue-900 bg-blue-50 px-3 py-1 rounded-lg uppercase">
              {uploadQueue.length} {uploadQueue.length === 1 ? 'Transfer' : 'Transfers'}
            </span>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {uploadQueue.map(upload => (
              <div key={upload.id} className="p-4 bg-gray-50/50 rounded-2xl border border-gray-100 flex items-center gap-4 animate-in fade-in slide-in-from-left-2 duration-300">
                <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-sm text-blue-900 shrink-0"><FileUp size={20} /></div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-1.5">
                    <p className="text-xs font-bold text-blue-900 truncate pr-4">{upload.name}</p>
                    <span className="text-[10px] font-black text-blue-600 uppercase tracking-tighter shrink-0">{upload.progress}%</span>
                  </div>
                  <div className="h-1.5 w-full bg-blue-100/50 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-900 transition-all duration-300 ease-out" style={{ width: `${upload.progress}%` }} />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Documents Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {processedDocs.length === 0 ? (
          <div className="col-span-full py-20 bg-white rounded-[2.5rem] border border-dashed border-gray-200 text-center space-y-4">
            <div className="w-16 h-16 bg-gray-50 text-gray-200 rounded-full flex items-center justify-center mx-auto"><FileSearch size={32} /></div>
            <p className="text-gray-400 font-bold text-xs uppercase tracking-widest">No matching records found</p>
          </div>
        ) : (
          processedDocs.map(doc => (
            <div key={doc.id} className="flex flex-col h-fit">
              <div className={`bg-white rounded-[2.5rem] border transition-all duration-300 shadow-sm hover:border-blue-200 overflow-hidden ${expandedDocId === doc.id ? 'ring-4 ring-blue-900/5' : 'border-gray-100'}`}>
                <div className="p-8">
                  {isHR && (
                    <div className="mb-6 flex items-center gap-3 bg-gray-50 p-3 rounded-2xl border border-gray-100">
                      <div className="w-8 h-8 rounded-lg bg-blue-900 flex items-center justify-center text-[10px] font-black text-white">{doc.ownerName.charAt(0)}</div>
                      <div>
                        <p className="text-[10px] font-black text-blue-900 uppercase leading-none">{doc.ownerName}</p>
                        <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-1">{doc.ownerEmployeeId}</p>
                      </div>
                    </div>
                  )}

                  <div className="flex justify-between items-start mb-6">
                    <div className="p-3 bg-blue-50 text-blue-900 rounded-2xl"><FileText size={24} /></div>
                    <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest border ${
                      doc.status === 'Verified' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-yellow-50 text-yellow-700 border-yellow-100'
                    }`}>{doc.status}</span>
                  </div>

                  {editingDocId === doc.id ? (
                    <div className="space-y-4 mb-4 animate-in fade-in zoom-in-95 duration-200">
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Label</label>
                        <input type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-blue-100 rounded-xl font-bold text-blue-900 text-sm outline-none" autoFocus />
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => saveEdit(doc.id, doc.ownerId)} className="flex-1 py-3 bg-blue-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-800 transition-all flex items-center justify-center gap-2"><Save size={14} /> Save</button>
                        <button onClick={() => setEditingDocId(null)} className="px-4 py-3 bg-gray-100 text-gray-400 rounded-xl hover:bg-gray-200 transition-all"><X size={14} /></button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <h3 className="font-bold text-lg truncate mb-1 text-blue-900">{doc.name}</h3>
                      <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mb-6">{doc.type}</p>
                    </>
                  )}

                  <div className="flex items-center justify-between pt-6 border-t border-gray-50 mt-4">
                    <div className="flex items-center gap-4">
                      <div className="flex items-center gap-1.5 text-gray-300">
                        <Clock size={12} />
                        <span className="text-[9px] font-bold uppercase tracking-tight">{doc.uploadDate}</span>
                      </div>
                      <button onClick={() => toggleHistory(doc.id)} className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-widest transition-all ${expandedDocId === doc.id ? 'text-blue-900' : 'text-gray-400 hover:text-blue-900 underline underline-offset-4'}`}>
                        <History size={12} /> Logs
                      </button>
                    </div>
                    <div className="flex gap-1">
                      {isHR && doc.status !== 'Verified' && (
                        <button onClick={() => verifyDoc(doc.id, doc.ownerId)} className="p-2 text-green-500 hover:bg-green-50 rounded-lg transition-all" title="Verify Document"><ShieldCheck size={18}/></button>
                      )}
                      {!isHR && (
                        <button onClick={() => startEditing(doc)} className="p-2 text-gray-200 hover:text-blue-900 transition-all" title="Edit entry"><Edit2 size={16} /></button>
                      )}
                      {(isHR || doc.ownerId === user.id) && (
                        <button onClick={() => setDocToDelete({ docId: doc.id, ownerId: doc.ownerId })} className="p-2 text-gray-200 hover:text-red-500 transition-all" title="Delete entry"><Trash2 size={16} /></button>
                      )}
                    </div>
                  </div>
                </div>

                {/* History View */}
                {expandedDocId === doc.id && (
                  <div className="bg-blue-50/30 border-t border-gray-100 p-8 animate-in slide-in-from-top-4 duration-300">
                    <div className="flex items-center justify-between mb-6">
                      <h4 className="text-[10px] font-black text-blue-900/40 uppercase tracking-[0.2em]">Audit Log</h4>
                    </div>
                    <div className="space-y-6 relative ml-1">
                      <div className="absolute left-[7px] top-2 bottom-2 w-[2px] bg-blue-100"></div>
                      {(doc.statusHistory || []).length === 0 ? (
                        <div className="flex gap-4 relative z-10">
                          <div className="w-4 h-4 rounded-full border-2 border-white shadow-sm mt-0.5 bg-yellow-500 shrink-0" />
                          <div><p className="text-xs font-bold text-blue-900">Initial Upload</p><p className="text-[9px] text-gray-400 font-bold uppercase tracking-tight flex items-center gap-1 mt-0.5"><Clock size={10} /> {doc.uploadDate}</p></div>
                        </div>
                      ) : (
                        doc.statusHistory.map((entry, idx) => (
                          <div key={idx} className="flex gap-4 relative z-10">
                            <div className={`w-4 h-4 rounded-full border-2 border-white shadow-sm mt-0.5 flex-shrink-0 flex items-center justify-center ${entry.status === 'Verified' ? 'bg-green-500' : 'bg-yellow-500'}`}>
                              {entry.status === 'Verified' ? <ShieldCheck size={8} className="text-white" /> : <AlertCircle size={8} className="text-white" />}
                            </div>
                            <div className="flex-1">
                              <p className="text-xs font-bold text-blue-900">Status: <span className={entry.status === 'Verified' ? 'text-green-600' : 'text-yellow-600'}>{entry.status}</span></p>
                              <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tight flex items-center gap-1 mt-0.5"><Clock size={10} /> {entry.timestamp}</p>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Confirmation Modal */}
      {docToDelete && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-blue-900/20 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDocToDelete(null)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-w-sm w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-red-50 text-red-600 rounded-[2rem] flex items-center justify-center mb-8"><TriangleAlert size={40} /></div>
              <h2 className="text-2xl font-bold text-blue-900 mb-2 uppercase tracking-tighter">Confirm Deletion</h2>
              <p className="text-sm text-gray-400 mb-10 font-medium">This record will be permanently purged from the personnel file. This action is irreversible.</p>
              <div className="flex flex-col w-full gap-3">
                <button onClick={finalizeDelete} className="w-full py-5 bg-red-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-red-700 transition-all shadow-xl shadow-red-600/20 active:scale-95">Purge Record</button>
                <button onClick={() => setDocToDelete(null)} className="w-full py-5 bg-gray-50 text-gray-400 rounded-2xl font-black uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Documents;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Search, Filter, MoreVertical, Plus, Trash2, UserMinus, FolderInput, 
  CheckCircle2, X, ClipboardList, Clock, AlertCircle, CheckCircle, 
  UserPlus, Mail, Briefcase, Building2, ShieldCheck, 
  Calendar as CalendarIcon, UserRoundCheck, ArrowRightLeft, 
  Download, Upload, Snowflake, Power, UserCheck,
  LayoutList, LayoutGrid, Rows3, ChevronDown, ListChecks, Fingerprint, FileText, FileUp, Hash, UserCircle,
  Lock,
  Eye,
  EyeOff,
  ShieldAlert,
  KeyRound,
  History,
  AlertTriangle
} from 'lucide-react';
import { DEPARTMENTS } from '../constants';
import { Employee, Task, Document } from '../types';

interface EmployeesProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

type ViewMode = 'list' | 'grid' | 'compact';
type TaskFilterType = 'All' | 'No Tasks' | 'Has Tasks';

const Employees: React.FC<EmployeesProps> = ({ employees, setEmployees, addNotification }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [idFilter, setIdFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [taskFilter, setTaskFilter] = useState<TaskFilterType>('All');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [isUploadingDoc, setIsUploadingDoc] = useState(false);
  const employeeFileInputRef = useRef<HTMLInputElement>(null);

  // Slide-over specific task filtering state
  const [taskSearchTerm, setTaskSearchTerm] = useState('');

  // Form error state
  const [formError, setFormError] = useState<string | null>(null);

  // Admin password reset state
  const [adminResetPass, setAdminResetPass] = useState('');
  const [showAdminResetPass, setShowAdminResetPass] = useState(false);
  const [resetSuccess, setResetSuccess] = useState(false);

  const [showInitialPass, setShowInitialPass] = useState(false);
  const [newEmp, setNewEmp] = useState({
    employeeId: '',
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    password: '',
    status: 'Active' as const
  });

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  useEffect(() => {
    const handleClickOutside = () => setMenuOpenId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  // Reset task search when closing the slide-over
  useEffect(() => {
    if (!viewingEmployee) {
      setTaskSearchTerm('');
      setAdminResetPass('');
      setShowAdminResetPass(false);
      setResetSuccess(false);
    }
  }, [viewingEmployee]);

  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const idTerm = idFilter.toLowerCase();

    const matchesSearch = 
      emp.name.toLowerCase().includes(term) ||
      emp.role.toLowerCase().includes(term) ||
      emp.department.toLowerCase().includes(term) ||
      emp.email.toLowerCase().includes(term) ||
      emp.employeeId.toLowerCase().includes(term);

    const matchesId = !idFilter || emp.employeeId.toLowerCase().includes(idTerm);
    const matchesStatus = statusFilter === 'All' || emp.status === statusFilter;
    const matchesDept = deptFilter === 'All' || emp.department === deptFilter;

    const hasTasks = emp.tasks && emp.tasks.length > 0;
    const matchesTasks = 
      taskFilter === 'All' ? true :
      taskFilter === 'No Tasks' ? !hasTasks :
      taskFilter === 'Has Tasks' ? hasTasks : true;

    return matchesSearch && matchesId && matchesStatus && matchesDept && matchesTasks;
  });

  const handleUpdateStatus = (id: string, newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      emp.id === id ? { ...emp, status: newStatus } : emp
    ));
    addNotification(id, `Status Update: ${newStatus}`, `Your account access has been set to ${newStatus}.`);
    setMenuOpenId(null);
  };

  const handleBulkStatusUpdate = (newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, status: newStatus } : emp
    ));
    selectedIds.forEach(id => {
      addNotification(id, `Bulk Status Update`, `Your status was updated to ${newStatus} by HR.`);
    });
    setSelectedIds([]);
  };

  const handleBulkPasswordReset = () => {
    const newPass = prompt(`BULK CREDENTIAL RESET:\n\nEnter a new access token for the ${selectedIds.length} selected employees:`);
    if (!newPass) return;

    if (newPass.length < 6) {
      alert("Error: Password must be at least 6 characters.");
      return;
    }

    const confirmed = window.confirm(`Confirm bulk password reset for ${selectedIds.length} employees to: "${newPass}"?`);
    if (!confirmed) return;

    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, password: newPass } : emp
    ));

    selectedIds.forEach(id => {
      addNotification(
        id,
        "System Credential Reset",
        "HR has performed a bulk update of organization access tokens. Your new password has been set by the administrator."
      );
    });

    alert(`Success: Credentials for ${selectedIds.length} personnel have been updated.`);
    setSelectedIds([]);
  };

  const handleDownloadData = () => {
    const dataToExport = selectedIds.length > 0 
      ? employees.filter(e => selectedIds.includes(e.id))
      : employees;

    const dataStr = JSON.stringify(dataToExport, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `srinidhi_profiles_export_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    // 1. Format Validation: SA-XXX
    const idRegex = /^SA-\d{3}$/;
    if (!idRegex.test(newEmp.employeeId)) {
      setFormError("Employee ID must follow the format 'SA-XXX' (e.g., SA-005).");
      return;
    }

    // 2. Uniqueness Validation
    const isDuplicate = employees.some(emp => emp.employeeId === newEmp.employeeId);
    if (isDuplicate) {
      setFormError(`Employee ID '${newEmp.employeeId}' is already assigned to another profile.`);
      return;
    }

    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: [],
      documents: []
    };

    setEmployees([employee, ...employees]);
    setIsAddingEmployee(false);
    setNewEmp({ employeeId: '', name: '', role: '', department: DEPARTMENTS[0], email: '', password: '', status: 'Active' });
    setShowInitialPass(false);
    setFormError(null);
  };

  const handleAdminResetPassword = () => {
    if (!viewingEmployee || !adminResetPass.trim()) return;

    const confirmed = window.confirm(
      `ADMINISTRATIVE OVERRIDE WARNING:\n\n` +
      `You are about to force-reset the access token for ${viewingEmployee.name} (${viewingEmployee.employeeId}).\n\n` +
      `New Token: ${adminResetPass}\n\n` +
      `The personnel will be notified of this manual credential change. Proceed?`
    );

    if (!confirmed) return;

    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, password: adminResetPass } : emp
    ));

    addNotification(
      viewingEmployee.id,
      "Manual Credential Reset",
      "HR has manually updated your organization access token. Please contact your manager for the new credentials if you did not request this."
    );

    setResetSuccess(true);
    setTimeout(() => setResetSuccess(false), 3000);
    setAdminResetPass('');
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;

    const confirmAssignment = window.confirm(
      `Please verify the directive details:\n\n` +
      `Title: ${newTaskTitle}\n` +
      `Priority: ${newTaskPriority}\n` +
      `Due Date: ${newTaskDueDate}\n` +
      `Assigned to: ${viewingEmployee.name}\n\n` +
      `Is this information correct?`
    );

    if (!confirmAssignment) return;

    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };

    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, tasks: [...(emp.tasks || []), newTask] } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, tasks: [...(prev.tasks || []), newTask] } : null);

    addNotification(
      viewingEmployee.id, 
      "New Directive Assigned", 
      `HR has assigned a new directive: "${newTaskTitle}". Priority: ${newTaskPriority}. Due: ${newTaskDueDate}.`
    );

    setNewTaskTitle('');
  };

  const handleUpdateTaskStatus = (taskId: string, newStatus: Task['status']) => {
    if (!viewingEmployee) return;

    // Specific confirmation for 'In Progress' status
    if (newStatus === 'In Progress') {
      const confirmed = window.confirm(`Set directive "${viewingEmployee.tasks?.find(t => t.id === taskId)?.title}" to 'In Progress'? This confirms the personnel has started this workload.`);
      if (!confirmed) return;
    }

    setEmployees(prev => prev.map(emp => {
      if (emp.id === viewingEmployee.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
        };
      }
      return emp;
    }));

    setViewingEmployee(prev => {
      if (!prev) return null;
      return {
        ...prev,
        tasks: (prev.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
      };
    });

    addNotification(
      viewingEmployee.id,
      "Directive Status Updated",
      `The status of your directive has been updated to "${newStatus}" by HR.`
    );
  };

  const handleEmployeeFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !viewingEmployee) return;

    setIsUploadingDoc(true);
    // Simulate upload delay
    setTimeout(() => {
      const now = new Date();
      const timestamp = now.toLocaleString('en-US', { month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true });

      const newDoc: Document = {
        id: `edoc-${Date.now()}`,
        name: file.name,
        type: file.type.split('/')[1]?.toUpperCase() || 'FILE',
        uploadDate: now.toISOString().split('T')[0],
        status: 'Pending',
        statusHistory: [{ status: 'Pending', timestamp }]
      };

      setEmployees(prev => prev.map(emp => 
        emp.id === viewingEmployee.id ? { ...emp, documents: [...(emp.documents || []), newDoc] } : emp
      ));
      setViewingEmployee(prev => prev ? { ...prev, documents: [...(prev.documents || []), newDoc] } : null);

      addNotification(
        viewingEmployee.id,
        "New Document Uploaded",
        `HR has uploaded a new document to your record: "${file.name}".`
      );

      setIsUploadingDoc(false);
      if (employeeFileInputRef.current) employeeFileInputRef.current.value = '';
    }, 1200);
  };

  const verifyEmployeeDoc = (docId: string) => {
    if (!viewingEmployee) return;

    const now = new Date();
    const timestamp = now.toLocaleString('en-US', { month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true });

    setEmployees(prev => prev.map(emp => {
      if (emp.id === viewingEmployee.id) {
        const updatedDocs = (emp.documents || []).map(doc => {
          if (doc.id === docId) {
            const history = doc.statusHistory || [];
            return {
              ...doc,
              status: 'Verified' as const,
              statusHistory: [...history, { status: 'Verified' as const, timestamp }]
            };
          }
          return doc;
        });
        return { ...emp, documents: updatedDocs };
      }
      return emp;
    }));

    // Update the local slide-over view too
    setViewingEmployee(prev => {
      if (!prev) return null;
      const updatedDocs = (prev.documents || []).map(doc => {
        if (doc.id === docId) {
          const history = doc.statusHistory || [];
          return {
            ...doc,
            status: 'Verified' as const,
            statusHistory: [...history, { status: 'Verified' as const, timestamp }]
          };
        }
        return doc;
      });
      return { ...prev, documents: updatedDocs };
    });

    addNotification(
      viewingEmployee.id,
      "Document Verified",
      `Your document "${viewingEmployee.documents?.find(d => d.id === docId)?.name}" has been verified and approved by HR.`
    );
  };

  const deleteEmployeeDoc = (docId: string) => {
    if (!viewingEmployee || !window.confirm('Remove this document from personnel file?')) return;

    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, documents: (emp.documents || []).filter(d => d.id !== docId) } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, documents: (prev.documents || []).filter(d => d.id !== docId) } : null);
  };

  const StatusBadge = ({ status }: { status: Employee['status'] }) => (
    <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
      status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
      status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
      status === 'Frozen' ? 'bg-blue-50 text-blue-700 border-blue-100' :
      'bg-gray-100 text-gray-500 border-gray-200'
    }`}>
      {status}
    </span>
  );

  const ActionMenu = ({ emp }: { emp: Employee }) => (
    <div className="relative inline-block text-left" onClick={(e) => e.stopPropagation()}>
      <button 
        onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === emp.id ? null : emp.id); }}
        className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all"
      >
        <MoreVertical size={18} />
      </button>

      {menuOpenId === emp.id && (
        <div className="absolute right-0 top-10 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <div className="p-2 space-y-1">
            <button onClick={() => handleUpdateStatus(emp.id, 'Active')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-green-700 hover:bg-green-50 flex items-center gap-3"><UserCheck size={14}/> Activate</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Frozen')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-blue-700 hover:bg-blue-50 flex items-center gap-3"><Snowflake size={14}/> Freeze</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Inactive')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-red-600 hover:bg-red-50 flex items-center gap-3"><Power size={14}/> Deactivate</button>
            <div className="h-[1px] bg-gray-50 my-1" />
            <button onClick={() => setViewingEmployee(emp)} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-500 hover:bg-gray-50 flex items-center gap-3"><ClipboardList size={14}/> Manage File</button>
          </div>
        </div>
      )}
    </div>
  );

  const filteredViewingTasks = viewingEmployee ? (viewingEmployee.tasks || []).filter(task => 
    task.title.toLowerCase().includes(taskSearchTerm.toLowerCase())
  ) : [];

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900">Personnel Profiles</h1>
          <p className="text-gray-500 font-medium">Browse and manage comprehensive organization profiles.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <button 
            onClick={() => {
              setIsAddingEmployee(true);
              setFormError(null);
            }}
            className="flex items-center gap-2 px-5 py-2.5 bg-blue-900 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95"
          >
            <Plus size={18} /> Create Profile
          </button>
        </div>
      </header>

      {/* Filters & View Switcher */}
      <div className="flex flex-col xl:flex-row gap-4 items-center">
        <div className="flex-1 relative w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search profiles by name, role, email..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:border-blue-900/20 transition-all shadow-sm font-medium text-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full xl:w-auto">
          {/* Profile ID Filter */}
          <div className="flex-1 xl:flex-none relative min-w-[140px]">
            <Hash className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
            <input 
              type="text" 
              placeholder="ID Filter"
              className="w-full pl-8 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:border-blue-900/20 transition-all shadow-sm font-bold text-xs uppercase tracking-widest placeholder:text-gray-300"
              value={idFilter}
              onChange={(e) => setIdFilter(e.target.value)}
            />
          </div>

          <div className="flex-1 xl:flex-none relative min-w-[160px]">
            <select 
              value={deptFilter}
              onChange={(e) => setDeptFilter(e.target.value)}
              className="w-full pl-4 pr-10 py-3 bg-white border border-gray-200 rounded-2xl outline-none appearance-none text-xs font-bold uppercase tracking-wider text-gray-600 shadow-sm cursor-pointer"
            >
              <option value="All">All Departments</option>
              {DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={14} />
          </div>

          <div className="flex-1 xl:flex-none relative min-w-[140px]">
            <select 
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="w-full pl-4 pr-10 py-3 bg-white border border-gray-200 rounded-2xl outline-none appearance-none text-xs font-bold uppercase tracking-wider text-gray-600 shadow-sm cursor-pointer"
            >
              <option value="All">All Statuses</option>
              <option value="Active">Active</option>
              <option value="On Leave">On Leave</option>
              <option value="Frozen">Frozen</option>
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={14} />
          </div>

          <div className="flex items-center gap-1 p-1.5 bg-gray-100 rounded-[1.25rem]">
            {(['list', 'grid', 'compact'] as ViewMode[]).map((mode) => (
              <button 
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`p-2 rounded-xl transition-all ${
                  viewMode === mode 
                    ? 'bg-white text-blue-900 shadow-sm' 
                    : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                {mode === 'list' && <LayoutList size={20} />}
                {mode === 'grid' && <LayoutGrid size={20} />}
                {mode === 'compact' && <Rows3 size={20} />}
              </button>
            ))}
          </div>
        </div>
      </div>

      {selectedIds.length > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-bottom-8 duration-300">
          <div className="bg-blue-900 text-white px-6 py-4 rounded-[2rem] shadow-2xl flex items-center gap-8 border border-white/20 backdrop-blur-lg">
            <div className="flex items-center gap-3 pr-8 border-r border-white/10">
              <div className="w-8 h-8 bg-white/20 rounded-xl flex items-center justify-center font-black text-sm">
                {selectedIds.length}
              </div>
              <p className="text-xs font-bold uppercase tracking-widest">Selected</p>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => handleBulkStatusUpdate('Active')} className="p-2.5 hover:bg-white/10 rounded-xl transition-all" title="Bulk Activate"><UserCheck size={18}/></button>
              <button onClick={() => handleBulkStatusUpdate('Frozen')} className="p-2.5 hover:bg-white/10 rounded-xl transition-all" title="Bulk Freeze"><Snowflake size={18}/></button>
              <button onClick={handleBulkPasswordReset} className="p-2.5 hover:bg-orange-500 rounded-xl transition-all" title="Bulk Credential Reset"><KeyRound size={18}/></button>
              <button onClick={handleDownloadData} className="p-2.5 hover:bg-white/10 rounded-xl transition-all" title="Export Selected"><Download size={18}/></button>
              <div className="w-[1px] h-6 bg-white/10 mx-2" />
              <button onClick={() => setSelectedIds([])} className="p-2.5 hover:bg-red-500 rounded-xl transition-all" title="Clear Selection"><X size={18}/></button>
            </div>
          </div>
        </div>
      )}

      <div className="min-h-[400px]">
        {filteredEmployees.length === 0 ? (
          <div className="bg-white rounded-[2.5rem] p-16 text-center border border-gray-100 shadow-sm">
            <UserCircle size={48} className="mx-auto text-gray-200 mb-4" />
            <h3 className="text-xl font-bold text-blue-900">No profiles found</h3>
            <p className="text-gray-400 max-w-xs mx-auto mt-2">Adjust your filters or try a different search term.</p>
          </div>
