                      <div key={task.id} className={`p-5 rounded-[1.75rem] border transition-all flex flex-col gap-4 ${task.status === 'Completed' ? 'bg-gray-50/50 border-gray-100 opacity-60' : 'bg-white border-gray-100 shadow-sm'}`}>
                        <div className="flex items-center justify-between w-full">
                          <div className="flex items-center gap-4">
                            <div className={`w-3 h-3 rounded-full ${task.status === 'Completed' ? 'bg-green-500' : task.status === 'In Progress' ? 'bg-blue-500 animate-pulse' : 'bg-gray-300'}`} />
                            <div>
                              <p className="text-sm font-bold text-blue-900">{task.title}</p>
                              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-0.5">Due {task.dueDate}</p>
                            </div>
                          </div>
                          <span className={`text-[9px] font-black px-2 py-0.5 rounded-lg uppercase tracking-widest ${task.priority === 'High' ? 'bg-red-50 text-red-600' : 'bg-gray-100 text-gray-500'}`}>{task.priority}</span>
                        </div>

                        <div className="flex items-center gap-2 pt-2 border-t border-gray-50">
                          <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest mr-auto">Status:</span>
                          {(['Pending', 'In Progress', 'Completed'] as Task['status'][]).map(status => (
                            <button
                              key={status}
                              onClick={() => handleUpdateTaskStatus(task.id, status)}
                              className={`px-3 py-1 rounded-lg text-[9px] font-bold uppercase tracking-wider transition-all border ${
                                task.status === status
                                  ? status === 'Completed' ? 'bg-green-100 border-green-200 text-green-700' : 
                                    status === 'In Progress' ? 'bg-blue-100 border-blue-200 text-blue-700' : 
                                    'bg-gray-100 border-gray-200 text-gray-600'
                                  : 'bg-white border-gray-100 text-gray-300 hover:border-blue-100 hover:text-blue-900'
                              }`}
                            >
                              {status}
                            </button>
                          ))}
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const Loader2 = ({ className, size }: { className?: string, size?: number }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    width={size || 24} 
    height={size || 24} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={`animate-spin ${className}`}
  >
    <path d="M21 12a9 9 0 1 1-6.219-8.56"/>
  </svg>
);

export default Employees;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Search, MoreVertical, Plus, Trash2, X, ClipboardList, CheckCircle, 
  UserPlus, Building2, ShieldCheck, Download, Snowflake, Power, UserCheck,
  LayoutList, LayoutGrid, Rows3, ChevronDown, Fingerprint, FileText, Hash, UserCircle,
  Lock, Eye, EyeOff, ShieldAlert, KeyRound, AlertTriangle, Loader2, FolderInput
} from 'lucide-react';
import { DEPARTMENTS } from '../constants';
import { Employee, Task, Document } from '../types';

interface EmployeesProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

type ViewMode = 'list' | 'grid' | 'compact';
type TaskFilterType = 'All' | 'No Tasks' | 'Has Tasks';

const Employees: React.FC<EmployeesProps> = ({ employees, setEmployees, addNotification }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [idFilter, setIdFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [taskFilter, setTaskFilter] = useState<TaskFilterType>('All');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [isUploadingDoc, setIsUploadingDoc] = useState(false);
  const employeeFileInputRef = useRef<HTMLInputElement>(null);

  const [taskSearchTerm, setTaskSearchTerm] = useState('');
  const [formError, setFormError] = useState<string | null>(null);
  const [adminResetPass, setAdminResetPass] = useState('');
  const [showAdminResetPass, setShowAdminResetPass] = useState(false);
  const [resetSuccess, setResetSuccess] = useState(false);
  const [showInitialPass, setShowInitialPass] = useState(false);

  const [newEmp, setNewEmp] = useState({
    employeeId: '',
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    password: '',
    status: 'Active' as const
  });

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  useEffect(() => {
    const handleClickOutside = () => setMenuOpenId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  useEffect(() => {
    if (!viewingEmployee) {
      setTaskSearchTerm('');
      setAdminResetPass('');
      setShowAdminResetPass(false);
      setResetSuccess(false);
    }
  }, [viewingEmployee]);

  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const idTerm = idFilter.toLowerCase();

    const matchesSearch = 
      emp.name.toLowerCase().includes(term) ||
      emp.role.toLowerCase().includes(term) ||
      emp.department.toLowerCase().includes(term) ||
      emp.email.toLowerCase().includes(term) ||
      emp.employeeId.toLowerCase().includes(term);

    const matchesId = !idFilter || emp.employeeId.toLowerCase().includes(idTerm);
    const matchesStatus = statusFilter === 'All' || emp.status === statusFilter;
    const matchesDept = deptFilter === 'All' || emp.department === deptFilter;

    const hasTasks = emp.tasks && emp.tasks.length > 0;
    const matchesTasks = 
      taskFilter === 'All' ? true :
      taskFilter === 'No Tasks' ? !hasTasks :
      taskFilter === 'Has Tasks' ? hasTasks : true;

    return matchesSearch && matchesId && matchesStatus && matchesDept && matchesTasks;
  });

  const handleUpdateStatus = (id: string, newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      emp.id === id ? { ...emp, status: newStatus } : emp
    ));
    addNotification(id, `Status Update: ${newStatus}`, `Your account access has been set to ${newStatus}.`);
    setMenuOpenId(null);
  };

  const handleBulkStatusUpdate = (newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, status: newStatus } : emp
    ));
    selectedIds.forEach(id => {
      addNotification(id, `Bulk Status Update`, `Your status was updated to ${newStatus} by HR.`);
    });
    setSelectedIds([]);
  };

  const handleBulkPasswordReset = () => {
    const newPass = prompt(`BULK CREDENTIAL RESET:\n\nEnter a new access token for the ${selectedIds.length} selected employees:`);
    if (!newPass) return;

    if (newPass.length < 6) {
      alert("Error: Password must be at least 6 characters.");
      return;
    }

    const confirmed = window.confirm(`Confirm bulk password reset for ${selectedIds.length} employees to: "${newPass}"?`);
    if (!confirmed) return;

    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, password: newPass } : emp
    ));

    selectedIds.forEach(id => {
      addNotification(id, "System Credential Reset", "HR has performed a bulk update of organization access tokens.");
    });

    alert(`Success: Credentials updated.`);
    setSelectedIds([]);
  };

  const handleDownloadData = () => {
    const dataToExport = selectedIds.length > 0 
      ? employees.filter(e => selectedIds.includes(e.id))
      : employees;

    const dataStr = JSON.stringify(dataToExport, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `srinidhi_profiles_export_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    // 1. Format Validation: SA-XXX (exactly 3 digits)
    const idRegex = /^SA-\d{3}$/;
    if (!idRegex.test(newEmp.employeeId)) {
      setFormError("Employee ID must follow the format 'SA-XXX' (e.g., SA-001, SA-999).");
      return;
    }

    // 2. Uniqueness Validation
    const isDuplicate = employees.some(emp => emp.employeeId.toUpperCase() === newEmp.employeeId.toUpperCase());
    if (isDuplicate) {
      setFormError(`Conflict: Employee ID '${newEmp.employeeId}' is already assigned to another profile.`);
      return;
    }

    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: [],
      documents: []
    };

    setEmployees([employee, ...employees]);
    setIsAddingEmployee(false);
    setNewEmp({ employeeId: '', name: '', role: '', department: DEPARTMENTS[0], email: '', password: '', status: 'Active' });
    setShowInitialPass(false);
    setFormError(null);
  };

  const handleAdminResetPassword = () => {
    if (!viewingEmployee || !adminResetPass.trim()) return;
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, password: adminResetPass } : emp
    ));
    setResetSuccess(true);
    setTimeout(() => setResetSuccess(false), 3000);
    setAdminResetPass('');
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;
    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, tasks: [...(emp.tasks || []), newTask] } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, tasks: [...(prev.tasks || []), newTask] } : null);
    setNewTaskTitle('');
  };

  const handleUpdateTaskStatus = (taskId: string, newStatus: Task['status']) => {
    if (!viewingEmployee) return;
    setEmployees(prev => prev.map(emp => {
      if (emp.id === viewingEmployee.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
        };
      }
      return emp;
    }));
    setViewingEmployee(prev => {
      if (!prev) return null;
      return {
        ...prev,
        tasks: (prev.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
      };
    });
  };

  const StatusBadge = ({ status }: { status: Employee['status'] }) => (
    <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
      status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
      status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
      status === 'Frozen' ? 'bg-blue-50 text-blue-700 border-blue-100' :
      'bg-gray-100 text-gray-500 border-gray-200'
    }`}>
      {status}
    </span>
  );

  const ActionMenu = ({ emp }: { emp: Employee }) => (
    <div className="relative inline-block text-left" onClick={(e) => e.stopPropagation()}>
      <button 
        onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === emp.id ? null : emp.id); }}
        className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all"
      >
        <MoreVertical size={18} />
      </button>

      {menuOpenId === emp.id && (
        <div className="absolute right-0 top-10 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <div className="p-2 space-y-1">
            <button onClick={() => handleUpdateStatus(emp.id, 'Active')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-green-700 hover:bg-green-50 flex items-center gap-3"><UserCheck size={14}/> Activate</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Frozen')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-blue-700 hover:bg-blue-50 flex items-center gap-3"><Snowflake size={14}/> Freeze</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Inactive')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-red-600 hover:bg-red-50 flex items-center gap-3"><Power size={14}/> Deactivate</button>
            <div className="h-[1px] bg-gray-50 my-1" />
            <button onClick={() => setViewingEmployee(emp)} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-500 hover:bg-gray-50 flex items-center gap-3"><ClipboardList size={14}/> Manage File</button>
          </div>
        </div>
      )}
    </div>
  );

  const filteredViewingTasks = viewingEmployee ? (viewingEmployee.tasks || []).filter(task => 
    task.title.toLowerCase().includes(taskSearchTerm.toLowerCase())
  ) : [];

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900">Personnel Profiles</h1>
          <p className="text-gray-500 font-medium">Browse and manage comprehensive organization profiles.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <button 
            onClick={() => {
              setIsAddingEmployee(true);
              setFormError(null);
            }}
            className="flex items-center gap-2 px-5 py-2.5 bg-blue-900 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95"
          >
            <Plus size={18} /> Create Profile
          </button>
        </div>
      </header>

      {/* Search & Filters */}
      <div className="flex flex-col xl:flex-row gap-4 items-center">
        <div className="flex-1 relative w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search profiles by name, role, email..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm font-medium text-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex flex-wrap items-center gap-3 w-full xl:w-auto">
          <div className="flex-1 xl:flex-none relative min-w-[140px]">
            <Hash className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
            <input 
              type="text" 
              placeholder="ID Filter"
              className="w-full pl-8 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none shadow-sm font-bold text-xs uppercase tracking-widest"
              value={idFilter}
              onChange={(e) => setIdFilter(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-1 p-1.5 bg-gray-100 rounded-[1.25rem]">
            {(['list', 'grid', 'compact'] as ViewMode[]).map((mode) => (
              <button 
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`p-2 rounded-xl transition-all ${viewMode === mode ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
              >
                {mode === 'list' && <LayoutList size={20} />}
                {mode === 'grid' && <LayoutGrid size={20} />}
                {mode === 'compact' && <Rows3 size={20} />}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="min-h-[400px]">
        {filteredEmployees.length === 0 ? (
          <div className="bg-white rounded-[2.5rem] p-16 text-center border border-gray-100 shadow-sm">
            <UserCircle size={48} className="mx-auto text-gray-200 mb-4" />
            <h3 className="text-xl font-bold text-blue-900">No profiles found</h3>
          </div>
        ) : (
          <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">ID</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Profile</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Department</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredEmployees.map(emp => (
                  <tr key={emp.id} onClick={() => setViewingEmployee(emp)} className="hover:bg-blue-50/30 transition-all cursor-pointer">
                    <td className="px-6 py-4 whitespace-nowrap text-xs font-bold text-gray-400">{emp.employeeId}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center gap-4">
                        <img src={emp.avatar} alt="" className="w-10 h-10 rounded-2xl object-cover" />
                        <div>
                          <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                          <p className="text-[11px] text-gray-400 font-bold uppercase">{emp.role}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-[11px] font-bold text-gray-500 uppercase">{emp.department}</td>
                    <td className="px-6 py-4 whitespace-nowrap"><StatusBadge status={emp.status} /></td>
                    <td className="px-6 py-4 text-right"><ActionMenu emp={emp} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {isAddingEmployee && (
        <div className="fixed inset-0 z-[150] overflow-hidden">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setIsAddingEmployee(false)} />
          <div className="absolute inset-y-0 right-0 max-w-md w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
              <div className="flex items-center gap-4">
                <UserPlus size={24} />
                <h2 className="text-xl font-bold">New Profile</h2>
              </div>
              <button onClick={() => setIsAddingEmployee(false)} className="p-2 hover:bg-white/10 rounded-xl"><X size={24} /></button>
            </div>
            <form onSubmit={handleAddEmployee} className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              {formError && (
                <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 animate-in slide-in-from-top-2">
                  <AlertTriangle className="text-red-600 shrink-0" size={18} />
                  <p className="text-xs font-bold text-red-700">{formError}</p>
                </div>
              )}
              <div className="space-y-6">
                <div>
                  <div className="flex items-center justify-between mb-2 ml-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Employee ID</label>
                    <span className="text-[8px] font-black text-blue-900/40 uppercase">Required: SA-XXX</span>
                  </div>
                  <div className="relative">
                    <Fingerprint className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                    <input 
                      required 
                      placeholder="e.g. SA-005" 
                      className={`w-full pl-12 pr-5 py-4 bg-gray-50 border rounded-2xl outline-none focus:ring-4 transition-all font-bold text-sm ${
                        formError && formError.includes('ID') ? 'border-red-200 focus:ring-red-500/5' : 'border-gray-100 focus:ring-blue-500/5 focus:bg-white'
                      }`} 
                      value={newEmp.employeeId} 
                      onChange={e => {
                        setFormError(null);
                        setNewEmp({...newEmp, employeeId: e.target.value.toUpperCase()});
                      }} 
                    />
                  </div>
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                  <input required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" value={newEmp.name} onChange={e => setNewEmp({...newEmp, name: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Professional Email</label>
                  <input type="email" required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" value={newEmp.email} onChange={e => setNewEmp({...newEmp, email: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Password</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                    <input 
                      type={showInitialPass ? "text" : "password"} 
                      required 
                      className="w-full pl-12 pr-12 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" 
                      value={newEmp.password} 
                      onChange={e => setNewEmp({...newEmp, password: e.target.value})} 
                    />
                    <button type="button" onClick={() => setShowInitialPass(!showInitialPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400">
                      {showInitialPass ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Position</label>
                    <input required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm" value={newEmp.role} onChange={e => setNewEmp({...newEmp, role: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Department</label>
                    <select className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm" value={newEmp.department} onChange={e => setNewEmp({...newEmp, department: e.target.value})}>
                      {DEPARTMENTS.map(d => <option key={d}>{d}</option>)}
                    </select>
                  </div>
                </div>
              </div>
              <button type="submit" className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-bold text-sm uppercase tracking-widest shadow-xl shadow-blue-900/20 active:scale-95 transition-all">Initialize Profile</button>
            </form>
          </div>
        </div>
      )}

      {viewingEmployee && (
        <div className="fixed inset-0 z-[140] overflow-hidden">
          <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={() => setViewingEmployee(null)} />
          <div className="absolute inset-y-0 right-0 max-w-lg w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between">
              <h2 className="text-xl font-bold text-blue-900">Personnel File</h2>
              <button onClick={() => setViewingEmployee(null)} className="p-2 hover:bg-gray-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-8 no-scrollbar space-y-10">
              <div className="flex items-center gap-8">
                <img src={viewingEmployee.avatar} className="w-28 h-28 rounded-[2.5rem] object-cover shadow-2xl shadow-blue-900/10 border-4 border-white" alt="" />
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <Fingerprint size={12} className="text-blue-900/30" />
                    <span className="text-[10px] font-black text-blue-900/30 uppercase">{viewingEmployee.employeeId}</span>
                  </div>
                  <h3 className="text-2xl font-bold text-blue-900">{viewingEmployee.name}</h3>
                  <p className="text-gray-500 font-medium">{viewingEmployee.role}</p>
                  <div className="flex items-center gap-2 mt-2">
                    <StatusBadge status={viewingEmployee.status} />
                    <span className="text-[9px] font-black text-gray-400 uppercase border px-2 py-0.5 rounded-lg">{viewingEmployee.department}</span>
                  </div>
                </div>
              </div>
              <div className="space-y-6">
                <h4 className="text-xs font-black text-gray-400 uppercase flex items-center gap-2"><ShieldAlert size={16} className="text-orange-500" /> Access Overwrite</h4>
                <div className="rounded-[2rem] p-6 border bg-orange-50/50 border-orange-100 space-y-4">
                  <div className="relative">
                    <input 
                      type="password" 
                      placeholder="Input new access token..." 
                      className="w-full px-6 py-4 bg-white border border-orange-200 rounded-2xl text-sm outline-none font-bold" 
                      value={adminResetPass} 
                      onChange={(e) => setAdminResetPass(e.target.value)} 
                    />
                    <button onClick={handleAdminResetPassword} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-orange-600 text-white rounded-xl"><ShieldCheck size={20}/></button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Employees;

import React, { useState } from 'react';
import { CheckCircle, Clock, Calendar, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Employee, Task } from '../types';

interface MyTasksProps {
  employee: Employee;
  onUpdateTask: (taskId: string, status: Task['status']) => void;
}

const MyTasks: React.FC<MyTasksProps> = ({ employee, onUpdateTask }) => {
  const [completingTaskId, setCompletingTaskId] = useState<string | null>(null);
  const tasks = employee.tasks || [];
  const pendingCount = tasks.filter(t => t.status !== 'Completed').length;

  const handleMarkComplete = (taskId: string, title: string) => {
    if (window.confirm(`Mark "${title}" as completed?`)) {
      // Trigger local animation state
      setCompletingTaskId(taskId);

      // Update the actual task status
      onUpdateTask(taskId, 'Completed');

      // Reset the animation state after it completes
      setTimeout(() => {
        setCompletingTaskId(null);
      }, 700);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">My Assignments</h1>
          <p className="text-gray-500">Review and update your current workload.</p>
        </div>
        <div className="flex items-center gap-3 px-4 py-2 bg-blue-50 border border-blue-100 rounded-xl">
          <AlertCircle className="text-blue-600" size={18} />
          <span className="text-sm font-bold text-blue-900">{pendingCount} Active Tasks</span>
        </div>
      </header>

      {tasks.length === 0 ? (
        <div className="bg-white rounded-3xl p-12 text-center border border-dashed border-gray-200">
          <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
            <CheckCircle2 size={32} />
          </div>
          <h3 className="text-lg font-bold text-gray-900">All caught up!</h3>
          <p className="text-gray-500 max-w-xs mx-auto mt-2">No tasks assigned to you at the moment. Take a breather or check in with HR.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {tasks.sort((a,b) => a.status === 'Completed' ? 1 : -1).map(task => {
            const isCompleting = completingTaskId === task.id;

            return (
              <div 
                key={task.id} 
                className={`bg-white p-6 rounded-2xl border transition-all duration-500 flex flex-col md:flex-row md:items-center justify-between gap-6 relative overflow-hidden ${
                  isCompleting 
                    ? 'scale-[1.03] border-green-500 ring-4 ring-green-500/20 shadow-xl z-10' 
                    : task.status === 'Completed' 
                      ? 'opacity-60 grayscale-[0.5] border-gray-100' 
                      : 'hover:border-blue-200 border-gray-100 shadow-sm'
                }`}
              >
                {/* Completion Flash Overlay */}
                {isCompleting && (
                  <div className="absolute inset-0 bg-green-50/20 animate-pulse pointer-events-none" />
                )}

                <div className="flex items-start gap-4 flex-1">
                  <div className={`p-3 rounded-xl transition-colors duration-500 ${
                    task.status === 'Completed' || isCompleting ? 'bg-green-50 text-green-600' :
                    task.status === 'In Progress' ? 'bg-blue-50 text-blue-600' :
                    'bg-gray-50 text-gray-400'
                  }`}>
                    {task.status === 'Completed' || isCompleting ? (
                      <CheckCircle size={24} className={isCompleting ? 'animate-bounce' : ''} />
                    ) : (
                      <Clock size={24} />
                    )}
                  </div>
                  <div>
                    <h3 className={`font-bold text-lg transition-all duration-500 ${
                      task.status === 'Completed' && !isCompleting ? 'line-through text-gray-400' : 'text-blue-900'
                    }`}>
                      {task.title}
                    </h3>
                    <div className="flex flex-wrap items-center gap-4 mt-2">
                      <div className="flex items-center gap-1.5 text-xs font-bold text-gray-400 uppercase tracking-tight">
                        <Calendar size={14} /> Due: {task.dueDate}
                      </div>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded-lg uppercase tracking-widest ${
                        task.priority === 'High' ? 'bg-red-50 text-red-600' :
                        task.priority === 'Medium' ? 'bg-yellow-50 text-yellow-600' :
                        'bg-gray-50 text-gray-500'
                      }`}>
                        {task.priority} Priority
                      </span>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded-lg uppercase tracking-widest transition-colors duration-500 ${
                        task.status === 'Completed' || isCompleting ? 'bg-green-50 text-green-700' :
                        task.status === 'In Progress' ? 'bg-blue-50 text-blue-700' :
                        'bg-gray-100 text-gray-500'
                      }`}>
                        {isCompleting ? 'Processing...' : task.status}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="flex gap-2">
                  {task.status !== 'In Progress' && task.status !== 'Completed' && !isCompleting && (
                    <button 
                      onClick={() => onUpdateTask(task.id, 'In Progress')}
                      className="px-4 py-2 bg-blue-50 text-blue-900 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-blue-100 transition-all active:scale-95"
                    >
                      Start Task
                    </button>
                  )}
                  {task.status !== 'Completed' && !isCompleting && (
                    <button 
                      onClick={() => handleMarkComplete(task.id, task.title)}
                      className="px-4 py-2 bg-blue-900 text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-blue-800 transition-all shadow-lg shadow-blue-900/10 active:scale-95"
                    >
                      Mark Complete
                    </button>
                  )}
                  {task.status === 'Completed' && !isCompleting && (
                    <button 
                      onClick={() => onUpdateTask(task.id, 'Pending')}
                      className="px-4 py-2 bg-gray-50 text-gray-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
                    >
                      Reopen
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default MyTasks;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Search, MoreVertical, Plus, Trash2, X, ClipboardList, CheckCircle, 
  UserPlus, Building2, ShieldCheck, Download, Snowflake, Power, UserCheck,
  LayoutList, LayoutGrid, Rows3, ChevronDown, Fingerprint, FileText, Hash, UserCircle,
  Lock, Eye, EyeOff, ShieldAlert, KeyRound, AlertTriangle, Loader2, FolderInput
} from 'lucide-react';
import { DEPARTMENTS } from '../constants';
import { Employee, Task, Document } from '../types';

interface EmployeesProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

type ViewMode = 'list' | 'grid' | 'compact';
type TaskFilterType = 'All' | 'No Tasks' | 'Has Tasks';

const Employees: React.FC<EmployeesProps> = ({ employees, setEmployees, addNotification }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [idFilter, setIdFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [taskFilter, setTaskFilter] = useState<TaskFilterType>('All');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [isUploadingDoc, setIsUploadingDoc] = useState(false);
  const employeeFileInputRef = useRef<HTMLInputElement>(null);

  const [taskSearchTerm, setTaskSearchTerm] = useState('');
  const [formError, setFormError] = useState<string | null>(null);
  const [adminResetPass, setAdminResetPass] = useState('');
  const [showAdminResetPass, setShowAdminResetPass] = useState(false);
  const [resetSuccess, setResetSuccess] = useState(false);
  const [showInitialPass, setShowInitialPass] = useState(false);

  const [newEmp, setNewEmp] = useState({
    employeeId: '',
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    password: '',
    status: 'Active' as const
  });

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  useEffect(() => {
    const handleClickOutside = () => setMenuOpenId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  useEffect(() => {
    if (!viewingEmployee) {
      setTaskSearchTerm('');
      setAdminResetPass('');
      setShowAdminResetPass(false);
      setResetSuccess(false);
    }
  }, [viewingEmployee]);

  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const idTerm = idFilter.toLowerCase();

    const matchesSearch = 
      emp.name.toLowerCase().includes(term) ||
      emp.role.toLowerCase().includes(term) ||
      emp.department.toLowerCase().includes(term) ||
      emp.email.toLowerCase().includes(term) ||
      emp.employeeId.toLowerCase().includes(term);

    const matchesId = !idFilter || emp.employeeId.toLowerCase().includes(idTerm);
    const matchesStatus = statusFilter === 'All' || emp.status === statusFilter;
    const matchesDept = deptFilter === 'All' || emp.department === deptFilter;

    const hasTasks = emp.tasks && emp.tasks.length > 0;
    const matchesTasks = 
      taskFilter === 'All' ? true :
      taskFilter === 'No Tasks' ? !hasTasks :
      taskFilter === 'Has Tasks' ? hasTasks : true;

    return matchesSearch && matchesId && matchesStatus && matchesDept && matchesTasks;
  });

  const handleUpdateStatus = (id: string, newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      emp.id === id ? { ...emp, status: newStatus } : emp
    ));
    addNotification(id, `Status Update: ${newStatus}`, `Your account access has been set to ${newStatus}.`);
    setMenuOpenId(null);
  };

  const handleBulkStatusUpdate = (newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, status: newStatus } : emp
    ));
    selectedIds.forEach(id => {
      addNotification(id, `Bulk Status Update`, `Your status was updated to ${newStatus} by HR.`);
    });
    setSelectedIds([]);
  };

  const handleBulkPasswordReset = () => {
    const newPass = prompt(`BULK CREDENTIAL RESET:\n\nEnter a new access token for the ${selectedIds.length} selected employees:`);
    if (!newPass) return;

    if (newPass.length < 6) {
      alert("Error: Password must be at least 6 characters.");
      return;
    }

    const confirmed = window.confirm(`Confirm bulk password reset for ${selectedIds.length} employees to: "${newPass}"?`);
    if (!confirmed) return;

    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, password: newPass } : emp
    ));

    selectedIds.forEach(id => {
      addNotification(id, "System Credential Reset", "HR has performed a bulk update of organization access tokens.");
    });

    alert(`Success: Credentials updated.`);
    setSelectedIds([]);
  };

  const handleDownloadData = () => {
    const dataToExport = selectedIds.length > 0 
      ? employees.filter(e => selectedIds.includes(e.id))
      : employees;

    const dataStr = JSON.stringify(dataToExport, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `srinidhi_profiles_export_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    // 1. Format Validation: SA-XXX (exactly 3 digits)
    const idRegex = /^SA-\d{3}$/;
    if (!idRegex.test(newEmp.employeeId)) {
      setFormError("Employee ID must follow the format 'SA-XXX' (e.g., SA-001, SA-999).");
      return;
    }

    // 2. Uniqueness Validation
    const isDuplicate = employees.some(emp => emp.employeeId.toUpperCase() === newEmp.employeeId.toUpperCase());
    if (isDuplicate) {
      setFormError(`Conflict: Employee ID '${newEmp.employeeId}' is already assigned to another profile.`);
      return;
    }

    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: [],
      documents: []
    };

    setEmployees([employee, ...employees]);
    setIsAddingEmployee(false);
    setNewEmp({ employeeId: '', name: '', role: '', department: DEPARTMENTS[0], email: '', password: '', status: 'Active' });
    setShowInitialPass(false);
    setFormError(null);
  };

  const handleAdminResetPassword = () => {
    if (!viewingEmployee || !adminResetPass.trim()) return;
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, password: adminResetPass } : emp
    ));
    setResetSuccess(true);
    setTimeout(() => setResetSuccess(false), 3000);
    setAdminResetPass('');
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;
    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, tasks: [...(emp.tasks || []), newTask] } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, tasks: [...(prev.tasks || []), newTask] } : null);
    setNewTaskTitle('');
  };

  const handleUpdateTaskStatus = (taskId: string, newStatus: Task['status']) => {
    if (!viewingEmployee) return;
    setEmployees(prev => prev.map(emp => {
      if (emp.id === viewingEmployee.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
        };
      }
      return emp;
    }));
    setViewingEmployee(prev => {
      if (!prev) return null;
      return {
        ...prev,
        tasks: (prev.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
      };
    });
  };

  const StatusBadge = ({ status }: { status: Employee['status'] }) => (
    <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
      status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
      status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
      status === 'Frozen' ? 'bg-blue-50 text-blue-700 border-blue-100' :
      'bg-gray-100 text-gray-500 border-gray-200'
    }`}>
      {status}
    </span>
  );

  const ActionMenu = ({ emp }: { emp: Employee }) => (
    <div className="relative inline-block text-left" onClick={(e) => e.stopPropagation()}>
      <button 
        onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === emp.id ? null : emp.id); }}
        className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all"
      >
        <MoreVertical size={18} />
      </button>

      {menuOpenId === emp.id && (
        <div className="absolute right-0 top-10 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <div className="p-2 space-y-1">
            <button onClick={() => handleUpdateStatus(emp.id, 'Active')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-green-700 hover:bg-green-50 flex items-center gap-3"><UserCheck size={14}/> Activate</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Frozen')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-blue-700 hover:bg-blue-50 flex items-center gap-3"><Snowflake size={14}/> Freeze</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Inactive')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-red-600 hover:bg-red-50 flex items-center gap-3"><Power size={14}/> Deactivate</button>
            <div className="h-[1px] bg-gray-50 my-1" />
            <button onClick={() => setViewingEmployee(emp)} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-500 hover:bg-gray-50 flex items-center gap-3"><ClipboardList size={14}/> Manage File</button>
          </div>
        </div>
      )}
    </div>
  );

  const filteredViewingTasks = viewingEmployee ? (viewingEmployee.tasks || []).filter(task => 
    task.title.toLowerCase().includes(taskSearchTerm.toLowerCase())
  ) : [];

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900">Personnel Profiles</h1>
          <p className="text-gray-500 font-medium">Browse and manage comprehensive organization profiles.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <button 
            onClick={() => {
              setIsAddingEmployee(true);
              setFormError(null);
            }}
            className="flex items-center gap-2 px-5 py-2.5 bg-blue-900 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95"
          >
            <Plus size={18} /> Create Profile
          </button>
        </div>
      </header>

      {/* Search & Filters */}
      <div className="flex flex-col xl:flex-row gap-4 items-center">
        <div className="flex-1 relative w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search profiles by name, role, email..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm font-medium text-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex flex-wrap items-center gap-3 w-full xl:w-auto">
          <div className="flex-1 xl:flex-none relative min-w-[140px]">
            <Hash className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
            <input 
              type="text" 
              placeholder="ID Filter"
              className="w-full pl-8 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none shadow-sm font-bold text-xs uppercase tracking-widest"
              value={idFilter}
              onChange={(e) => setIdFilter(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-1 p-1.5 bg-gray-100 rounded-[1.25rem]">
            {(['list', 'grid', 'compact'] as ViewMode[]).map((mode) => (
              <button 
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`p-2 rounded-xl transition-all ${viewMode === mode ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
              >
                {mode === 'list' && <LayoutList size={20} />}
                {mode === 'grid' && <LayoutGrid size={20} />}
                {mode === 'compact' && <Rows3 size={20} />}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="min-h-[400px]">
        {filteredEmployees.length === 0 ? (
          <div className="bg-white rounded-[2.5rem] p-16 text-center border border-gray-100 shadow-sm">
            <UserCircle size={48} className="mx-auto text-gray-200 mb-4" />
            <h3 className="text-xl font-bold text-blue-900">No profiles found</h3>
          </div>
        ) : (
          <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest whitespace-nowrap">Employee ID</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Profile</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Department</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
                  <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredEmployees.map(emp => (
                  <tr key={emp.id} onClick={() => setViewingEmployee(emp)} className="hover:bg-blue-50/30 transition-all cursor-pointer">
                    <td className="px-6 py-4 whitespace-nowrap text-xs font-bold text-gray-400">{emp.employeeId}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center gap-4">
                        <img src={emp.avatar} alt="" className="w-10 h-10 rounded-2xl object-cover" />
                        <div>
                          <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                          <p className="text-[11px] text-gray-400 font-bold uppercase">{emp.role}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-[11px] font-bold text-gray-500 uppercase">{emp.department}</td>
                    <td className="px-6 py-4 whitespace-nowrap"><StatusBadge status={emp.status} /></td>
                    <td className="px-6 py-4 text-right"><ActionMenu emp={emp} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {isAddingEmployee && (
        <div className="fixed inset-0 z-[150] overflow-hidden">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setIsAddingEmployee(false)} />
          <div className="absolute inset-y-0 right-0 max-w-md w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
              <div className="flex items-center gap-4">
                <UserPlus size={24} />
                <h2 className="text-xl font-bold">New Profile</h2>
              </div>
              <button onClick={() => setIsAddingEmployee(false)} className="p-2 hover:bg-white/10 rounded-xl"><X size={24} /></button>
            </div>
            <form onSubmit={handleAddEmployee} className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              {formError && (
                <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 animate-in slide-in-from-top-2">
                  <AlertTriangle className="text-red-600 shrink-0" size={18} />
                  <p className="text-xs font-bold text-red-700">{formError}</p>
                </div>
              )}
              <div className="space-y-6">
                <div>
                  <div className="flex items-center justify-between mb-2 ml-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Employee ID</label>
                    <span className="text-[8px] font-black text-blue-900/40 uppercase">Required: SA-XXX</span>
                  </div>
                  <div className="relative">
                    <Fingerprint className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                    <input 
                      required 
                      placeholder="e.g. SA-005" 
                      className={`w-full pl-12 pr-5 py-4 bg-gray-50 border rounded-2xl outline-none focus:ring-4 transition-all font-bold text-sm ${
                        formError && formError.includes('ID') ? 'border-red-200 focus:ring-red-500/5' : 'border-gray-100 focus:ring-blue-500/5 focus:bg-white'
                      }`} 
                      value={newEmp.employeeId} 
                      onChange={e => {
                        setFormError(null);
                        setNewEmp({...newEmp, employeeId: e.target.value.toUpperCase()});
                      }} 
                    />
                  </div>
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                  <input required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" value={newEmp.name} onChange={e => setNewEmp({...newEmp, name: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Professional Email</label>
                  <input type="email" required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" value={newEmp.email} onChange={e => setNewEmp({...newEmp, email: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Password</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                    <input 
                      type={showInitialPass ? "text" : "password"} 
                      required 
                      className="w-full pl-12 pr-12 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" 
                      value={newEmp.password} 
                      onChange={e => setNewEmp({...newEmp, password: e.target.value})} 
                    />
                    <button type="button" onClick={() => setShowInitialPass(!showInitialPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400">
                      {showInitialPass ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Position</label>
                    <input required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm" value={newEmp.role} onChange={e => setNewEmp({...newEmp, role: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Department</label>
                    <select className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm" value={newEmp.department} onChange={e => setNewEmp({...newEmp, department: e.target.value})}>
                      {DEPARTMENTS.map(d => <option key={d}>{d}</option>)}
                    </select>
                  </div>
                </div>
              </div>
              <button type="submit" className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-bold text-sm uppercase tracking-widest shadow-xl shadow-blue-900/20 active:scale-95 transition-all">Initialize Profile</button>
            </form>
          </div>
        </div>
      )}

      {viewingEmployee && (
        <div className="fixed inset-0 z-[140] overflow-hidden">
          <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={() => setViewingEmployee(null)} />
          <div className="absolute inset-y-0 right-0 max-w-lg w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between">
              <h2 className="text-xl font-bold text-blue-900">Personnel File</h2>
              <button onClick={() => setViewingEmployee(null)} className="p-2 hover:bg-gray-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-8 no-scrollbar space-y-10">
              <div className="flex items-center gap-8">
                <img src={viewingEmployee.avatar} className="w-28 h-28 rounded-[2.5rem] object-cover shadow-2xl shadow-blue-900/10 border-4 border-white" alt="" />
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <Fingerprint size={12} className="text-blue-900/30" />
                    <span className="text-[10px] font-black text-blue-900/30 uppercase">{viewingEmployee.employeeId}</span>
                  </div>
                  <h3 className="text-2xl font-bold text-blue-900">{viewingEmployee.name}</h3>
                  <p className="text-gray-500 font-medium">{viewingEmployee.role}</p>
                  <div className="flex items-center gap-2 mt-2">
                    <StatusBadge status={viewingEmployee.status} />
                    <span className="text-[9px] font-black text-gray-400 uppercase border px-2 py-0.5 rounded-lg">{viewingEmployee.department}</span>
                  </div>
                </div>
              </div>
              <div className="space-y-6">
                <h4 className="text-xs font-black text-gray-400 uppercase flex items-center gap-2"><ShieldAlert size={16} className="text-orange-500" /> Access Overwrite</h4>
                <div className="rounded-[2rem] p-6 border bg-orange-50/50 border-orange-100 space-y-4">
                  <div className="relative">
                    <input 
                      type="password" 
                      placeholder="Input new access token..." 
                      className="w-full px-6 py-4 bg-white border border-orange-200 rounded-2xl text-sm outline-none font-bold" 
                      value={adminResetPass} 
                      onChange={(e) => setAdminResetPass(e.target.value)} 
                    />
                    <button onClick={handleAdminResetPassword} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-orange-600 text-white rounded-xl"><ShieldCheck size={20}/></button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Employees;

import React, { useState } from 'react';
import { 
  Lock, 
  ShieldCheck, 
  CheckCircle, 
  AlertTriangle, 
  Eye, 
  EyeOff, 
  Key, 
  LifeBuoy, 
  Fingerprint, 
  Mail, 
  ArrowLeft,
  ShieldAlert,
  X,
  UserCheck,
  Check
} from 'lucide-react';
import { User, Employee } from '../types';

interface SecurityProps {
  user: User;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
}

const Security: React.FC<SecurityProps> = ({ user, employees, setEmployees }) => {
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [showPass, setShowPass] = useState({ current: false, new: false, confirm: false });
  const [isUpdating, setIsUpdating] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // Recovery State
  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [recoveryStep, setRecoveryStep] = useState<'verify' | 'reset'>('verify');
  const [verifyId, setVerifyId] = useState('');
  const [verifyEmail, setVerifyEmail] = useState('');

  // Confirmation Modal State
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const currentEmployee = employees.find(e => e.id === user.id);

  const validateForm = () => {
    if (!currentEmployee) return false;

    if (!isRecoveryMode && currentPass !== currentEmployee.password) {
      setMessage({ type: 'error', text: 'The current access token you provided is incorrect.' });
      return false;
    }

    if (newPass !== confirmPass) {
      setMessage({ type: 'error', text: 'The new passwords do not match.' });
      return false;
    }

    if (newPass.length < 6) {
      setMessage({ type: 'error', text: 'New password must be at least 6 characters long.' });
      return false;
    }

    return true;
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    if (validateForm()) {
      setShowConfirmModal(true);
    }
  };

  const finalizeUpdate = () => {
    setShowConfirmModal(false);
    setIsUpdating(true);

    // Simulate update
    setTimeout(() => {
      setEmployees(prev => prev.map(emp => 
        emp.id === user.id ? { ...emp, password: newPass } : emp
      ));

      setIsUpdating(false);
      setMessage({ type: 'success', text: `Credential successfully ${isRecoveryMode ? 'recovered' : 'updated'}. Your account is now secure.` });

      // Reset everything
      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
      setIsRecoveryMode(false);
      setRecoveryStep('verify');
      setVerifyId('');
      setVerifyEmail('');
    }, 1200);
  };

  const handleVerifyIdentity = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);

    if (!currentEmployee) return;

    const matchesId = verifyId.trim() === currentEmployee.employeeId || verifyId.trim() === currentEmployee.id;
    const matchesEmail = verifyEmail.trim().toLowerCase() === currentEmployee.email.toLowerCase();

    if (matchesId && matchesEmail) {
      setRecoveryStep('reset');
    } else {
      setMessage({ type: 'error', text: 'Identity verification failed. Information does not match our records.' });
    }
  };

  const toggleShow = (field: keyof typeof showPass) => {
    setShowPass(prev => ({ ...prev, [field]: !prev[field] }));
  };

  const switchMode = (mode: boolean) => {
    setIsRecoveryMode(mode);
    setMessage(null);
    setRecoveryStep('verify');
    setCurrentPass('');
    setNewPass('');
    setConfirmPass('');
  };

  const StepIndicator = ({ currentStep }: { currentStep: 'verify' | 'reset' }) => (
    <div className="flex items-center gap-4 mb-8">
      <div className="flex items-center gap-2">
        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-black border-2 transition-all ${
          currentStep === 'verify' ? 'bg-purple-900 border-purple-900 text-white shadow-lg' : 'bg-green-500 border-green-500 text-white'
        }`}>
          {currentStep === 'reset' ? <Check size={14} /> : '1'}
        </div>
        <span className={`text-[10px] font-black uppercase tracking-widest ${currentStep === 'verify' ? 'text-purple-900' : 'text-gray-400'}`}>Verify Identity</span>
      </div>
      <div className={`h-[2px] w-8 rounded-full ${currentStep === 'reset' ? 'bg-green-500' : 'bg-gray-100'}`} />
      <div className="flex items-center gap-2">
        <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-black border-2 transition-all ${
          currentStep === 'reset' ? 'bg-purple-900 border-purple-900 text-white shadow-lg' : 'bg-gray-100 border-gray-200 text-gray-300'
        }`}>
          2
        </div>
        <span className={`text-[10px] font-black uppercase tracking-widest ${currentStep === 'reset' ? 'text-purple-900' : 'text-gray-300'}`}>New Token</span>
      </div>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900 uppercase tracking-tighter">Personnel Security</h1>
          <p className="text-gray-500 font-medium tracking-tight">Manage your digital identity and access credentials at Srinidhi Associates.</p>
        </div>
        {isRecoveryMode && (
          <button 
            onClick={() => switchMode(false)}
            className="flex items-center gap-2 text-xs font-bold text-blue-900 hover:text-blue-700 uppercase tracking-widest transition-all mb-1 group"
          >
            <ArrowLeft size={14} className="group-hover:-translate-x-1 transition-transform" /> 
            Back to Standard Update
          </button>
        )}
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className={`${isRecoveryMode ? 'bg-purple-900' : 'bg-blue-900'} p-8 rounded-[2.5rem] text-white shadow-xl transition-all duration-500`}>
            <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center mb-6">
              {isRecoveryMode ? <LifeBuoy size={24} /> : <ShieldCheck size={24} />}
            </div>
            <h3 className="font-bold text-lg mb-2">{isRecoveryMode ? 'Token Recovery' : 'Security Settings'}</h3>
            <p className="text-white/70 text-sm leading-relaxed mb-6 font-medium">
              {isRecoveryMode 
                ? 'Lost access? Follow the two-step verification process to securely reset your personnel token.'
                : 'Regularly updating your access token helps protect your sensitive payroll and performance data.'}
            </p>
            {isRecoveryMode && recoveryStep === 'verify' && (
              <div className="p-4 bg-white/5 rounded-2xl border border-white/10">
                <p className="text-[10px] font-black uppercase tracking-widest text-purple-200 mb-2">Instructions</p>
                <p className="text-xs text-purple-100/70 leading-relaxed">Please provide your unique Employee ID (e.g., SA-001) and your registered professional email to begin identity verification.</p>
              </div>
            )}
            {isRecoveryMode && recoveryStep === 'reset' && (
              <div className="p-4 bg-white/5 rounded-2xl border border-white/10">
                <p className="text-[10px] font-black uppercase tracking-widest text-green-300 mb-2">Step 2: Security</p>
                <p className="text-xs text-green-100/70 leading-relaxed">Verification successful. Create a strong new access token. Minimum 6 characters required.</p>
              </div>
            )}
          </div>

          <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm space-y-4">
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Digital Hygiene</h4>
            <div className="space-y-3">
              {[
                "At least 6 characters",
                "Uppercase & Lowercase mix",
                "Include numeric symbols",
                "Avoid birthday sequences"
              ].map((tip, i) => (
                <div key={i} className="flex items-center gap-2 text-xs font-bold text-gray-600">
                  <div className={`w-1.5 h-1.5 rounded-full ${isRecoveryMode ? 'bg-purple-600' : 'bg-blue-900'}`} />
                  {tip}
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border border-gray-100 shadow-sm relative overflow-hidden">
            <div className={`absolute top-0 right-0 p-8 text-gray-50 opacity-10 pointer-events-none transition-transform duration-700 ${isRecoveryMode ? 'translate-y-0 scale-110' : 'translate-y-4'}`}>
              {isRecoveryMode ? <ShieldAlert size={120} /> : <Lock size={120} />}
            </div>

            <h2 className={`text-xl font-bold mb-8 flex items-center gap-3 transition-colors duration-500 ${isRecoveryMode ? 'text-purple-900' : 'text-blue-900'}`}>
              {isRecoveryMode ? (recoveryStep === 'verify' ? <Fingerprint size={20} /> : <UserCheck size={20} />) : <Key size={20} />} 
              {isRecoveryMode ? (recoveryStep === 'verify' ? 'Identity Verification' : 'Define New Credentials') : 'Standard Token Update'}
            </h2>

            {isRecoveryMode && <StepIndicator currentStep={recoveryStep} />}

            {message && (
              <div className={`mb-8 p-4 rounded-2xl flex items-center gap-3 animate-in slide-in-from-top-2 duration-300 ${
                message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'
              }`}>
                {message.type === 'success' ? <CheckCircle size={20} /> : <AlertTriangle size={20} />}
                <p className="text-xs font-bold text-left">{message.text}</p>
              </div>
            )}

            {/* Recovery Mode: Step 1 - Verification */}
            {isRecoveryMode && recoveryStep === 'verify' && (
              <form onSubmit={handleVerifyIdentity} className="space-y-6 max-w-md animate-in slide-in-from-right-4 duration-300 relative z-10">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Unique Employee ID</label>
                  <div className="relative group">
                    <Fingerprint className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-purple-900 transition-colors" size={16} />
                    <input 
                      type="text" 
                      required
                      className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-purple-500/5 focus:bg-white focus:border-purple-900/20 transition-all font-bold text-sm text-purple-900 placeholder:text-gray-300"
                      placeholder="e.g. SA-001"
                      value={verifyId}
                      onChange={(e) => setVerifyId(e.target.value)}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Registered Work Email</label>
                  <div className="relative group">
                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-purple-900 transition-colors" size={16} />
                    <input 
                      type="email" 
                      required
                      className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-purple-500/5 focus:bg-white focus:border-purple-900/20 transition-all font-bold text-sm text-purple-900 placeholder:text-gray-300"
                      placeholder="Enter professional email"
                      value={verifyEmail}
                      onChange={(e) => setVerifyEmail(e.target.value)}
                    />
                  </div>
                </div>

                <button 
                  type="submit"
                  className="w-full mt-4 py-5 bg-purple-900 text-white rounded-[2rem] font-bold text-sm uppercase tracking-widest hover:bg-purple-800 transition-all shadow-xl shadow-purple-900/20 active:scale-95"
                >
                  Initiate Step 2 Verification
                </button>
              </form>
            )}

            {/* Standard Update or Recovery Step 2 (Reset) */}
            {(!isRecoveryMode || (isRecoveryMode && recoveryStep === 'reset')) && (
              <form onSubmit={handleFormSubmit} className="space-y-6 max-w-md animate-in slide-in-from-left-4 duration-300 relative z-10">
                {!isRecoveryMode ? (
                  <div className="space-y-2">
                    <div className="flex items-center justify-between ml-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Current Token</label>
                      <button 
                        type="button" 
                        onClick={() => switchMode(true)}
                        className="text-[9px] font-bold text-blue-900 hover:underline uppercase tracking-widest"
                      >
                        Lost Token?
                      </button>
                    </div>
                    <div className="relative group">
                      <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-blue-900 transition-colors" size={16} />
                      <input 
                        type={showPass.current ? "text" : "password"} 
                        required
                        className="w-full pl-12 pr-12 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900"
                        placeholder="Current personnel token"
                        value={currentPass}
                        onChange={(e) => setCurrentPass(e.target.value)}
                      />
                      <button type="button" onClick={() => toggleShow('current')} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-900 transition-colors">
                        {showPass.current ? <EyeOff size={16} /> : <Eye size={16} />}
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="p-5 bg-green-50 border border-green-200 rounded-3xl flex items-center gap-4 mb-6">
                    <div className="w-10 h-10 bg-green-500 text-white rounded-2xl flex items-center justify-center shrink-0 shadow-lg shadow-green-500/20">
                      <ShieldCheck size={20} />
                    </div>
                    <div>
                      <p className="text-xs font-black text-green-800 uppercase tracking-tight">Personnel Identity Verified</p>
                      <p className="text-[10px] text-green-700 font-bold opacity-70">Access granted to define new credentials.</p>
                    </div>
                  </div>
                )}

                <div className={`h-[1px] ${isRecoveryMode ? 'bg-purple-50' : 'bg-gray-50'} w-full my-8`} />

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">New Access Token</label>
                  <div className="relative group">
                    <ShieldCheck className={`absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 transition-colors ${isRecoveryMode ? 'group-focus-within:text-purple-900' : 'group-focus-within:text-blue-900'}`} size={16} />
                    <input 
                      type={showPass.new ? "text" : "password"} 
                      required
                      className={`w-full pl-12 pr-12 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 transition-all font-bold text-sm ${
                        isRecoveryMode 
                          ? 'focus:ring-purple-500/5 focus:border-purple-900/20 text-purple-900' 
                          : 'focus:ring-blue-500/5 focus:border-blue-900/20 text-blue-900'
                      }`}
                      placeholder="At least 6 characters"
                      value={newPass}
                      onChange={(e) => setNewPass(e.target.value)}
                    />
                    <button type="button" onClick={() => toggleShow('new')} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-900 transition-colors">
                      {showPass.new ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Confirm New Token</label>
                  <div className="relative group">
                    <ShieldCheck className={`absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 transition-colors ${isRecoveryMode ? 'group-focus-within:text-purple-900' : 'group-focus-within:text-blue-900'}`} size={16} />
                    <input 
                      type={showPass.confirm ? "text" : "password"} 
                      required
                      className={`w-full pl-12 pr-12 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 transition-all font-bold text-sm ${
                        isRecoveryMode 
                          ? 'focus:ring-purple-500/5 focus:border-purple-900/20 text-purple-900' 
                          : 'focus:ring-blue-500/5 focus:border-blue-900/20 text-blue-900'
                      }`}
                      placeholder="Repeat new token"
                      value={confirmPass}
                      onChange={(e) => setConfirmPass(e.target.value)}
                    />
                    <button type="button" onClick={() => toggleShow('confirm')} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-900 transition-colors">
                      {showPass.confirm ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                </div>

                <button 
                  type="submit"
                  disabled={isUpdating || (!isRecoveryMode && !currentPass) || !newPass || !confirmPass}
                  className={`w-full mt-4 py-5 text-white rounded-[2rem] font-bold text-sm uppercase tracking-widest transition-all shadow-xl active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed ${
                    isRecoveryMode 
                      ? 'bg-purple-900 hover:bg-purple-800 shadow-purple-900/20' 
                      : 'bg-blue-900 hover:bg-blue-800 shadow-blue-900/20'
                  }`}
                >
                  {isUpdating 
                    ? (isRecoveryMode ? "Resetting Credentials..." : "Hardening Credentials...") 
                    : (isRecoveryMode ? "Complete Identity Recovery" : "Commit Credential Change")}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      {showConfirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div 
            className="absolute inset-0 bg-blue-900/40 backdrop-blur-sm animate-in fade-in duration-300"
            onClick={() => setShowConfirmModal(false)}
          ></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-w-sm w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className={`w-20 h-20 ${isRecoveryMode ? 'bg-purple-50 text-purple-600' : 'bg-blue-50 text-blue-600'} rounded-[2rem] flex items-center justify-center mb-8 shadow-inner`}>
                <ShieldAlert size={36} />
              </div>
              <h2 className="text-2xl font-black text-blue-900 mb-2 uppercase tracking-tighter">Security Alert</h2>
              <p className="text-sm text-gray-500 mb-10 font-medium leading-relaxed">
                You are performing a sensitive modification to your organization access token. 
                {isRecoveryMode 
                  ? " This will override your forgotten token immediately." 
                  : " Please ensure you have memorized your new token securely."}
              </p>
              <div className="flex flex-col w-full gap-3">
                <button 
                  onClick={finalizeUpdate}
                  className={`w-full py-5 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 ${
                    isRecoveryMode 
                      ? 'bg-purple-900 hover:bg-purple-800 shadow-purple-900/20' 
                      : 'bg-blue-900 hover:bg-blue-800 shadow-blue-900/20'
                  }`}
                >
                  Verify & Proceed
                </button>
                <button 
                  onClick={() => setShowConfirmModal(false)}
                  className="w-full py-5 bg-gray-50 text-gray-400 rounded-2xl font-black uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Security;

import React, { useState } from 'react';
import { CheckCircle, Clock, Calendar, AlertCircle, CheckCircle2, CheckSquare, Square, X } from 'lucide-react';
import { Employee, Task } from '../types';

interface MyTasksProps {
  employee: Employee;
  onUpdateTask: (taskId: string, status: Task['status']) => void;
}

const MyTasks: React.FC<MyTasksProps> = ({ employee, onUpdateTask }) => {
  const [completingTaskIds, setCompletingTaskIds] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const tasks = employee.tasks || [];
  const incompleteTasks = tasks.filter(t => t.status !== 'Completed');
  const pendingCount = incompleteTasks.length;

  const handleMarkComplete = (taskId: string, title: string) => {
    if (window.confirm(`Mark "${title}" as completed?`)) {
      triggerCompletion([taskId]);
    }
  };

  const triggerCompletion = (ids: string[]) => {
    // Filter out already completing ones just in case
    setCompletingTaskIds(prev => [...prev, ...ids]);

    // Process each task
    ids.forEach(id => onUpdateTask(id, 'Completed'));

    // Clear selection
    setSelectedIds(prev => prev.filter(id => !ids.includes(id)));

    // Reset the animation state after it completes
    setTimeout(() => {
      setCompletingTaskIds(prev => prev.filter(id => !ids.includes(id)));
    }, 800);
  };

  const handleBulkComplete = () => {
    if (selectedIds.length === 0) return;
    if (window.confirm(`Mark ${selectedIds.length} selected tasks as completed?`)) {
      triggerCompletion(selectedIds);
    }
  };

  const toggleSelection = (id: string) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === incompleteTasks.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(incompleteTasks.map(t => t.id));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900 uppercase tracking-tighter">My Assignments</h1>
          <p className="text-gray-500 font-medium tracking-tight">Review and update your current workload at Srinidhi Associates.</p>
        </div>
        <div className="flex items-center gap-3">
          {incompleteTasks.length > 0 && (
            <button 
              onClick={toggleSelectAll}
              className="px-4 py-2 bg-white border border-gray-200 rounded-xl text-[10px] font-black uppercase tracking-widest text-gray-500 hover:bg-gray-50 transition-all shadow-sm"
            >
              {selectedIds.length === incompleteTasks.length ? 'Deselect All' : 'Select All Active'}
            </button>
          )}
          <div className="flex items-center gap-3 px-4 py-2 bg-blue-50 border border-blue-100 rounded-xl">
            <AlertCircle className="text-blue-600" size={18} />
            <span className="text-sm font-bold text-blue-900">{pendingCount} Active Tasks</span>
          </div>
        </div>
      </header>

      {tasks.length === 0 ? (
        <div className="bg-white rounded-[2.5rem] p-20 text-center border border-dashed border-gray-200 shadow-sm">
          <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-200">
            <CheckCircle2 size={40} />
          </div>
          <h3 className="text-xl font-bold text-blue-900">All caught up!</h3>
          <p className="text-gray-400 font-medium max-w-xs mx-auto mt-2 italic">
            No active assignments detected for your profile. Take a well-deserved breather.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {tasks.sort((a,b) => a.status === 'Completed' ? 1 : -1).map(task => {
            const isCompleting = completingTaskIds.includes(task.id);
            const isSelected = selectedIds.includes(task.id);
            const isCompleted = task.status === 'Completed';

            return (
              <div 
                key={task.id} 
                className={`group bg-white p-6 rounded-[2rem] border transition-all duration-500 flex flex-col md:flex-row md:items-center justify-between gap-6 relative overflow-hidden ${
                  isCompleting 
                    ? 'scale-[1.03] border-green-500 ring-4 ring-green-500/20 shadow-xl z-10' 
                    : isCompleted 
                      ? 'opacity-60 grayscale-[0.5] border-gray-100 bg-gray-50/30' 
                      : isSelected 
                        ? 'border-blue-900 bg-blue-50/30 shadow-md ring-4 ring-blue-900/5'
                        : 'hover:border-blue-200 border-gray-100 shadow-sm'
                }`}
              >
                {/* Completion Flash Overlay */}
                {isCompleting && (
                  <div className="absolute inset-0 bg-green-50/20 animate-pulse pointer-events-none" />
                )}

                <div className="flex items-center gap-4 flex-1">
                  {/* Selection Checkbox */}
                  {!isCompleted && !isCompleting && (
                    <button 
                      onClick={() => toggleSelection(task.id)}
                      className={`shrink-0 w-8 h-8 rounded-xl flex items-center justify-center transition-all ${
                        isSelected 
                          ? 'bg-blue-900 text-white shadow-lg shadow-blue-900/20' 
                          : 'bg-gray-100 text-gray-300 hover:text-blue-900 hover:bg-blue-50'
                      }`}
                    >
                      {isSelected ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                  )}

                  <div className="flex items-start gap-4 flex-1 min-w-0">
                    <div className={`p-4 rounded-2xl transition-all duration-500 ${
                      isCompleted || isCompleting ? 'bg-green-50 text-green-600' :
                      task.status === 'In Progress' ? 'bg-blue-900 text-white' :
                      'bg-gray-50 text-gray-400'
                    }`}>
                      {isCompleted || isCompleting ? (
                        <CheckCircle size={24} className={isCompleting ? 'animate-bounce' : ''} />
                      ) : (
                        <Clock size={24} />
                      )}
                    </div>
                    <div className="min-w-0">
                      <h3 className={`font-bold text-lg transition-all duration-500 truncate ${
                        isCompleted && !isCompleting ? 'line-through text-gray-400' : 'text-blue-900'
                      }`}>
                        {task.title}
                      </h3>
                      <div className="flex flex-wrap items-center gap-4 mt-2">
                        <div className="flex items-center gap-1.5 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                          <Calendar size={12} /> Due: {task.dueDate}
                        </div>
                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-lg uppercase tracking-[0.2em] border ${
                          task.priority === 'High' ? 'bg-red-50 text-red-600 border-red-100' :
                          task.priority === 'Medium' ? 'bg-yellow-50 text-yellow-600 border-yellow-100' :
                          'bg-gray-50 text-gray-500 border-gray-200'
                        }`}>
                          {task.priority} Priority
                        </span>
                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-lg uppercase tracking-[0.2em] border transition-colors duration-500 ${
                          isCompleted || isCompleting ? 'bg-green-50 text-green-700 border-green-100' :
                          task.status === 'In Progress' ? 'bg-blue-50 text-blue-900 border-blue-100' :
                          'bg-gray-100 text-gray-400 border-gray-200'
                        }`}>
                          {isCompleting ? 'Finalizing...' : task.status}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex gap-2">
                  {!isCompleted && !isCompleting && (
                    <>
                      {task.status !== 'In Progress' && (
                        <button 
                          onClick={() => onUpdateTask(task.id, 'In Progress')}
                          className="px-5 py-2.5 bg-gray-50 text-gray-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-50 hover:text-blue-900 transition-all active:scale-95"
                        >
                          Initialize
                        </button>
                      )}
                      <button 
                        onClick={() => handleMarkComplete(task.id, task.title)}
                        className="px-5 py-2.5 bg-blue-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-800 transition-all shadow-lg shadow-blue-900/10 active:scale-95"
                      >
                        Complete
                      </button>
                    </>
                  )}
                  {isCompleted && !isCompleting && (
                    <button 
                      onClick={() => onUpdateTask(task.id, 'Pending')}
                      className="px-5 py-2.5 bg-gray-100 text-gray-400 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-200 transition-all active:scale-95"
                    >
                      Restore
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Floating Bulk Action Bar */}
      {selectedIds.length > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-[100] animate-in slide-in-from-bottom-10 duration-500">
          <div className="bg-blue-900 text-white p-4 rounded-[2.5rem] shadow-2xl flex items-center justify-between border border-white/10 backdrop-blur-md">
            <div className="flex items-center gap-4 ml-4">
              <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center">
                <CheckSquare size={20} />
              </div>
              <div>
                <p className="text-xs font-black uppercase tracking-widest">{selectedIds.length} Selected</p>
                <p className="text-[10px] font-bold text-white/60 uppercase">Bulk Action Mode</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={handleBulkComplete}
                className="px-6 py-3 bg-white text-blue-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-50 transition-all active:scale-95 shadow-xl"
              >
                Complete Selected
              </button>
              <button 
                onClick={() => setSelectedIds([])}
                className="p-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl transition-all"
              >
                <X size={18} />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

