                      className="w-full pl-12 pr-12 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all font-bold text-sm" 
                      value={newEmp.password} 
