import React, { useState } from 'react';
import { CheckCircle, Clock, Calendar, AlertCircle, CheckCircle2, CheckSquare, Square, X } from 'lucide-react';
import { Employee, Task } from '../types';

interface MyTasksProps {
  employee: Employee;
  onUpdateTask: (taskId: string, status: Task['status']) => void;
}

const MyTasks: React.FC<MyTasksProps> = ({ employee, onUpdateTask }) => {
  const [completingTaskIds, setCompletingTaskIds] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const tasks = employee.tasks || [];
  const incompleteTasks = tasks.filter(t => t.status !== 'Completed');
  const pendingCount = incompleteTasks.length;

  const handleMarkComplete = (taskId: string, title: string) => {
    if (window.confirm(`Mark "${title}" as completed?`)) {
      triggerCompletion([taskId]);
    }
  };

  const triggerCompletion = (ids: string[]) => {
    // Filter out already completing ones just in case
    setCompletingTaskIds(prev => [...prev, ...ids]);

    // Process each task
    ids.forEach(id => onUpdateTask(id, 'Completed'));

    // Clear selection
    setSelectedIds(prev => prev.filter(id => !ids.includes(id)));

    // Reset the animation state after it completes
    setTimeout(() => {
      setCompletingTaskIds(prev => prev.filter(id => !ids.includes(id)));
    }, 800);
  };

  const handleBulkComplete = () => {
    if (selectedIds.length === 0) return;
    if (window.confirm(`Mark ${selectedIds.length} selected tasks as completed?`)) {
      triggerCompletion(selectedIds);
    }
  };

  const toggleSelection = (id: string) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const toggleSelectAll = () => {
    if (selectedIds.length === incompleteTasks.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(incompleteTasks.map(t => t.id));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900 uppercase tracking-tighter">My Assignments</h1>
          <p className="text-gray-500 font-medium tracking-tight">Review and update your current workload at Srinidhi Associates.</p>
        </div>
        <div className="flex items-center gap-3">
          {incompleteTasks.length > 0 && (
            <button 
              onClick={toggleSelectAll}
              className="px-4 py-2 bg-white border border-gray-200 rounded-xl text-[10px] font-black uppercase tracking-widest text-gray-500 hover:bg-gray-50 transition-all shadow-sm"
            >
              {selectedIds.length === incompleteTasks.length ? 'Deselect All' : 'Select All Active'}
            </button>
          )}
          <div className="flex items-center gap-3 px-4 py-2 bg-blue-50 border border-blue-100 rounded-xl">
            <AlertCircle className="text-blue-600" size={18} />
            <span className="text-sm font-bold text-blue-900">{pendingCount} Active Tasks</span>
          </div>
        </div>
      </header>

      {tasks.length === 0 ? (
        <div className="bg-white rounded-[2.5rem] p-20 text-center border border-dashed border-gray-200 shadow-sm">
          <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-200">
            <CheckCircle2 size={40} />
          </div>
          <h3 className="text-xl font-bold text-blue-900">All caught up!</h3>
          <p className="text-gray-400 font-medium max-w-xs mx-auto mt-2 italic">
            No active assignments detected for your profile. Take a well-deserved breather.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {tasks.sort((a,b) => a.status === 'Completed' ? 1 : -1).map(task => {
            const isCompleting = completingTaskIds.includes(task.id);
            const isSelected = selectedIds.includes(task.id);
            const isCompleted = task.status === 'Completed';
            const isInProgress = task.status === 'In Progress';

            return (
              <div 
                key={task.id} 
                className={`group bg-white p-6 rounded-[2rem] border transition-all duration-500 flex flex-col md:flex-row md:items-center justify-between gap-6 relative overflow-hidden ${
                  isCompleting 
                    ? 'scale-[1.03] border-green-500 ring-4 ring-green-500/20 shadow-xl z-10' 
                    : isCompleted 
                      ? 'opacity-60 grayscale-[0.5] border-gray-100 bg-gray-50/30' 
                      : isSelected 
                        ? 'border-blue-900 bg-blue-50/30 shadow-md ring-4 ring-blue-900/5'
                        : 'hover:border-blue-200 border-gray-100 shadow-sm'
                }`}
              >
                {/* Completion Flash Overlay */}
                {isCompleting && (
                  <div className="absolute inset-0 bg-green-50/20 animate-pulse pointer-events-none" />
                )}

                <div className="flex items-center gap-4 flex-1">
                  {/* Selection Checkbox */}
                  {!isCompleted && !isCompleting && (
                    <button 
                      onClick={() => toggleSelection(task.id)}
                      className={`shrink-0 w-8 h-8 rounded-xl flex items-center justify-center transition-all ${
                        isSelected 
                          ? 'bg-blue-900 text-white shadow-lg shadow-blue-900/20' 
                          : 'bg-gray-100 text-gray-300 hover:text-blue-900 hover:bg-blue-50'
                      }`}
                    >
                      {isSelected ? <CheckSquare size={18} /> : <Square size={18} />}
                    </button>
                  )}

                  <div className="flex items-start gap-4 flex-1 min-w-0">
                    <div className={`p-4 rounded-2xl transition-all duration-500 ${
                      isCompleted || isCompleting ? 'bg-green-100 text-green-700 shadow-sm' :
                      isInProgress ? 'bg-blue-900 text-white shadow-lg' :
                      'bg-gray-100 text-gray-400'
                    }`}>
                      {isCompleted || isCompleting ? (
                        <CheckCircle size={24} className={isCompleting ? 'animate-bounce' : ''} />
                      ) : (
                        <Clock size={24} />
                      )}
                    </div>
                    <div className="min-w-0">
                      <h3 className={`font-bold text-lg transition-all duration-500 truncate ${
                        isCompleted && !isCompleting ? 'line-through text-gray-400' : 'text-blue-900'
                      }`}>
                        {task.title}
                      </h3>
                      <div className="flex flex-wrap items-center gap-4 mt-2">
                        <div className="flex items-center gap-1.5 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                          <Calendar size={12} /> Due: {task.dueDate}
                        </div>
                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-lg uppercase tracking-[0.2em] border ${
                          task.priority === 'High' ? 'bg-red-50 text-red-600 border-red-100' :
                          task.priority === 'Medium' ? 'bg-yellow-50 text-yellow-600 border-yellow-100' :
                          'bg-gray-50 text-gray-500 border-gray-200'
                        }`}>
                          {task.priority} Priority
                        </span>
                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-lg uppercase tracking-[0.2em] border shadow-sm transition-all duration-500 ${
                          isCompleted || isCompleting ? 'bg-green-500 text-white border-green-600' :
                          isInProgress ? 'bg-blue-900 text-white border-blue-950' :
                          'bg-slate-100 text-slate-600 border-slate-200'
                        }`}>
                          {isCompleting ? 'Finalizing...' : task.status}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex gap-2">
                  {!isCompleted && !isCompleting && (
                    <>
                      {task.status !== 'In Progress' && (
                        <button 
                          onClick={() => onUpdateTask(task.id, 'In Progress')}
                          className="px-5 py-2.5 bg-gray-50 text-gray-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-50 hover:text-blue-900 transition-all active:scale-95"
                        >
                          Initialize
                        </button>
                      )}
                      <button 
                        onClick={() => handleMarkComplete(task.id, task.title)}
                        className="px-5 py-2.5 bg-blue-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-800 transition-all shadow-lg shadow-blue-900/10 active:scale-95"
                      >
                        Complete
                      </button>
                    </>
                  )}
                  {isCompleted && !isCompleting && (
                    <button 
                      onClick={() => onUpdateTask(task.id, 'Pending')}
                      className="px-5 py-2.5 bg-gray-100 text-gray-400 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-200 transition-all active:scale-95"
                    >
                      Restore
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Floating Bulk Action Bar */}
      {selectedIds.length > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-[100] animate-in slide-in-from-bottom-10 duration-500">
          <div className="bg-blue-900 text-white p-4 rounded-[2.5rem] shadow-2xl flex items-center justify-between border border-white/10 backdrop-blur-md">
            <div className="flex items-center gap-4 ml-4">
              <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center">
                <CheckSquare size={20} />
              </div>
              <div>
                <p className="text-xs font-black uppercase tracking-widest">{selectedIds.length} Selected</p>
                <p className="text-[10px] font-bold text-white/60 uppercase">Bulk Action Mode</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={handleBulkComplete}
                className="px-6 py-3 bg-white text-blue-900 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-50 transition-all active:scale-95 shadow-xl"
              >
                Complete Selected
              </button>
              <button 
                onClick={() => setSelectedIds([])}
                className="p-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl transition-all"
              >
                <X size={18} />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MyTasks;

import React, { useState } from 'react';
import { 
  Lock, 
  ShieldCheck, 
  CheckCircle, 
  AlertTriangle, 
  Eye, 
  EyeOff, 
  Key, 
  LifeBuoy, 
  Fingerprint, 
  Mail, 
  ArrowLeft,
  ShieldAlert,
  X,
  UserCheck,
  Check,
  History,
  Monitor,
  Globe,
  MapPin
} from 'lucide-react';
import { User, Employee } from '../types';

interface SecurityProps {
  user: User;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
}

const Security: React.FC<SecurityProps> = ({ user, employees, setEmployees }) => {
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [showPass, setShowPass] = useState({ current: false, new: false, confirm: false });
  const [isUpdating, setIsUpdating] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // Recovery State
  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [recoveryStep, setRecoveryStep] = useState<'verify' | 'reset'>('verify');
  const [verifyId, setVerifyId] = useState('');
  const [verifyEmail, setVerifyEmail] = useState('');

  // Confirmation Modal State
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const currentEmployee = employees.find(e => e.id === user.id);

  const validateForm = () => {
    if (!currentEmployee) return false;

    if (!isRecoveryMode && currentPass !== currentEmployee.password) {
      setMessage({ type: 'error', text: 'Authentication Failure: The current access token you provided is incorrect.' });
      return false;
    }

    if (newPass !== confirmPass) {
      setMessage({ type: 'error', text: 'Validation Error: The new tokens do not match. Please re-verify.' });
      return false;
    }

    if (newPass.length < 8) {
      setMessage({ type: 'error', text: 'Security Requirement: New access tokens must be at least 8 characters long for organizational safety.' });
      return false;
    }

    return true;
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    if (validateForm()) {
      setShowConfirmModal(true);
    }
  };

  const finalizeUpdate = () => {
    setShowConfirmModal(false);
    setIsUpdating(true);

    // Simulate update delay
    setTimeout(() => {
      setEmployees(prev => prev.map(emp => 
        emp.id === user.id ? { ...emp, password: newPass } : emp
      ));

      setIsUpdating(false);
      setMessage({ type: 'success', text: `Access Token successfully ${isRecoveryMode ? 'recovered' : 'updated'}. Your account credentials have been hardened.` });

      // Reset form fields
      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
      setIsRecoveryMode(false);
      setRecoveryStep('verify');
      setVerifyId('');
      setVerifyEmail('');
    }, 1200);
  };

  const handleVerifyIdentity = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);

    if (!currentEmployee) return;

    const matchesId = verifyId.trim().toUpperCase() === currentEmployee.employeeId.toUpperCase() || verifyId.trim() === currentEmployee.id;
    const matchesEmail = verifyEmail.trim().toLowerCase() === currentEmployee.email.toLowerCase();

    if (matchesId && matchesEmail) {
      setRecoveryStep('reset');
    } else {
      setMessage({ type: 'error', text: 'Verification Failed: The provided identifiers do not match our personnel registry.' });
    }
  };

  const toggleShow = (field: keyof typeof showPass) => {
    setShowPass(prev => ({ ...prev, [field]: !prev[field] }));
  };

  const switchMode = (mode: boolean) => {
    setIsRecoveryMode(mode);
    setMessage(null);
    setRecoveryStep('verify');
    setCurrentPass('');
    setNewPass('');
    setConfirmPass('');
  };

  // Mock Login History Data
  const loginHistory = [
    { device: 'Chrome on MacOS', location: 'Bengaluru, IN', time: 'Just now', ip: '106.51.XX.XX', status: 'Success' },
    { device: 'Safari on iPhone', location: 'Bengaluru, IN', time: '2 hours ago', ip: '106.51.XX.XX', status: 'Success' },
    { device: 'Chrome on MacOS', location: 'Bengaluru, IN', time: 'Yesterday, 09:15 AM', ip: '106.51.XX.XX', status: 'Success' },
    { device: 'Unknown Browser', location: 'London, UK', time: '3 days ago', ip: '45.12.XX.XX', status: 'Blocked Attempt' },
  ];

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-20">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-blue-900 uppercase tracking-tighter">Security Center</h1>
          <p className="text-gray-500 font-medium tracking-tight">Manage your digital identity, access tokens, and security audit logs.</p>
        </div>
        {isRecoveryMode && (
          <button 
            onClick={() => switchMode(false)}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-xl text-[10px] font-black text-blue-900 hover:bg-gray-50 uppercase tracking-widest transition-all shadow-sm active:scale-95"
          >
            <ArrowLeft size={14} /> Back to Standard Update
          </button>
        )}
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Left Column: Form Section */}
        <div className="xl:col-span-2 space-y-8">
          <section className="bg-white rounded-[3rem] p-8 md:p-12 border border-gray-100 shadow-xl shadow-blue-900/5 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-12 text-blue-900/5 pointer-events-none">
              {isRecoveryMode ? <ShieldAlert size={160} /> : <Lock size={160} />}
            </div>

            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-10">
                <div className={`p-4 rounded-3xl ${isRecoveryMode ? 'bg-purple-100 text-purple-900' : 'bg-blue-900 text-white shadow-lg shadow-blue-900/20'}`}>
                  {isRecoveryMode ? <LifeBuoy size={28} /> : <Key size={28} />}
                </div>
                <div>
                  <h2 className="text-2xl font-black text-blue-900 uppercase tracking-tighter leading-none">
                    {isRecoveryMode ? 'Access Token Recovery' : 'Account Protection'}
                  </h2>
                  <p className="text-gray-400 font-bold text-[10px] uppercase tracking-widest mt-1">
                    {isRecoveryMode ? 'Personnel Identity Verification' : 'Update your organizational credentials'}
                  </p>
                </div>
              </div>

              {message && (
                <div className={`mb-8 p-5 rounded-[2rem] flex items-center gap-4 animate-in slide-in-from-top-4 duration-300 ${
                  message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'
                }`}>
                  {message.type === 'success' ? <CheckCircle className="shrink-0" size={24} /> : <AlertTriangle className="shrink-0" size={24} />}
                  <p className="text-xs font-black uppercase tracking-tight leading-relaxed">{message.text}</p>
                </div>
              )}

              {/* Recovery Mode: Verification Form */}
              {isRecoveryMode && recoveryStep === 'verify' && (
                <form onSubmit={handleVerifyIdentity} className="space-y-6 max-w-lg animate-in slide-in-from-right-8">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Personnel Identifier (ID)</label>
                    <div className="relative group">
                      <Fingerprint className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-purple-900 transition-colors" size={20} />
                      <input 
                        type="text" 
                        required
                        className="w-full pl-14 pr-6 py-5 bg-gray-50 border border-transparent rounded-[1.5rem] outline-none focus:ring-4 focus:ring-purple-500/5 focus:bg-white focus:border-purple-900/20 transition-all font-bold text-sm text-purple-900"
                        placeholder="e.g. SA-001"
                        value={verifyId}
                        onChange={(e) => setVerifyId(e.target.value)}
                      />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Corporate Email Address</label>
                    <div className="relative group">
                      <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-purple-900 transition-colors" size={20} />
                      <input 
                        type="email" 
                        required
                        className="w-full pl-14 pr-6 py-5 bg-gray-50 border border-transparent rounded-[1.5rem] outline-none focus:ring-4 focus:ring-purple-500/5 focus:bg-white focus:border-purple-900/20 transition-all font-bold text-sm text-purple-900"
                        placeholder="yourname@srinidhi.com"
                        value={verifyEmail}
                        onChange={(e) => setVerifyEmail(e.target.value)}
                      />
                    </div>
                  </div>
                  <button 
                    type="submit"
                    className="w-full py-5 bg-purple-900 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-purple-800 transition-all shadow-xl shadow-purple-900/20 active:scale-95"
                  >
                    Initiate Recovery Verification
                  </button>
                </form>
              )}

              {/* Standard Change or Recovery Reset Form */}
              {(!isRecoveryMode || (isRecoveryMode && recoveryStep === 'reset')) && (
                <form onSubmit={handleFormSubmit} className="space-y-6 max-w-lg animate-in slide-in-from-left-8">
                  {!isRecoveryMode ? (
                    <div className="space-y-2">
                      <div className="flex items-center justify-between ml-1 mb-1">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Current Access Token</label>
                        <button 
                          type="button" 
                          onClick={() => switchMode(true)}
                          className="text-[9px] font-black text-blue-900 hover:underline uppercase tracking-[0.2em]"
                        >
                          Credential Recovery?
                        </button>
                      </div>
                      <div className="relative group">
                        <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-blue-900 transition-colors" size={20} />
                        <input 
                          type={showPass.current ? "text" : "password"} 
                          required
                          className="w-full pl-14 pr-14 py-5 bg-gray-50 border border-transparent rounded-[1.5rem] outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900"
                          placeholder="Current personnel token"
                          value={currentPass}
                          onChange={(e) => setCurrentPass(e.target.value)}
                        />
                        <button type="button" onClick={() => toggleShow('current')} className="absolute right-5 top-1/2 -translate-y-1/2 text-gray-300 hover:text-blue-900 transition-all">
                          {showPass.current ? <EyeOff size={18} /> : <Eye size={18} />}
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div className="p-6 bg-green-50 border border-green-100 rounded-[2rem] flex items-center gap-5 mb-8">
                      <div className="w-12 h-12 bg-green-500 text-white rounded-2xl flex items-center justify-center shrink-0 shadow-lg shadow-green-500/20">
                        <UserCheck size={24} />
                      </div>
                      <div>
                        <p className="text-sm font-black text-green-800 uppercase tracking-tight">Personnel Verified</p>
                        <p className="text-[10px] text-green-700 font-bold opacity-60 uppercase tracking-widest">Security clearance granted for token override.</p>
                      </div>
                    </div>
                  )}

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">New Access Token</label>
                      <div className="relative group">
                        <ShieldCheck className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-blue-900 transition-colors" size={18} />
                        <input 
                          type={showPass.new ? "text" : "password"} 
                          required
                          className="w-full pl-12 pr-12 py-5 bg-gray-50 border border-transparent rounded-[1.5rem] outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900"
                          placeholder="At least 8 chars"
                          value={newPass}
                          onChange={(e) => setNewPass(e.target.value)}
                        />
                        <button type="button" onClick={() => toggleShow('new')} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 hover:text-blue-900 transition-all">
                          {showPass.new ? <EyeOff size={16} /> : <Eye size={16} />}
                        </button>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Confirmation</label>
                      <div className="relative group">
                        <ShieldCheck className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-blue-900 transition-colors" size={18} />
                        <input 
                          type={showPass.confirm ? "text" : "password"} 
                          required
                          className="w-full pl-12 pr-12 py-5 bg-gray-50 border border-transparent rounded-[1.5rem] outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900"
                          placeholder="Repeat new token"
                          value={confirmPass}
                          onChange={(e) => setConfirmPass(e.target.value)}
                        />
                        <button type="button" onClick={() => toggleShow('confirm')} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 hover:text-blue-900 transition-all">
                          {showPass.confirm ? <EyeOff size={16} /> : <Eye size={16} />}
                        </button>
                      </div>
                    </div>
                  </div>

                  <button 
                    type="submit"
                    disabled={isUpdating || (!isRecoveryMode && !currentPass) || !newPass || !confirmPass}
                    className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed group"
                  >
                    {isUpdating ? (
                      <div className="flex items-center justify-center gap-3">
                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        Hardening Credentials...
                      </div>
                    ) : (
                      "Commit Credential Change"
                    )}
                  </button>
                </form>
              )}
            </div>
          </section>

          {/* Security Best Practices */}
          <section className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex items-start gap-6">
              <div className="p-3 bg-blue-50 text-blue-900 rounded-2xl"><ShieldCheck size={24} /></div>
              <div>
                <h3 className="text-sm font-black text-blue-900 uppercase tracking-tighter">Two-Factor Auth</h3>
                <p className="text-xs text-gray-400 font-medium mt-1">Multi-layered protection is currently enabled for all HR-privileged accounts.</p>
              </div>
            </div>
            <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm flex items-start gap-6">
              <div className="p-3 bg-orange-50 text-orange-600 rounded-2xl"><AlertTriangle size={24} /></div>
              <div>
                <h3 className="text-sm font-black text-blue-900 uppercase tracking-tighter">Token Strength</h3>
                <p className="text-xs text-gray-400 font-medium mt-1">Avoid sequential numbers or birthday strings to ensure maximal personnel data safety.</p>
              </div>
            </div>
          </section>
        </div>

        {/* Right Column: Security Audit Log */}
        <div className="space-y-8">
          <section className="bg-white rounded-[3rem] p-8 border border-gray-100 shadow-sm flex flex-col h-full">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-sm font-black text-blue-900 uppercase tracking-widest flex items-center gap-2">
                <History size={18} className="text-blue-900/30" /> Recent Access Logs
              </h2>
              <span className="text-[9px] font-black text-blue-900/30 uppercase border px-2 py-1 rounded-lg">Live Registry</span>
            </div>

            <div className="space-y-4 flex-1">
              {loginHistory.map((log, i) => (
                <div key={i} className="p-5 rounded-[1.5rem] border border-gray-50 bg-gray-50/20 hover:bg-white hover:border-blue-100 hover:shadow-md transition-all group">
                  <div className="flex items-start justify-between mb-3">
                    <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-xl ${log.status.includes('Blocked') ? 'bg-red-50 text-red-600' : 'bg-white text-blue-900 shadow-sm border border-gray-100'}`}>
                        <Monitor size={14} />
                      </div>
                      <p className="text-xs font-bold text-blue-900">{log.device}</p>
                    </div>
                    <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${
                      log.status.includes('Blocked') ? 'bg-red-500 text-white' : 'bg-green-100 text-green-700'
                    }`}>{log.status}</span>
                  </div>
                  <div className="space-y-1.5 pl-1">
                    <div className="flex items-center gap-2 text-[10px] text-gray-400 font-bold uppercase tracking-tight">
                      <MapPin size={10} /> {log.location}
                    </div>
                    <div className="flex items-center gap-2 text-[10px] text-gray-400 font-bold uppercase tracking-tight">
                      <Globe size={10} /> {log.ip}
                    </div>
                    <div className="flex items-center gap-2 text-[9px] text-blue-900/30 font-black uppercase tracking-[0.2em] mt-2">
                      <History size={10} /> {log.time}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <button className="w-full mt-8 py-4 bg-gray-50 text-gray-400 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-100 hover:text-blue-900 transition-all active:scale-95">
              Export Security Audit
            </button>
          </section>
        </div>
      </div>

      {/* Confirmation Modal */}
      {showConfirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div 
            className="absolute inset-0 bg-blue-900/40 backdrop-blur-sm animate-in fade-in duration-300"
            onClick={() => setShowConfirmModal(false)}
          ></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-w-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex flex-col items-center text-center">
              <div className={`w-24 h-24 ${isRecoveryMode ? 'bg-purple-50 text-purple-600' : 'bg-blue-50 text-blue-900'} rounded-[2.5rem] flex items-center justify-center mb-8 shadow-inner`}>
                <ShieldAlert size={48} />
              </div>
              <h2 className="text-3xl font-black text-blue-900 mb-2 uppercase tracking-tighter leading-none">Security Alert</h2>
              <p className="text-sm text-gray-500 mb-10 font-bold uppercase tracking-widest leading-relaxed">
                You are about to modify your organization-wide access token.
                {isRecoveryMode 
                  ? " This will override existing credentials immediately." 
                  : " Please ensure you have documented this change for future logins."}
              </p>
              <div className="flex flex-col w-full gap-3">
                <button 
                  onClick={finalizeUpdate}
                  className={`w-full py-5 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 ${
                    isRecoveryMode 
                      ? 'bg-purple-900 hover:bg-purple-800 shadow-purple-900/20' 
                      : 'bg-blue-900 hover:bg-blue-800 shadow-blue-900/20'
                  }`}
                >
                  Confirm & Commit Change
                </button>
                <button 
                  onClick={() => setShowConfirmModal(false)}
                  className="w-full py-5 bg-gray-50 text-gray-400 rounded-2xl font-black uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Security;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Search, MoreVertical, Plus, Trash2, X, ClipboardList, CheckCircle, 
  UserPlus, Building2, ShieldCheck, Download, Snowflake, Power, UserCheck,
  LayoutList, LayoutGrid, Rows3, ChevronDown, Fingerprint, FileText, Hash, UserCircle,
  Lock, Eye, EyeOff, ShieldAlert, KeyRound, AlertTriangle, Loader2, FolderInput,
  Calendar, Clock, User as UserIcon, FileDown, Mail, Square, CheckSquare, AlertCircle
} from 'lucide-react';
import { DEPARTMENTS } from '../constants';
import { Employee, Task, Document } from '../types';

interface EmployeesProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

type ViewMode = 'list' | 'grid' | 'compact';
type TaskFilterType = 'All' | 'No Tasks' | 'Has Tasks';

const Employees: React.FC<EmployeesProps> = ({ employees, setEmployees, addNotification }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [idFilter, setIdFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [taskFilter, setTaskFilter] = useState<TaskFilterType>('All');
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showBulkDeactivateConfirm, setShowBulkDeactivateConfirm] = useState(false);

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  const [formError, setFormError] = useState<string | null>(null);
  const [adminResetPass, setAdminResetPass] = useState('');
  const [resetSuccess, setResetSuccess] = useState(false);
  const [showInitialPass, setShowInitialPass] = useState(false);

  const [newEmp, setNewEmp] = useState({
    employeeId: '',
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    password: '',
    status: 'Active' as const
  });

  useEffect(() => {
    const handleClickOutside = () => setMenuOpenId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const idTerm = idFilter.toLowerCase();

    const matchesSearch = 
      emp.name.toLowerCase().includes(term) ||
      emp.role.toLowerCase().includes(term) ||
      emp.department.toLowerCase().includes(term) ||
      emp.email.toLowerCase().includes(term) ||
      emp.employeeId.toLowerCase().includes(term);

    const matchesId = !idFilter || emp.employeeId.toLowerCase().includes(idTerm);
    const matchesStatus = statusFilter === 'All' || emp.status === statusFilter;
    const matchesDept = deptFilter === 'All' || emp.department === deptFilter;

    const hasTasks = emp.tasks && emp.tasks.length > 0;
    const matchesTasks = 
      taskFilter === 'All' ? true :
      taskFilter === 'No Tasks' ? !hasTasks :
      taskFilter === 'Has Tasks' ? hasTasks : true;

    return matchesSearch && matchesId && matchesStatus && matchesDept && matchesTasks;
  });

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredEmployees.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(filteredEmployees.map(e => e.id));
    }
  };

  const toggleSelect = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const handleBulkDeactivate = () => {
    setEmployees(prev => prev.map(emp => 
      selectedIds.includes(emp.id) ? { ...emp, status: 'Inactive' } : emp
    ));
    selectedIds.forEach(id => {
      addNotification(id, "Account Status Updated", "Your organizational access has been set to Inactive by HR.");
    });
    setSelectedIds([]);
    setShowBulkDeactivateConfirm(false);
  };

  const handleExportCSV = () => {
    const headers = ['Employee ID', 'Name', 'Role', 'Department', 'Status'];
    const rows = filteredEmployees.map(emp => [
      emp.employeeId,
      emp.name,
      emp.role,
      emp.department,
      emp.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `srinidhi_personnel_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleUpdateStatus = (id: string, newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => 
      emp.id === id ? { ...emp, status: newStatus } : emp
    ));
    addNotification(id, `Status Update: ${newStatus}`, `Your account access has been set to ${newStatus}.`);
    setMenuOpenId(null);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    const idRegex = /^SA-\d{3}$/;
    if (!idRegex.test(newEmp.employeeId)) {
      setFormError("Employee ID must follow the format 'SA-XXX'.");
      return;
    }
    const isDuplicate = employees.some(emp => emp.employeeId.toUpperCase() === newEmp.employeeId.toUpperCase());
    if (isDuplicate) {
      setFormError(`Conflict: Employee ID '${newEmp.employeeId}' is already assigned.`);
      return;
    }
    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: [],
      documents: []
    };
    setEmployees([employee, ...employees]);
    setIsAddingEmployee(false);
    setNewEmp({ employeeId: '', name: '', role: '', department: DEPARTMENTS[0], email: '', password: '', status: 'Active' });
  };

  const handleAdminResetPassword = () => {
    if (!viewingEmployee || !adminResetPass.trim()) return;
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, password: adminResetPass } : emp
    ));
    addNotification(viewingEmployee.id, "Security: Credentials Reset", "An HR Administrator has updated your organizational access token.");
    setResetSuccess(true);
    setTimeout(() => setResetSuccess(false), 3000);
    setAdminResetPass('');
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;
    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, tasks: [...(emp.tasks || []), newTask] } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, tasks: [...(prev.tasks || []), newTask] } : null);
    addNotification(viewingEmployee.id, "New Assignment", `HR has assigned you a new task: ${newTaskTitle}`);
    setNewTaskTitle('');
  };

  const handleUpdateTaskStatus = (taskId: string, newStatus: Task['status']) => {
    if (!viewingEmployee) return;
    setEmployees(prev => prev.map(emp => {
      if (emp.id === viewingEmployee.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t)
        };
      }
      return emp;
    }));
    setViewingEmployee(prev => prev ? { ...prev, tasks: (prev.tasks || []).map(t => t.id === taskId ? { ...t, status: newStatus } : t) } : null);
  };

  const StatusBadge = ({ status }: { status: Employee['status'] }) => (
    <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
      status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
      status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
      status === 'Frozen' ? 'bg-blue-50 text-blue-700 border-blue-100' :
      'bg-gray-100 text-gray-500 border-gray-200'
    }`}>
      {status}
    </span>
  );

  const ActionMenu = ({ emp }: { emp: Employee }) => (
    <div className="relative inline-block text-left" onClick={(e) => e.stopPropagation()}>
      <button 
        onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === emp.id ? null : emp.id); }}
        className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all"
      >
        <MoreVertical size={18} />
      </button>

      {menuOpenId === emp.id && (
        <div className="absolute right-0 top-10 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
          <div className="p-2 space-y-1">
            <button onClick={() => handleUpdateStatus(emp.id, 'Active')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-green-700 hover:bg-green-50 flex items-center gap-3"><UserCheck size={14}/> Activate</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Frozen')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-blue-700 hover:bg-blue-50 flex items-center gap-3"><Snowflake size={14}/> Freeze</button>
            <button onClick={() => handleUpdateStatus(emp.id, 'Inactive')} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-red-600 hover:bg-red-50 flex items-center gap-3"><Power size={14}/> Deactivate</button>
            <div className="h-[1px] bg-gray-50 my-1" />
            <button onClick={() => setViewingEmployee(emp)} className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-500 hover:bg-gray-50 flex items-center gap-3"><ClipboardList size={14}/> Manage File</button>
          </div>
        </div>
      )}
    </div>
  );

  const renderListView = () => (
    <div key="list" className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden animate-in fade-in zoom-in-95 duration-500">
      <table className="w-full text-left">
        <thead>
          <tr className="bg-gray-50/50 border-b border-gray-100">
            <th className="px-6 py-5 w-10">
              <button onClick={toggleSelectAll} className={`w-5 h-5 rounded flex items-center justify-center transition-all ${selectedIds.length === filteredEmployees.length ? 'bg-blue-900 text-white' : 'bg-white border border-gray-300 text-transparent'}`}>
                {selectedIds.length === filteredEmployees.length ? <CheckSquare size={14} /> : <Square size={14} />}
              </button>
            </th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Employee ID</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Profile</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Department</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Actions</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-50">
          {filteredEmployees.map(emp => {
            const isSelected = selectedIds.includes(emp.id);
            return (
              <tr 
                key={emp.id} 
                onClick={() => setViewingEmployee(emp)} 
                className={`hover:bg-blue-50/30 transition-all cursor-pointer ${isSelected ? 'bg-blue-50/50' : ''}`}
              >
                <td className="px-6 py-4">
                  <button onClick={(e) => toggleSelect(emp.id, e)} className={`w-5 h-5 rounded flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-white border border-gray-200 text-transparent'}`}>
                    {isSelected ? <CheckSquare size={14} /> : <Square size={14} />}
                  </button>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-xs font-bold text-gray-400">{emp.employeeId}</td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center gap-4">
                    <img src={emp.avatar} alt="" className="w-10 h-10 rounded-2xl object-cover" />
                    <div>
                      <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                      <p className="text-[11px] text-gray-400 font-bold uppercase">{emp.role}</p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-[11px] font-bold text-gray-500 uppercase">{emp.department}</td>
                <td className="px-6 py-4 whitespace-nowrap"><StatusBadge status={emp.status} /></td>
                <td className="px-6 py-4 text-right"><ActionMenu emp={emp} /></td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );

  const renderGridView = () => (
    <div key="grid" className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 animate-in fade-in zoom-in-95 duration-500">
      {filteredEmployees.map(emp => {
        const isSelected = selectedIds.includes(emp.id);
        return (
          <div 
            key={emp.id} 
            onClick={() => setViewingEmployee(emp)}
            className={`bg-white p-6 rounded-[2.5rem] border transition-all cursor-pointer relative group ${isSelected ? 'border-blue-900 bg-blue-50/20 ring-4 ring-blue-900/5 shadow-md' : 'border-gray-100 shadow-sm hover:border-blue-200 hover:shadow-lg'}`}
          >
            <div className="absolute top-4 left-4 z-10">
              <button 
                onClick={(e) => toggleSelect(emp.id, e)} 
                className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-white/80 border border-gray-200 text-transparent hover:border-blue-400 backdrop-blur-sm opacity-0 group-hover:opacity-100'}`}
              >
                {isSelected ? <CheckSquare size={16} /> : <Square size={16} />}
              </button>
            </div>
            <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
              <ActionMenu emp={emp} />
            </div>
            <div className="flex flex-col items-center text-center">
              <img src={emp.avatar} alt="" className="w-20 h-20 rounded-[2rem] object-cover mb-4 shadow-md border-4 border-white" />
              <h3 className="text-sm font-bold text-blue-900 mb-1">{emp.name}</h3>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">{emp.role}</p>
              <div className="flex flex-col gap-2 w-full">
                <div className="flex items-center justify-between bg-gray-50 p-2 rounded-xl">
                  <span className="text-[9px] font-black text-gray-400 uppercase">Dept</span>
                  <span className="text-[10px] font-bold text-blue-900">{emp.department}</span>
                </div>
                <div className="flex items-center justify-between bg-gray-50 p-2 rounded-xl">
                  <span className="text-[9px] font-black text-gray-400 uppercase">ID</span>
                  <span className="text-[10px] font-bold text-blue-900">{emp.employeeId}</span>
                </div>
              </div>
              <div className="mt-4">
                <StatusBadge status={emp.status} />
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );

  const renderCompactView = () => (
    <div key="compact" className="space-y-2 animate-in fade-in zoom-in-95 duration-500">
      {filteredEmployees.map(emp => {
        const isSelected = selectedIds.includes(emp.id);
        return (
          <div 
            key={emp.id} 
