                     <button 
                       onClick={addTask}
                       disabled={!newTaskTitle.trim()}
                       className="w-full py-4 bg-blue-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-blue-800 disabled:opacity-50"
                     >
                       Initialize Assignment
