import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Employees from './pages/Employees';
import Recruitment from './pages/Recruitment';
import Performance from './pages/Performance';
import Documents from './pages/Documents';
import Attendance from './pages/Attendance';
import Security from './pages/Security';
import Login from './pages/Login';
import MyTasks from './pages/MyTasks';
import { Bell, Search, LogOut, X, Clock, ShieldAlert } from 'lucide-react';
import Logo from './components/Logo';
import { User, Employee, Notification, Task } from './types';
import { MOCK_EMPLOYEES } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);

  const currentEmployee = employees.find(e => e.id === user?.id);

  // Enforcement logic: If password change is required, lock the user to the security tab
  useEffect(() => {
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      setActiveTab('security');
    }
  }, [currentEmployee?.mustChangePassword, activeTab]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setShowNotifications(false);
  };

  const addNotification = (userId: string, title: string, message: string) => {
    const newNotif: Notification = {
      id: `notif-${Date.now()}`,
      userId,
      title,
      message,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };
    setNotifications(prev => [newNotif, ...prev]);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const userNotifications = notifications.filter(n => n.userId === user?.id || (user?.role === 'HR'));
  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleUpdateTaskStatus = (taskId: string, status: Task['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === user?.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status } : t)
        };
      }
      return emp;
    }));
  };

  const renderContent = () => {
    if (!user) return null;

    // If user must change password, restrict access to other pages
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'tasks': return currentEmployee ? <MyTasks employee={currentEmployee} onUpdateTask={handleUpdateTaskStatus} /> : <Dashboard />;
      case 'profiles': return user.role === 'HR' ? <Employees employees={employees} setEmployees={setEmployees} addNotification={addNotification} /> : <Dashboard />;
      case 'recruitment': return user.role === 'HR' ? <Recruitment /> : <Dashboard />;
      case 'performance': return <Performance />;
      case 'attendance': return <Attendance user={user} />;
      case 'documents': return (
        <Documents 
          user={user} 
          allEmployees={employees} 
          setEmployees={setEmployees} 
          addNotification={addNotification}
        />
      );
      case 'security': return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
      default: return <Dashboard />;
    }
  };

  // If user is not logged in, show the Login page
  if (!user) {
    return <Login onLogin={handleLogin} employees={employees} setEmployees={setEmployees} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        user={user} 
        disabled={!!currentEmployee?.mustChangePassword}
      />

      <main className="flex-1 md:ml-64 p-4 md:p-8">
        {currentEmployee?.mustChangePassword && (
          <div className="mb-6 p-4 bg-orange-50 border border-orange-200 rounded-2xl flex items-center justify-between animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-4 text-orange-800">
              <ShieldAlert size={20} className="shrink-0" />
              <p className="text-sm font-bold uppercase tracking-tight">Security Action Required: Mandatory access token update mandated by HR administration.</p>
            </div>
            <div className="px-3 py-1 bg-orange-100 text-orange-900 text-[10px] font-black rounded-lg uppercase">Restricted Mode</div>
          </div>
        )}

        <nav className="flex items-center justify-between mb-8 sticky top-0 bg-gray-50/80 backdrop-blur-md z-10 py-4">
          <div className="md:hidden flex items-center gap-2">
             <Logo className="w-8 h-8" />
             <span className="font-bold text-sm tracking-tight text-[#1e3a8a] uppercase">Srinidhi</span>
          </div>

          <div className="hidden md:flex items-center bg-white rounded-xl border border-gray-200 px-4 py-2 w-96 shadow-sm focus-within:ring-2 focus-within:ring-blue-500/20 transition-all">
            <Search className="text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Quick search records..." 
              className="bg-transparent border-none outline-none text-sm ml-2 w-full font-medium"
              disabled={!!currentEmployee?.mustChangePassword}
            />
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <button 
                onClick={() => {
                  setShowNotifications(!showNotifications);
                  if (!showNotifications) markAllAsRead();
                }}
                disabled={!!currentEmployee?.mustChangePassword}
                className="p-2 text-gray-400 hover:bg-white hover:text-blue-900 rounded-xl transition-all relative disabled:opacity-30"
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-gray-50"></span>
                )}
              </button>

              {showNotifications && (
                <div className="absolute right-0 mt-4 w-80 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
                    <h3 className="font-bold text-sm">Notifications</h3>
                    <button onClick={() => setShowNotifications(false)}><X size={16} /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto no-scrollbar">
                    {userNotifications.length === 0 ? (
                      <div className="p-8 text-center text-gray-400 text-sm italic">No recent notifications.</div>
                    ) : (
                      userNotifications.map(notif => (
                        <div key={notif.id} className="p-4 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                          <p className="text-sm font-bold text-blue-900">{notif.title}</p>
                          <p className="text-xs text-gray-600 mt-1">{notif.message}</p>
                          <div className="flex items-center gap-1 text-[10px] text-gray-400 mt-2 uppercase font-bold">
                            <Clock size={10} /> {notif.timestamp}
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  <div className="p-3 text-center bg-gray-50">
                    <button className="text-[10px] font-bold uppercase tracking-widest text-blue-900 hover:underline">View All Notifications</button>
                  </div>
                </div>
              )}
            </div>

            <button onClick={handleLogout} className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-xl transition-all"><LogOut size={20} /></button>
            <div className="h-8 w-[1px] bg-gray-200 mx-1"></div>
            <div className="flex items-center gap-3 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold group-hover:text-blue-900 transition-colors uppercase tracking-tight">{user.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-blue-900 flex items-center justify-center text-white border-2 border-white shadow-md overflow-hidden">
                <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
              </div>
            </div>
          </div>
        </nav>

        <div className="max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User as UserIcon, Lock, AlertCircle, Eye, EyeOff, Snowflake, Ban, Clock } from 'lucide-react';
import Logo from '../components/Logo';
import { UserRole, User, Employee } from '../types';
import { MOCK_EMPLOYEES } from '../constants';

interface LoginProps {
  onLogin: (user: User) => void;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
}

const Login: React.FC<LoginProps> = ({ onLogin, employees, setEmployees }) => {
  const [userId, setUserId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const LOCKOUT_THRESHOLD = 5;
  const LOCKOUT_DURATION_MS = 15 * 60 * 1000; // 15 minutes

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    // Simulate network delay
    setTimeout(() => {
      // Search for employee in current application state
      const employee = employees.find(emp => emp.id === userId.trim() || emp.employeeId === userId.trim());

      if (!employee) {
        setError('Invalid Personnel ID or Access Token. Please try again.');
        setIsLoading(false);
        return;
      }

      // Check account status
      if (employee.status === 'Frozen') {
        setError('ACCESS DENIED: Your account is temporarily frozen. Please contact the HR department.');
        setIsLoading(false);
        return;
      }

      if (employee.status === 'Inactive') {
        setError('ACCESS DENIED: This account has been deactivated and is no longer valid.');
        setIsLoading(false);
        return;
      }

      // Check for lockout
      if (employee.lockoutUntil) {
        const lockoutTime = new Date(employee.lockoutUntil).getTime();
        const now = Date.now();
        if (now < lockoutTime) {
          const remainingMinutes = Math.ceil((lockoutTime - now) / 60000);
          setError(`SECURITY LOCKOUT: Too many failed attempts. Access restricted for another ${remainingMinutes} minute(s).`);
          setIsLoading(false);
          return;
        }
      }

      if (employee.password === password) {
        // Successful login: Reset failed attempts and lockout
        setEmployees(prev => prev.map(emp => 
          emp.id === employee.id 
            ? { ...emp, failedLoginAttempts: 0, lockoutUntil: null } 
            : emp
        ));

        const userRole: UserRole = employee.role.includes('HR') ? 'HR' : 'Employee';
        const user: User = {
          id: employee.id,
          name: employee.name,
          role: userRole,
          email: employee.email,
          avatar: employee.avatar
        };
        onLogin(user);
      } else {
        // Failed login attempt
        const newFailedAttempts = (employee.failedLoginAttempts || 0) + 1;
        let newLockoutUntil = employee.lockoutUntil || null;

        if (newFailedAttempts >= LOCKOUT_THRESHOLD) {
          newLockoutUntil = new Date(Date.now() + LOCKOUT_DURATION_MS).toISOString();
          setError(`SECURITY LOCKOUT: 5 failed attempts reached. Account is now locked for 15 minutes.`);
        } else {
          setError(`Invalid Personnel ID or Access Token. Attempt ${newFailedAttempts} of ${LOCKOUT_THRESHOLD}.`);
        }

        setEmployees(prev => prev.map(emp => 
          emp.id === employee.id 
            ? { ...emp, failedLoginAttempts: newFailedAttempts, lockoutUntil: newLockoutUntil } 
            : emp
        ));

        setIsLoading(false);
      }
    }, 800);
  };

  return (
    <div className="min-h-screen bg-[#1e3a8a] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative Background Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-96 h-96 bg-blue-800/30 rounded-full blur-3xl"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-96 h-96 bg-blue-900/40 rounded-full blur-3xl"></div>

      <div className="bg-white rounded-[2rem] shadow-2xl p-8 md:p-12 max-w-md w-full text-center relative z-10 animate-in fade-in zoom-in-95 duration-700">
        <div className="flex justify-center mb-6">
          <Logo className="w-20 h-20 shadow-2xl shadow-blue-900/20" />
        </div>

        <div className="space-y-1 mb-10">
          <h1 className="text-2xl font-black text-[#1e3a8a] uppercase tracking-tighter">Srinidhi Associates</h1>
          <p className="text-gray-400 font-bold text-[10px] uppercase tracking-[0.2em]">Personnel Gateway</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 text-red-600 animate-in slide-in-from-top-2">
            {error.includes('frozen') ? <Snowflake size={18} className="flex-shrink-0" /> : 
             error.includes('LOCKOUT') ? <Clock size={18} className="flex-shrink-0" /> : <Ban size={18} className="flex-shrink-0" />}
            <p className="text-xs font-bold text-left leading-tight">{error}</p>
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-5">
          <div className="space-y-2 text-left">
            <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Personnel ID</label>
            <div className="relative group">
              <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-900 transition-colors" size={18} />
              <input 
                type="text" 
                required
                autoComplete="username"
                className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900 placeholder:text-gray-300"
                placeholder="e.g. SA-001 or emp-alice"
                value={userId}
                onChange={(e) => setUserId(e.target.value)}
              />
            </div>
          </div>

          <div className="space-y-2 text-left">
            <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Access Token</label>
            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-900 transition-colors" size={18} />
              <input 
                type={showPassword ? "text" : "password"} 
                required
                autoComplete="current-password"
                className="w-full pl-12 pr-12 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900 placeholder:text-gray-300"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <button 
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-900 transition-colors"
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          <button 
            type="submit"
            disabled={isLoading}
            className="w-full py-4 px-6 bg-[#1e3a8a] text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-800 transition-all flex items-center justify-center gap-3 shadow-xl shadow-blue-900/20 active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed group"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
            ) : (
              <>
                Initialize Access 
                <div className="p-1 bg-white/10 rounded-lg group-hover:bg-white/20 transition-colors">
                  <UserIcon size={14} />
                </div>
              </>
            )}
          </button>
        </form>

        <div className="mt-10 pt-6 border-t border-gray-50">
          <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest leading-loose">
            Security Notice: Unauthorized access is strictly prohibited. <br/>
            Account will be locked for 15 minutes after 5 failed attempts.
          </p>

          <div className="mt-4 flex flex-col gap-1 items-center">
            <p className="text-[8px] text-gray-300 font-bold uppercase tracking-widest">Demo Credentials</p>
            <div className="flex flex-wrap justify-center gap-2">
              <code className="text-[9px] text-blue-300 bg-blue-50 px-2 py-1 rounded">emp-diana / password123</code>
              <code className="text-[9px] text-blue-300 bg-blue-50 px-2 py-1 rounded">emp-alice / password123</code>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useMemo } from 'react';
import { 
  Lock, 
  ShieldCheck, 
  CheckCircle, 
  AlertTriangle, 
  Eye, 
  EyeOff, 
  Key, 
  LifeBuoy, 
  Fingerprint, 
  Mail, 
  ArrowLeft,
  ShieldAlert,
  X,
  UserCheck,
  Check,
  History,
  Monitor,
  Globe,
  MapPin,
  Zap,
  ShieldX,
  Info,
  CircleDot,
  ArrowRight,
  RefreshCcw,
  Sparkles,
  SearchCheck,
  ShieldQuestion,
  Clock
} from 'lucide-react';
import { User, Employee } from '../types';

interface SecurityProps {
  user: User;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

interface StrengthRequirement {
  id: string;
  label: string;
  met: boolean;
}

const Security: React.FC<SecurityProps> = ({ user, employees, setEmployees, addNotification }) => {
  const isHR = user.role === 'HR';
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [showPass, setShowPass] = useState({ current: false, new: false, confirm: false, global: false });
  const [isUpdating, setIsUpdating] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  // Recovery State
  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [recoveryStep, setRecoveryStep] = useState<'verify' | 'reset'>('verify');
  const [verifyId, setVerifyId] = useState('');
  const [verifyEmail, setVerifyEmail] = useState('');

  // Confirmation Modal State
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  // Global Reset State
  const [globalResetToken, setGlobalResetToken] = useState('');
  const [showGlobalResetModal, setShowGlobalResetModal] = useState(false);
  const [isPerformingGlobalReset, setIsPerformingGlobalReset] = useState(false);

  const currentEmployee = employees.find(e => e.id === user.id);

  // Real-time password strength calculation
  const strengthRequirements = useMemo((): StrengthRequirement[] => {
    return [
      { id: 'length', label: '8+ Characters', met: newPass.length >= 8 },
      { id: 'upper', label: 'Uppercase Letter', met: /[A-Z]/.test(newPass) },
      { id: 'lower', label: 'Lowercase Letter', met: /[a-z]/.test(newPass) },
      { id: 'number', label: 'Numerical Digit', met: /[0-9]/.test(newPass) },
      { id: 'special', label: 'Special Character (!@#$%^&*)', met: /[^A-Za-z0-9]/.test(newPass) },
    ];
  }, [newPass]);

  const strengthScore = strengthRequirements.filter(req => req.met).length;
  const isStrongEnough = strengthScore === strengthRequirements.length;

  const generateSecureToken = () => {
    const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789!@#$%&*";
    let token = "";
    for (let i = 0; i < 12; i++) {
      token += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setGlobalResetToken(token);
    if (!showPass.global) setShowPass(prev => ({ ...prev, global: true }));
  };

  const getStrengthLabel = () => {
    if (newPass.length === 0) return { label: 'None', color: 'bg-gray-100' };
    if (strengthScore <= 2) return { label: 'Weak', color: 'bg-red-500' };
    if (strengthScore <= 4) return { label: 'Moderate', color: 'bg-yellow-500' };
    return { label: 'Secure', color: 'bg-green-500' };
  };

  const validateForm = () => {
    if (!currentEmployee) return false;

    if (!isRecoveryMode && currentPass !== currentEmployee.password) {
      setMessage({ type: 'error', text: 'Authentication Failure: The current access token you provided is incorrect.' });
      return false;
    }

    if (newPass !== confirmPass) {
      setMessage({ type: 'error', text: 'Validation Error: The new tokens do not match. Please re-verify.' });
      return false;
    }

    if (!isStrongEnough) {
      setMessage({ type: 'error', text: 'Security Requirement: Your new token does not meet the organizational complexity standards.' });
      return false;
    }

    return true;
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    if (validateForm()) {
      setShowConfirmModal(true);
    }
  };

  const finalizeUpdate = () => {
    setShowConfirmModal(false);
    setIsUpdating(true);

    // Simulate update delay
    setTimeout(() => {
      setEmployees(prev => prev.map(emp => 
        emp.id === user.id ? { ...emp, password: newPass, mustChangePassword: false, failedLoginAttempts: 0, lockoutUntil: null } : emp
      ));

      setIsUpdating(false);
      setMessage({ type: 'success', text: `Access Token successfully ${isRecoveryMode ? 'recovered' : 'updated'}. Your account credentials have been hardened.` });

      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
      setIsRecoveryMode(false);
      setRecoveryStep('verify');
      setVerifyId('');
      setVerifyEmail('');
    }, 1200);
  };

  const handleGlobalReset = () => {
    if (!globalResetToken || globalResetToken.length < 8) return;

    setIsPerformingGlobalReset(true);

    setTimeout(() => {
      setEmployees(prev => {
        const updated = prev.map(emp => {
          // Send notification to each employee
          addNotification(
            emp.id, 
            "Mandatory Security Reset", 
            `A global security override has been performed. Your password is now: ${globalResetToken}. You are REQUIRED to change this upon your next dashboard access.`
          );

          return {
            ...emp,
            password: globalResetToken,
            mustChangePassword: true,
            failedLoginAttempts: 0,
            lockoutUntil: null
          };
        });
        return updated;
      });

      setIsPerformingGlobalReset(false);
      setShowGlobalResetModal(false);
      setGlobalResetToken('');
      setMessage({ type: 'success', text: `SYSTEM OVERRIDE SUCCESSFUL: All ${employees.length} personnel credentials have been synchronized and flagged for mandatory rotation.` });
    }, 2000);
  };

  const handleVerifyIdentity = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);

    if (!currentEmployee) return;

    const matchesId = verifyId.trim().toUpperCase() === currentEmployee.employeeId.toUpperCase() || verifyId.trim() === currentEmployee.id;
    const matchesEmail = verifyEmail.trim().toLowerCase() === currentEmployee.email.toLowerCase();

    if (matchesId && matchesEmail) {
      setRecoveryStep('reset');
      setMessage({ type: 'success', text: 'Identity Verified. Proceeding to credential reset stage.' });
    } else {
      setMessage({ type: 'error', text: 'Verification Failed: The provided identifiers do not match our personnel registry.' });
    }
  };

  const toggleShow = (field: keyof typeof showPass) => {
    setShowPass(prev => ({ ...prev, [field]: !prev[field] }));
  };

