import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Employees from './pages/Employees';
import Recruitment from './pages/Recruitment';
import Performance from './pages/Performance';
import Documents from './pages/Documents';
import Attendance from './pages/Attendance';
import Security from './pages/Security';
import Login from './pages/Login';
import MyTasks from './pages/MyTasks';
import { Bell, Search, LogOut, X, Clock, ShieldAlert, Sparkles, PartyPopper, CheckCircle2 } from 'lucide-react';
import Logo from './components/Logo';
import { User, Employee, Notification, Task } from './types';
import { MOCK_EMPLOYEES } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showWelcome, setShowWelcome] = useState(false);

  const currentEmployee = employees.find(e => e.id === user?.id);

  // Enforcement logic: If password change is required, lock the user to the security tab
  useEffect(() => {
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      setActiveTab('security');
    }
  }, [currentEmployee?.mustChangePassword, activeTab]);

  // Handle welcome screen visibility
  useEffect(() => {
    if (user && currentEmployee && !currentEmployee.hasLoggedInBefore) {
      setShowWelcome(true);
    }
  }, [user, currentEmployee]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setShowNotifications(false);
    setShowWelcome(false);
  };

  const handleFinishWelcome = () => {
    if (user) {
      setEmployees(prev => prev.map(emp => 
        emp.id === user.id ? { ...emp, hasLoggedInBefore: true } : emp
      ));
    }
    setShowWelcome(false);
  };

  const addNotification = (userId: string, title: string, message: string) => {
    const newNotif: Notification = {
      id: `notif-${Date.now()}`,
      userId,
      title,
      message,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };
    setNotifications(prev => [newNotif, ...prev]);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const userNotifications = notifications.filter(n => n.userId === user?.id || (user?.role === 'HR'));
  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleUpdateTaskStatus = (taskId: string, status: Task['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === user?.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status } : t)
        };
      }
      return emp;
    }));
  };

  const renderContent = () => {
    if (!user) return null;

    // If user must change password, restrict access to other pages
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'tasks': return currentEmployee ? <MyTasks employee={currentEmployee} onUpdateTask={handleUpdateTaskStatus} /> : <Dashboard />;
      case 'profiles': return user.role === 'HR' ? <Employees employees={employees} setEmployees={setEmployees} addNotification={addNotification} /> : <Dashboard />;
      case 'recruitment': return user.role === 'HR' ? <Recruitment /> : <Dashboard />;
      case 'performance': return <Performance />;
      case 'attendance': return <Attendance user={user} />;
      case 'documents': return (
        <Documents 
          user={user} 
          allEmployees={employees} 
          setEmployees={setEmployees} 
          addNotification={addNotification}
        />
      );
      case 'security': return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
      default: return <Dashboard />;
    }
  };

  // If user is not logged in, show the Login page
  if (!user) {
    return <Login onLogin={handleLogin} employees={employees} setEmployees={setEmployees} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Welcome Screen Modal */}
      {showWelcome && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-[#1e3a8a]/95 backdrop-blur-xl animate-in fade-in duration-700">
          <div className="max-w-2xl w-full bg-white rounded-[3rem] p-12 text-center relative overflow-hidden shadow-2xl animate-in zoom-in-95 duration-500">
            {/* Decorative background shapes */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-blue-50 rounded-full -mr-32 -mt-32 opacity-50 blur-3xl"></div>
            <div className="absolute bottom-0 left-0 w-64 h-64 bg-purple-50 rounded-full -ml-32 -mb-32 opacity-50 blur-3xl"></div>

            <div className="relative z-10 flex flex-col items-center">
              <div className="w-24 h-24 bg-blue-900 rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl shadow-blue-900/20 rotate-3 transition-transform hover:rotate-0">
                <Logo className="w-16 h-16" />
              </div>

              <div className="space-y-4 mb-10">
                <div className="flex items-center justify-center gap-3 text-blue-600">
                  <Sparkles size={20} />
                  <span className="text-[10px] font-black uppercase tracking-[0.3em]">Official Onboarding</span>
                  <Sparkles size={20} />
                </div>
                <h1 className="text-4xl font-black text-blue-900 uppercase tracking-tighter serif leading-tight">
                  Welcome to the <br/> Srinidhi Family
                </h1>
                <p className="text-gray-500 font-medium text-lg max-w-md mx-auto">
                  Hello, <span className="text-blue-900 font-bold">{user.name}</span>. We're thrilled to have you join our world-class team of professionals.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full mb-10">
                <div className="p-6 bg-gray-50 rounded-3xl border border-gray-100 flex flex-col items-center text-center">
                  <div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-blue-900 mb-3">
                    <CheckCircle2 size={20} />
                  </div>
                  <h3 className="text-xs font-black text-blue-900 uppercase tracking-widest mb-1">Onboarding Active</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">Email dispatched to HR Desk</p>
                </div>
                <div className="p-6 bg-gray-50 rounded-3xl border border-gray-100 flex flex-col items-center text-center">
                  <div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-purple-600 mb-3">
                    <PartyPopper size={20} />
                  </div>
                  <h3 className="text-xs font-black text-blue-900 uppercase tracking-widest mb-1">Growth Ready</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">Your digital workspace is primed</p>
                </div>
              </div>

              <button 
                onClick={handleFinishWelcome}
                className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 active:scale-95 group flex items-center justify-center gap-3"
              >
                Initialize Workspace
                <Sparkles size={18} className="group-hover:rotate-12 transition-transform" />
              </button>

              <p className="mt-6 text-[9px] text-gray-400 font-bold uppercase tracking-[0.2em]">
                Securely synchronized with saisurendra@srinidhiassociates.co.in
              </p>
            </div>
          </div>
        </div>
      )}

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        user={user} 
        disabled={!!currentEmployee?.mustChangePassword}
      />

      <main className="flex-1 md:ml-64 p-4 md:p-8">
        {currentEmployee?.mustChangePassword && (
          <div className="mb-6 p-4 bg-orange-50 border border-orange-200 rounded-2xl flex items-center justify-between animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-4 text-orange-800">
              <ShieldAlert size={20} className="shrink-0" />
              <p className="text-sm font-bold uppercase tracking-tight">Security Action Required: Mandatory access token update mandated by HR administration.</p>
            </div>
            <div className="px-3 py-1 bg-orange-100 text-orange-900 text-[10px] font-black rounded-lg uppercase">Restricted Mode</div>
          </div>
        )}

        <nav className="flex items-center justify-between mb-8 sticky top-0 bg-gray-50/80 backdrop-blur-md z-10 py-4">
          <div className="md:hidden flex items-center gap-2">
             <Logo className="w-8 h-8" />
             <span className="font-bold text-sm tracking-tight text-[#1e3a8a] uppercase">Srinidhi</span>
          </div>

          <div className="hidden md:flex items-center bg-white rounded-xl border border-gray-200 px-4 py-2 w-96 shadow-sm focus-within:ring-2 focus-within:ring-blue-500/20 transition-all">
            <Search className="text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Quick search records..." 
              className="bg-transparent border-none outline-none text-sm ml-2 w-full font-medium"
              disabled={!!currentEmployee?.mustChangePassword}
            />
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <button 
                onClick={() => {
                  setShowNotifications(!showNotifications);
                  if (!showNotifications) markAllAsRead();
                }}
                disabled={!!currentEmployee?.mustChangePassword}
                className="p-2 text-gray-400 hover:bg-white hover:text-blue-900 rounded-xl transition-all relative disabled:opacity-30"
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-gray-50"></span>
                )}
              </button>

              {showNotifications && (
                <div className="absolute right-0 mt-4 w-80 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
                    <h3 className="font-bold text-sm">Notifications</h3>
                    <button onClick={() => setShowNotifications(false)}><X size={16} /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto no-scrollbar">
                    {userNotifications.length === 0 ? (
                      <div className="p-8 text-center text-gray-400 text-sm italic">No recent notifications.</div>
                    ) : (
                      userNotifications.map(notif => (
                        <div key={notif.id} className="p-4 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                          <p className="text-sm font-bold text-blue-900">{notif.title}</p>
                          <p className="text-xs text-gray-600 mt-1">{notif.message}</p>
                          <div className="flex items-center gap-1 text-[10px] text-gray-400 mt-2 uppercase font-bold">
                            <Clock size={10} /> {notif.timestamp}
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  <div className="p-3 text-center bg-gray-50">
                    <button className="text-[10px] font-bold uppercase tracking-widest text-blue-900 hover:underline">View All Notifications</button>
                  </div>
                </div>
              )}
            </div>

            <button onClick={handleLogout} className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-xl transition-all"><LogOut size={20} /></button>
            <div className="h-8 w-[1px] bg-gray-200 mx-1"></div>
            <div className="flex items-center gap-3 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold group-hover:text-blue-900 transition-colors uppercase tracking-tight">{user.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-blue-900 flex items-center justify-center text-white border-2 border-white shadow-md overflow-hidden">
                <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
              </div>
            </div>
          </div>
        </nav>

        <div className="max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Search, MoreVertical, Plus, Trash2, X, ClipboardList, CheckCircle, 
  UserPlus, Snowflake, Power, UserCheck,
  LayoutList, LayoutGrid, Rows3, ChevronDown, Fingerprint, Hash, UserCircle,
  Lock, ShieldAlert, AlertTriangle, 
  User as UserIcon, FileDown, Square, CheckSquare, 
  UserMinus, UserX,
  TriangleAlert,
  Activity,
  Clock,
  Eye,
  EyeOff,
  Unlock,
  MailCheck
} from 'lucide-react';
import { DEPARTMENTS } from '../constants';
import { Employee, Task } from '../types';

interface EmployeesProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

type ViewMode = 'list' | 'grid' | 'compact';
type TaskFilterType = 'All' | 'No Tasks' | 'Has Tasks';

const Employees: React.FC<EmployeesProps> = ({ employees, setEmployees, addNotification }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [idFilter, setIdFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [taskFilter, setTaskFilter] = useState<TaskFilterType>('All');
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showNewEmpPassword, setShowNewEmpPassword] = useState(false);

  // Deletion/Freeze States
  const [employeeToDelete, setEmployeeToDelete] = useState<Employee | null>(null);
  const [employeeToFreeze, setEmployeeToFreeze] = useState<Employee | null>(null);
  const [isDeleteConfirmed, setIsDeleteConfirmed] = useState(false);
  const [showBulkDeleteConfirm, setShowBulkDeleteConfirm] = useState(false);

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  const [formError, setFormError] = useState<string | null>(null);
  const [adminResetPass, setAdminResetPass] = useState('');
  const [resetSuccess, setResetSuccess] = useState(false);

  // Task search state for the slide-over
  const [taskSearchTerm, setTaskSearchTerm] = useState('');

  const [newEmp, setNewEmp] = useState({
    employeeId: '',
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    password: 'Password123!',
    status: 'Active' as const
  });

  // Real-time validation states
  const idRegex = /^SA-\d{3}$/;
  const isIdFormatValid = idRegex.test(newEmp.employeeId);
  const isIdUnique = !employees.some(emp => emp.employeeId.toUpperCase() === newEmp.employeeId.toUpperCase());
  const canSubmit = isIdFormatValid && isIdUnique && newEmp.name && newEmp.email && newEmp.role && newEmp.password;

  useEffect(() => {
    const handleClickOutside = () => setMenuOpenId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const idTerm = idFilter.toLowerCase();

    const matchesSearch = 
      emp.name.toLowerCase().includes(term) ||
      emp.role.toLowerCase().includes(term) ||
      emp.department.toLowerCase().includes(term) ||
      emp.email.toLowerCase().includes(term) ||
      emp.employeeId.toLowerCase().includes(term);

    const matchesId = !idFilter || emp.employeeId.toLowerCase().includes(idTerm);
    const matchesStatus = statusFilter === 'All' || emp.status === statusFilter;
    const matchesDept = deptFilter === 'All' || emp.department === deptFilter;

    const hasTasks = emp.tasks && emp.tasks.length > 0;
    const matchesTasks = 
      taskFilter === 'All' ? true :
      taskFilter === 'No Tasks' ? !hasTasks :
      taskFilter === 'Has Tasks' ? hasTasks : true;

    return matchesSearch && matchesId && matchesStatus && matchesDept && matchesTasks;
  });

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredEmployees.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(filteredEmployees.map(e => e.id));
    }
  };

  const toggleSelect = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const updateEmployeeStatus = (id: string, newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === id) {
        const statusMap = {
          'Active': { title: 'Account Activated', msg: 'Your professional access has been restored by HR.' },
          'Inactive': { title: 'Account Deactivated', msg: 'Your account has been moved to inactive status.' },
          'Frozen': { title: 'Account Frozen', msg: 'Your account has been temporarily frozen for security purposes.' },
          'On Leave': { title: 'Leave Approved', msg: 'Your status has been updated to On Leave.' }
        };
        const notify = statusMap[newStatus];
        addNotification(id, notify.title, notify.msg);
        return { ...emp, status: newStatus };
      }
      return emp;
    }));
    setMenuOpenId(null);
  };

  const unlockEmployee = (id: string) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === id) {
        addNotification(id, "Security: Account Unlocked", "An HR Administrator has reset your failed login attempts and restored access.");
        return { ...emp, failedLoginAttempts: 0, lockoutUntil: null };
      }
      return emp;
    }));
    if (viewingEmployee?.id === id) {
      setViewingEmployee(prev => prev ? { ...prev, failedLoginAttempts: 0, lockoutUntil: null } : null);
    }
    setMenuOpenId(null);
  };

  const handleBulkDelete = () => {
    if (!isDeleteConfirmed) return;
    setEmployees(prev => prev.filter(emp => !selectedIds.includes(emp.id)));
    setSelectedIds([]);
    setShowBulkDeleteConfirm(false);
    setIsDeleteConfirmed(false);
  };

  const handleDeleteEmployee = () => {
    if (!employeeToDelete || !isDeleteConfirmed) return;
    setEmployees(prev => prev.filter(emp => emp.id !== employeeToDelete.id));
    setEmployeeToDelete(null);
    setIsDeleteConfirmed(false);
    setMenuOpenId(null);
  };

  const handleFreezeEmployee = () => {
    if (!employeeToFreeze || !isDeleteConfirmed) return;
    updateEmployeeStatus(employeeToFreeze.id, 'Frozen');
    setEmployeeToFreeze(null);
    setIsDeleteConfirmed(false);
  };

  const handleExportCSV = () => {
    const headers = ['Employee ID', 'Name', 'Role', 'Department', 'Status'];
    const rows = filteredEmployees.map(emp => [
      emp.employeeId,
      emp.name,
      emp.role,
      emp.department,
      emp.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `srinidhi_personnel_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    if (!isIdFormatValid) {
      setFormError("Format Mismatch: Employee ID must strictly follow the 'SA-XXX' pattern.");
      return;
    }

    if (!isIdUnique) {
      setFormError(`Registry Conflict: The identifier '${newEmp.employeeId}' is already permanently assigned.`);
      return;
    }

    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: [],
      documents: [],
      failedLoginAttempts: 0,
      lockoutUntil: null,
      hasLoggedInBefore: false // Trigger welcome screen for new user
    };

    setEmployees([employee, ...employees]);
    setIsAddingEmployee(false);

    // Simulate automated onboarding dispatch
    console.log(`ONBOARDING DISPATCH: Sending credentials and welcome package to ${newEmp.email}`);
    console.log(`ONBOARDING DISPATCH: Notifying HR Administrator saisurendra@srinidhiassociates.co.in`);

    setNewEmp({ employeeId: '', name: '', role: '', department: DEPARTMENTS[0], email: '', password: 'Password123!', status: 'Active' });
    setShowNewEmpPassword(false);

    // Visual confirmation for HR
    alert(`Onboarding Initiated:\nPersonnel profile for ${employee.name} created.\nWelcome credentials dispatched to ${employee.email} and HR Desk (saisurendra@srinidhiassociates.co.in).`);
  };

  const handleAdminResetPassword = () => {
    if (!viewingEmployee || !adminResetPass.trim()) return;
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, password: adminResetPass, failedLoginAttempts: 0, lockoutUntil: null } : emp
    ));
    addNotification(viewingEmployee.id, "Security: Credentials Reset", "An HR Administrator has updated your organizational access token.");
    setResetSuccess(true);
    setTimeout(() => setResetSuccess(false), 3000);
    setAdminResetPass('');
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;
    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, tasks: [...(emp.tasks || []), newTask] } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, tasks: [...(prev.tasks || []), newTask] } : null);
    addNotification(viewingEmployee.id, "New Assignment", `HR has assigned you a new task: ${newTaskTitle}`);
    setNewTaskTitle('');
  };

  const filteredMemberTasks = useMemo(() => {
    if (!viewingEmployee) return [];
    const tasks = viewingEmployee.tasks || [];
    if (!taskSearchTerm.trim()) return tasks;
    return tasks.filter(t => 
      t.title.toLowerCase().includes(taskSearchTerm.toLowerCase())
    );
  }, [viewingEmployee, taskSearchTerm]);

  const StatusBadge = ({ emp }: { emp: Employee }) => {
    const isLocked = emp.lockoutUntil && new Date(emp.lockoutUntil).getTime() > Date.now();
    return (
      <div className="flex flex-col gap-1 items-start">
        <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
          emp.status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
          emp.status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
          emp.status === 'Frozen' ? 'bg-blue-50 text-blue-700 border-blue-100' :
          'bg-gray-100 text-gray-500 border-gray-200'
        }`}>
          {emp.status}
        </span>
        {isLocked && (
          <span className="bg-red-50 text-red-600 border border-red-100 px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest flex items-center gap-1">
            <Lock size={8} /> Locked Out
          </span>
        )}
      </div>
    );
  };

  const ActionMenu = ({ emp }: { emp: Employee }) => {
    const isLocked = emp.lockoutUntil && new Date(emp.lockoutUntil).getTime() > Date.now();
    return (
      <div className="relative inline-block text-left" onClick={(e) => e.stopPropagation()}>
        <button 
          onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === emp.id ? null : emp.id); }}
          className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all"
        >
          <MoreVertical size={18} />
        </button>

        {menuOpenId === emp.id && (
          <div className="absolute right-0 top-10 w-52 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-2 space-y-1">
              <button 
                onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }} 
                className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-500 hover:bg-gray-50 flex items-center gap-3"
              >
                <ClipboardList size={14}/> View Profile
              </button>

              <div className="h-[1px] bg-gray-50 my-1" />

              <p className="px-3 py-1 text-[9px] font-black text-gray-400 uppercase tracking-widest">Status Governance</p>

              {isLocked && (
                <button 
                  onClick={() => unlockEmployee(emp.id)} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-orange-600 hover:bg-orange-50 flex items-center gap-3"
                >
                  <Unlock size={14}/> Emergency Unlock
                </button>
              )}

              {emp.status !== 'Active' && (
                <button 
                  onClick={() => updateEmployeeStatus(emp.id, 'Active')} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-green-600 hover:bg-green-50 flex items-center gap-3"
                >
                  <UserCheck size={14}/> Activate
                </button>
              )}

              {emp.status !== 'Inactive' && (
                <button 
                  onClick={() => updateEmployeeStatus(emp.id, 'Inactive')} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-600 hover:bg-gray-50 flex items-center gap-3"
                >
                  <UserX size={14}/> Deactivate
                </button>
              )}

              {emp.status !== 'Frozen' && (
                <button 
                  onClick={() => { setEmployeeToFreeze(emp); setIsDeleteConfirmed(false); }} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-blue-600 hover:bg-blue-50 flex items-center gap-3"
                >
                  <Snowflake size={14}/> Freeze Account
                </button>
              )}

              <div className="h-[1px] bg-gray-50 my-1" />

              <button 
                onClick={() => { setEmployeeToDelete(emp); setIsDeleteConfirmed(false); }} 
                className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-red-600 hover:bg-red-50 flex items-center gap-3"
              >
                <Trash2 size={14}/> Delete Permanently
              </button>
            </div>
          </div>
        )}
      </div>
    );
  };

  const renderListView = () => (
    <div key="list" className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden animate-in fade-in zoom-in-95 duration-500">
      <table className="w-full text-left">
        <thead>
          <tr className="bg-gray-50/50 border-b border-gray-100">
            <th className="px-6 py-5 w-10">
              <button onClick={toggleSelectAll} className={`w-5 h-5 rounded flex items-center justify-center transition-all ${selectedIds.length === filteredEmployees.length ? 'bg-blue-900 text-white' : 'bg-white border border-gray-300 text-transparent'}`}>
                {selectedIds.length === filteredEmployees.length ? <CheckSquare size={14} /> : <Square size={14} />}
              </button>
            </th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Employee ID</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Profile</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Department</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Actions</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-50">
          {filteredEmployees.map(emp => {
            const isSelected = selectedIds.includes(emp.id);
            return (
              <tr 
                key={emp.id} 
                onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }} 
                className={`hover:bg-blue-50/30 transition-all cursor-pointer ${isSelected ? 'bg-blue-50/50' : ''}`}
              >
                <td className="px-6 py-4">
                  <button onClick={(e) => toggleSelect(emp.id, e)} className={`w-5 h-5 rounded flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-white border border-gray-200 text-transparent'}`}>
                    {isSelected ? <CheckSquare size={14} /> : <Square size={14} />}
                  </button>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-xs font-bold text-gray-400">{emp.employeeId}</td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center gap-4">
                    <img src={emp.avatar} alt="" className="w-10 h-10 rounded-2xl object-cover" />
                    <div>
                      <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                      <p className="text-[11px] text-gray-400 font-bold uppercase">{emp.role}</p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-[11px] font-bold text-gray-500 uppercase">{emp.department}</td>
                <td className="px-6 py-4 whitespace-nowrap"><StatusBadge emp={emp} /></td>
                <td className="px-6 py-4 text-right"><ActionMenu emp={emp} /></td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );

  const renderGridView = () => (
    <div key="grid" className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 animate-in fade-in zoom-in-95 duration-500">
      {filteredEmployees.map(emp => {
        const isSelected = selectedIds.includes(emp.id);
        return (
          <div 
            key={emp.id} 
            onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }}
            className={`bg-white p-6 rounded-[2.5rem] border transition-all cursor-pointer relative group ${isSelected ? 'border-blue-900 bg-blue-50/20 ring-4 ring-blue-900/5 shadow-md' : 'border-gray-100 shadow-sm hover:border-blue-200 hover:shadow-lg'}`}
          >
            <div className="absolute top-4 left-4 z-10">
              <button 
                onClick={(e) => toggleSelect(emp.id, e)} 
                className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-white/80 border border-gray-200 text-transparent hover:border-blue-400 backdrop-blur-sm opacity-0 group-hover:opacity-100'}`}
              >
                {isSelected ? <CheckSquare size={16} /> : <Square size={16} />}
              </button>
            </div>
            <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
              <ActionMenu emp={emp} />
            </div>
            <div className="flex flex-col items-center text-center">
              <img src={emp.avatar} alt="" className="w-20 h-20 rounded-[2rem] object-cover mb-4 shadow-md border-4 border-white" />
              <h3 className="text-sm font-bold text-blue-900 mb-1">{emp.name}</h3>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">{emp.role}</p>
              <div className="flex flex-col gap-2 w-full">
                <div className="flex items-center justify-between bg-gray-50 p-2 rounded-xl">
                  <span className="text-[9px] font-black text-gray-400 uppercase">Dept</span>
                  <span className="text-[10px] font-bold text-blue-900">{emp.department}</span>
                </div>
                <div className="flex items-center justify-between bg-gray-50 p-2 rounded-xl">
                  <span className="text-[9px] font-black text-gray-400 uppercase">ID</span>
                  <span className="text-[10px] font-bold text-blue-900">{emp.employeeId}</span>
                </div>
              </div>
              <div className="mt-4">
                <StatusBadge emp={emp} />
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );

  const renderCompactView = () => (
    <div key="compact" className="space-y-2 animate-in fade-in zoom-in-95 duration-500">
      {filteredEmployees.map(emp => {
        const isSelected = selectedIds.includes(emp.id);
        return (
          <div 
            key={emp.id} 
            onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }}
            className={`px-6 py-3 rounded-2xl border transition-all cursor-pointer flex items-center justify-between ${isSelected ? 'bg-blue-50 border-blue-900 shadow-sm' : 'bg-white border-gray-100 shadow-sm hover:bg-blue-50/30'}`}
          >
            <div className="flex items-center gap-4 flex-1">
              <button 
                onClick={(e) => toggleSelect(emp.id, e)} 
                className={`w-5 h-5 rounded flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-gray-50 border border-gray-200 text-transparent'}`}
              >
                {isSelected ? <CheckSquare size={14} /> : <Square size={14} />}
              </button>
              <span className="text-[10px] font-black text-gray-300 w-16">{emp.employeeId}</span>
              <div className="flex items-center gap-3">
                <img src={emp.avatar} alt="" className="w-8 h-8 rounded-xl object-cover" />
                <p className="text-xs font-bold text-blue-900">{emp.name}</p>
              </div>
            </div>
            <div className="flex items-center gap-8">
              <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest hidden md:block">{emp.department}</span>
              <StatusBadge emp={emp} />
              <ActionMenu emp={emp} />
            </div>
          </div>
        );
      })}
    </div>
