import React, { useState, useMemo } from 'react';
import { 
  Plane, 
  Calendar, 
  CheckCircle, 
  XCircle, 
  Clock, 
  User, 
  Plus, 
  X, 
  ShieldAlert, 
  FileText, 
  AlertTriangle, 
  Check,
  ChevronRight,
  Info,
  Layers,
  ArrowRight,
  History
} from 'lucide-react';
import { User as UserType, LeaveRequest, Employee, LeaveStatus } from '../types';

interface LeaveManagementProps {
  user: UserType;
  leaveRequests: LeaveRequest[];
  setLeaveRequests: React.Dispatch<React.SetStateAction<LeaveRequest[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
  employees: Employee[];
}

const LeaveManagement: React.FC<LeaveManagementProps> = ({ 
  user, 
  leaveRequests, 
  setLeaveRequests, 
  addNotification, 
  employees 
}) => {
  const isHR = user.role === 'HR';
  const currentEmployee = employees.find(e => e.id === user.id);

  // Mock HOD/Supervisor checks for demo purposes
  const isSupervisor = isHR || user.id === 'emp-alice'; // Senior Dev Alice acts as supervisor for others
  const isOperationsHOD = isHR || user.id === 'emp-bob'; // Bob acts as HOD Operations

  const [isApplying, setIsApplying] = useState(false);
  const [formData, setFormData] = useState({
    type: 'Annual' as LeaveRequest['type'],
    startDate: '',
    endDate: '',
    reason: ''
  });

  const myRequests = useMemo(() => 
    leaveRequests.filter(req => req.employeeId === user.id), 
    [leaveRequests, user.id]
  );

  const pendingApprovals = useMemo(() => {
    return leaveRequests.filter(req => {
      if (req.status === 'Rejected' || req.status === 'Approved' || req.status === 'Policy Violation (HR)') return false;

      // Supervisor sees everything pending their approval
      if (isSupervisor && req.status === 'Pending Supervisor') return true;

      // HOD sees everything pending HOD approval
      if (isOperationsHOD && req.status === 'Pending HOD') return true;

      return false;
    });
  }, [leaveRequests, isSupervisor, isOperationsHOD]);

  const handleApply = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmployee) return;

    const newRequest: LeaveRequest = {
      id: `leave-${Date.now()}`,
      employeeId: user.id,
      employeeName: user.name,
      department: currentEmployee.department,
      type: formData.type,
      startDate: formData.startDate,
      endDate: formData.endDate,
      reason: formData.reason,
      status: 'Pending Supervisor',
      appliedDate: new Date().toISOString().split('T')[0],
      supervisorApproved: false,
      hodApproved: false
    };

    setLeaveRequests(prev => [newRequest, ...prev]);
    setIsApplying(false);
    setFormData({ type: 'Annual', startDate: '', endDate: '', reason: '' });

    // Notify HR team
    employees.filter(e => e.role === 'HR').forEach(hr => {
      addNotification(hr.id, "New Leave Request", `${user.name} has applied for ${formData.type} leave.`);
    });

    // Notify Supervisor (Mock: Alice)
    if (user.id !== 'emp-alice') {
      addNotification('emp-alice', "Approval Required", `${user.name} applied for leave and requires your initial approval.`);
    }
  };

  const handleAction = (requestId: string, action: 'Approve' | 'Reject' | 'Policy Violation') => {
    setLeaveRequests(prev => prev.map(req => {
      if (req.id === requestId) {
        let newStatus = req.status;
        let supervisorApproved = req.supervisorApproved;
        let hodApproved = req.hodApproved;

        if (action === 'Policy Violation') {
          newStatus = 'Policy Violation (HR)';
          addNotification(req.employeeId, "Leave Rejected: Policy Violation", "HR has flagged your leave application as a violation of organizational policy.");
        } else if (action === 'Reject') {
          newStatus = 'Rejected';
          addNotification(req.employeeId, "Leave Application Rejected", "Your leave request has been declined by the approval committee.");
        } else if (action === 'Approve') {
          if (req.status === 'Pending Supervisor' && isSupervisor) {
            newStatus = 'Pending HOD';
            supervisorApproved = true;
            addNotification(req.employeeId, "Supervisor Approval Granted", "Your supervisor has approved your leave. It now awaits HOD Operations finalization.");
            // Notify HOD Operations (Mock: Bob)
            addNotification('emp-bob', "HOD Approval Required", `${req.employeeName}'s leave request has been approved by their supervisor and requires your final sign-off.`);
          } else if (req.status === 'Pending HOD' && isOperationsHOD) {
            newStatus = 'Approved';
            hodApproved = true;
            addNotification(req.employeeId, "Leave Approved", "Your leave application has been finalized and approved by the HOD Operations.");
          }
        }

        return { ...req, status: newStatus, supervisorApproved, hodApproved };
      }
      return req;
    }));
  };

  const getStatusColor = (status: LeaveStatus) => {
    switch (status) {
      case 'Approved': return 'bg-green-50 text-green-700 border-green-100';
      case 'Rejected': return 'bg-red-50 text-red-700 border-red-100';
      case 'Policy Violation (HR)': return 'bg-slate-900 text-white border-slate-800';
      case 'Pending HOD': return 'bg-blue-50 text-blue-700 border-blue-100';
      default: return 'bg-yellow-50 text-yellow-700 border-yellow-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-blue-900 uppercase tracking-tighter">Time Off & Absence</h1>
          <p className="text-gray-500 font-medium">Coordinate your professional availability and leave records.</p>
        </div>
        <button 
          onClick={() => setIsApplying(true)}
          className="flex items-center gap-2 px-6 py-3 bg-blue-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/10 active:scale-95"
        >
          <Plus size={18} /> Apply for Leave
        </button>
      </header>

      {/* Approval Workflow Visualization */}
      <section className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden relative">
        <div className="absolute top-0 right-0 p-8 text-blue-900/5 pointer-events-none">
          <Layers size={140} />
        </div>
        <div className="relative z-10">
          <h2 className="text-xs font-black text-blue-900 uppercase tracking-widest mb-8 flex items-center gap-2">
            <ShieldAlert size={16} className="text-blue-600" /> Multi-Stage Approval Registry
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 relative">
            <div className="hidden md:block absolute top-1/2 left-0 right-0 h-[2px] bg-gray-50 -translate-y-1/2 -z-10"></div>

            <div className="bg-white p-5 rounded-3xl border border-gray-50 shadow-sm flex flex-col items-center text-center">
              <div className="w-10 h-10 bg-blue-50 text-blue-900 rounded-xl flex items-center justify-center mb-3">01</div>
              <p className="text-[10px] font-black uppercase text-blue-900">Direct Supervisor</p>
              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">Initial Validation</p>
            </div>

            <div className="bg-white p-5 rounded-3xl border border-gray-50 shadow-sm flex flex-col items-center text-center">
              <div className="w-10 h-10 bg-blue-50 text-blue-900 rounded-xl flex items-center justify-center mb-3">02</div>
              <p className="text-[10px] font-black uppercase text-blue-900">HOD Operations</p>
              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">Operational Finalization</p>
            </div>

            <div className="bg-white p-5 rounded-3xl border border-gray-50 shadow-sm flex flex-col items-center text-center">
              <div className="w-10 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center mb-3">HR</div>
              <p className="text-[10px] font-black uppercase text-blue-900">Policy Oversight</p>
              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">Veto Authorization</p>
            </div>
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Left Column: Requests List */}
        <div className="xl:col-span-2 space-y-8">
          {(isSupervisor || isOperationsHOD || isHR) && pendingApprovals.length > 0 && (
            <section className="space-y-4">
              <h2 className="text-sm font-black text-blue-900 uppercase tracking-widest px-4 flex items-center gap-2">
                <AlertTriangle size={18} className="text-yellow-600" /> Pending Approval Registry
              </h2>
              <div className="space-y-4">
                {pendingApprovals.map(req => (
                  <div key={req.id} className="bg-white rounded-[2.5rem] p-8 border border-yellow-100 shadow-sm hover:shadow-md transition-all">
                    <div className="flex flex-col md:flex-row justify-between gap-6">
                      <div className="flex items-start gap-4">
                        <div className="w-12 h-12 bg-blue-50 text-blue-900 rounded-[1.5rem] flex items-center justify-center font-black text-lg shadow-inner uppercase">
                          {req.employeeName.charAt(0)}
                        </div>
                        <div>
                          <h3 className="font-black text-blue-900 uppercase tracking-tight">{req.employeeName}</h3>
                          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{req.department} &bull; {req.type} Leave</p>
                          <div className="flex items-center gap-4 mt-3">
                            <div className="flex items-center gap-1.5 text-[10px] font-bold text-gray-500 uppercase">
                              <Calendar size={12} /> {req.startDate} <ArrowRight size={10} /> {req.endDate}
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="flex flex-wrap items-center gap-2">
                        {((req.status === 'Pending Supervisor' && isSupervisor) || 
                          (req.status === 'Pending HOD' && isOperationsHOD)) && (
                          <button 
                            onClick={() => handleAction(req.id, 'Approve')}
                            className="flex items-center gap-2 px-4 py-2.5 bg-green-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-green-600 shadow-lg shadow-green-500/20 active:scale-95"
                          >
                            <Check size={14} /> Approve Request
                          </button>
                        )}
                        <button 
                          onClick={() => handleAction(req.id, 'Reject')}
                          className="flex items-center gap-2 px-4 py-2.5 bg-white border border-red-100 text-red-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-50 transition-all active:scale-95"
                        >
                          <X size={14} /> Decline
                        </button>
                        {isHR && (
                          <button 
                            onClick={() => handleAction(req.id, 'Policy Violation')}
                            className="flex items-center gap-2 px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all active:scale-95"
                          >
                            <ShieldAlert size={14} /> Policy Reject
                          </button>
                        )}
                      </div>
                    </div>
                    <div className="mt-6 p-4 bg-gray-50 rounded-2xl border border-gray-100 italic text-xs text-gray-500">
                      "{req.reason}"
                    </div>
                  </div>
                ))}
              </div>
            </section>
          )}

          <section className="space-y-4">
            <h2 className="text-sm font-black text-blue-900 uppercase tracking-widest px-4 flex items-center gap-2">
              <History size={18} className="text-blue-900/30" /> My Leave History
            </h2>
            {myRequests.length === 0 ? (
              <div className="bg-white rounded-[2.5rem] p-16 text-center border border-dashed border-gray-200">
                <Plane size={48} className="mx-auto text-gray-200 mb-4" />
                <h3 className="text-lg font-bold text-blue-900">No leave records found</h3>
                <p className="text-gray-400 text-xs font-bold uppercase tracking-widest mt-2">Your historical presence registry is currently clear.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-4">
                {myRequests.map(req => (
                  <div key={req.id} className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6 transition-all hover:border-blue-100">
                    <div className="flex items-center gap-5">
                      <div className={`p-4 rounded-2xl ${getStatusColor(req.status)}`}>
                        <Plane size={24} />
                      </div>
                      <div>
                        <h3 className="text-sm font-black text-blue-900 uppercase tracking-widest">{req.type} Leave</h3>
                        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter mt-1">{req.startDate} — {req.endDate}</p>
                        <div className="flex items-center gap-2 mt-3">
                          <span className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase tracking-[0.1em] border ${getStatusColor(req.status)}`}>
                            {req.status}
                          </span>
                        </div>
                      </div>
                    </div>

                    <div className="flex flex-col items-end text-right">
                      <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Applied On</p>
                      <p className="text-xs font-bold text-gray-500 uppercase mt-1">{req.appliedDate}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </section>
        </div>

        {/* Right Column: Policies & Quick Info */}
        <div className="space-y-8">
          <section className="bg-slate-900 text-white rounded-[3rem] p-10 border border-slate-800 shadow-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-10 text-white/5 pointer-events-none group-hover:text-blue-500/10 transition-all duration-700">
              <Info size={160} />
            </div>
            <div className="relative z-10">
              <h2 className="text-sm font-black uppercase tracking-[0.2em] mb-8 flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-lg"><CheckCircle size={16}/></div>
                Leave Policy Guidelines
              </h2>
              <ul className="space-y-6">
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">01</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">Applications must be submitted at least <span className="text-blue-400 font-black">7 days</span> in advance for annual leaves.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">02</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">Medical leave requires a verified <span className="text-blue-400 font-black">Practitioner's Note</span> uploaded to the Registry.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">03</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">HOD Operations approval is <span className="text-blue-400 font-black">mandatory</span> for all cross-departmental travel.</p>
                </li>
              </ul>

              <div className="mt-10 p-6 bg-white/5 rounded-[2rem] border border-white/10">
                <div className="flex items-center gap-3 text-yellow-500 mb-3">
                  <ShieldAlert size={18} />
                  <p className="text-[10px] font-black uppercase tracking-widest">HR Veto Protocol</p>
                </div>
                <p className="text-[10px] text-slate-400 font-bold uppercase leading-relaxed tracking-tight">
                  HR reserves the right to regret any approval in case of policy violations or organizational priority conflict.
                </p>
              </div>
            </div>
          </section>

          <section className="bg-white rounded-[3rem] p-10 border border-gray-100 shadow-sm flex items-center gap-6">
             <div className="w-14 h-14 bg-green-50 text-green-600 rounded-2xl flex items-center justify-center shrink-0">
               <Calendar size={28} />
             </div>
             <div>
               <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Leave Entitlement</p>
               <div className="flex items-baseline gap-2 mt-1">
                 <p className="text-2xl font-black text-blue-900">22</p>
                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Days Remaining</p>
               </div>
             </div>
          </section>
        </div>
      </div>

      {/* Leave Application Modal */}
      {isApplying && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#1e3a8a]/40 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsApplying(false)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-w-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-blue-900 text-white rounded-2xl"><Plus size={20}/></div>
                <h2 className="text-xl font-black text-blue-900 uppercase tracking-tighter">Apply for Leave</h2>
              </div>
              <button onClick={() => setIsApplying(false)} className="p-2 hover:bg-gray-100 rounded-xl transition-all"><X size={20}/></button>
            </div>

            <form onSubmit={handleApply} className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Leave Classification</label>
                <select 
                  required
                  value={formData.type}
                  onChange={e => setFormData({...formData, type: e.target.value as any})}
                  className="w-full px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900"
                >
                  <option value="Annual">Annual Leave</option>
                  <option value="Sick">Sick Leave</option>
                  <option value="Personal">Personal Leave</option>
                  <option value="Maternity/Paternity">Maternity/Paternity</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">From Date</label>
                  <input 
                    type="date" 
                    required
                    value={formData.startDate}
                    onChange={e => setFormData({...formData, startDate: e.target.value})}
                    className="w-full px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white transition-all font-bold text-xs text-blue-900"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">To Date</label>
                  <input 
                    type="date" 
                    required
                    value={formData.endDate}
                    onChange={e => setFormData({...formData, endDate: e.target.value})}
                    className="w-full px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white transition-all font-bold text-xs text-blue-900"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Operational Justification</label>
                <textarea 
                  required
                  placeholder="Provide brief context for leave request..."
                  value={formData.reason}
                  onChange={e => setFormData({...formData, reason: e.target.value})}
                  className="w-full h-24 px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white focus:border-blue-900/20 transition-all font-bold text-sm text-blue-900 resize-none"
                />
              </div>

              <button 
                type="submit"
                className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 active:scale-95 flex items-center justify-center gap-3"
              >
                Submit for Validation <ArrowRight size={18} />
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default LeaveManagement;

export type UserRole = 'HR' | 'Employee';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  email: string;
  avatar: string;
}

export interface Task {
  id: string;
  title: string;
  dueDate: string;
  status: 'Pending' | 'In Progress' | 'Completed';
  priority: 'Low' | 'Medium' | 'High';
}

export interface Notification {
  id: string;
  userId: string;
  title: string;
  message: string;
  timestamp: string;
  isRead: boolean;
}

export type LeaveStatus = 'Pending Supervisor' | 'Pending HOD' | 'Approved' | 'Rejected' | 'Policy Violation (HR)';

export interface LeaveRequest {
  id: string;
  employeeId: string;
  employeeName: string;
  department: string;
  startDate: string;
  endDate: string;
  reason: string;
  type: 'Annual' | 'Sick' | 'Personal' | 'Maternity/Paternity';
  status: LeaveStatus;
  appliedDate: string;
  supervisorApproved?: boolean;
  hodApproved?: boolean;
}

export type ResignationStatus = 'Pending' | 'Accepted' | 'Rejected' | 'Withdrawn';

export interface ResignationRequest {
  id: string;
  employeeId: string;
  employeeName: string;
  reason: string;
  appliedDate: string;
  lastWorkingDate: string;
  status: ResignationStatus;
  feedback?: string;
}

export interface Employee {
  id: string;
  employeeId: string;
  name: string;
  role: string;
  department: string;
  email: string;
  password?: string;
  mustChangePassword?: boolean;
  failedLoginAttempts?: number;
  lockoutUntil?: string | null;
  hasLoggedInBefore?: boolean;
  status: 'Active' | 'On Leave' | 'Inactive' | 'Frozen';
  avatar: string;
  joinDate: string;
  tasks?: Task[];
  documents?: Document[];
  leaveRequests?: LeaveRequest[];
  resignation?: ResignationRequest;
}

export interface DocumentHistoryEntry {
  status: 'Verified' | 'Pending';
  timestamp: string;
  verifiedBy?: string;
}

export interface Document {
  id: string;
  name: string;
  type: string;
  uploadDate: string;
  status: 'Verified' | 'Pending';
  statusHistory?: DocumentHistoryEntry[];
  verifiedBy?: string;
}

export interface JobPosting {
  id: string;
  title: string;
  department: string;
  location: string;
  type: string;
  description: string;
  status: 'Open' | 'Closed' | 'Draft';
}

export interface PerformanceReview {
  id: string;
  employeeId: string;
  reviewer: string;
  date: string;
  rating: number;
  comments: string;
  summary?: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Employees from './pages/Employees';
import Recruitment from './pages/Recruitment';
import Performance from './pages/Performance';
import Documents from './pages/Documents';
import Attendance from './pages/Attendance';
import Security from './pages/Security';
import LeaveManagement from './pages/LeaveManagement';
import ExitManagement from './pages/ExitManagement';
import Login from './pages/Login';
import MyTasks from './pages/MyTasks';
import { Bell, Search, LogOut, X, Clock, ShieldAlert, Sparkles, PartyPopper, CheckCircle2 } from 'lucide-react';
import Logo from './components/Logo';
import { User, Employee, Notification, Task, LeaveRequest, ResignationRequest } from './types';
import { MOCK_EMPLOYEES } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [leaveRequests, setLeaveRequests] = useState<LeaveRequest[]>([]);
  const [resignationRequests, setResignationRequests] = useState<ResignationRequest[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showWelcome, setShowWelcome] = useState(false);

  const currentEmployee = employees.find(e => e.id === user?.id);

  // Enforcement logic: If password change is required, lock the user to the security tab
  useEffect(() => {
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      setActiveTab('security');
    }
  }, [currentEmployee?.mustChangePassword, activeTab]);

  // Handle welcome screen visibility
  useEffect(() => {
    if (user && currentEmployee && !currentEmployee.hasLoggedInBefore) {
      setShowWelcome(true);
    }
  }, [user, currentEmployee]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setShowNotifications(false);
    setShowWelcome(false);
  };

  const handleFinishWelcome = () => {
    if (user) {
      setEmployees(prev => prev.map(emp => 
        emp.id === user.id ? { ...emp, hasLoggedInBefore: true } : emp
      ));
    }
    setShowWelcome(false);
  };

  const addNotification = (userId: string, title: string, message: string) => {
    const newNotif: Notification = {
      id: `notif-${Date.now()}`,
      userId,
      title,
      message,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };
    setNotifications(prev => [newNotif, ...prev]);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const userNotifications = notifications.filter(n => n.userId === user?.id || (user?.role === 'HR'));
  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleUpdateTaskStatus = (taskId: string, status: Task['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === user?.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status } : t)
        };
      }
      return emp;
    }));
  };

  const renderContent = () => {
    if (!user) return null;

    // If user must change password, restrict access to other pages
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'tasks': return currentEmployee ? <MyTasks employee={currentEmployee} onUpdateTask={handleUpdateTaskStatus} /> : <Dashboard />;
      case 'profiles': return user.role === 'HR' ? <Employees employees={employees} setEmployees={setEmployees} addNotification={addNotification} /> : <Dashboard />;
      case 'recruitment': return user.role === 'HR' ? <Recruitment /> : <Dashboard />;
      case 'performance': return <Performance />;
      case 'attendance': return <Attendance user={user} />;
      case 'leave': return (
        <LeaveManagement 
          user={user} 
          leaveRequests={leaveRequests} 
          setLeaveRequests={setLeaveRequests}
          addNotification={addNotification}
          employees={employees}
        />
      );
      case 'exit': return (
        <ExitManagement
          user={user}
          resignationRequests={resignationRequests}
          setResignationRequests={setResignationRequests}
          addNotification={addNotification}
          employees={employees}
        />
      );
      case 'documents': return (
        <Documents 
          user={user} 
          allEmployees={employees} 
          setEmployees={setEmployees} 
          addNotification={addNotification}
        />
      );
      case 'security': return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
      default: return <Dashboard />;
    }
  };

  // If user is not logged in, show the Login page
  if (!user) {
    return <Login onLogin={handleLogin} employees={employees} setEmployees={setEmployees} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Welcome Screen Modal */}
      {showWelcome && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-[#1e3a8a]/95 backdrop-blur-xl animate-in fade-in duration-700">
          <div className="max-w-2xl w-full bg-white rounded-[3rem] p-12 text-center relative overflow-hidden shadow-2xl animate-in zoom-in-95 duration-500">
            {/* Decorative background shapes */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-blue-50 rounded-full -mr-32 -mt-32 opacity-50 blur-3xl"></div>
            <div className="absolute bottom-0 left-0 w-64 h-64 bg-purple-50 rounded-full -ml-32 -mb-32 opacity-50 blur-3xl"></div>

            <div className="relative z-10 flex flex-col items-center">
              <div className="w-24 h-24 bg-blue-900 rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl shadow-blue-900/20 rotate-3 transition-transform hover:rotate-0">
                <Logo className="w-16 h-16" />
              </div>

              <div className="space-y-4 mb-10">
                <div className="flex items-center justify-center gap-3 text-blue-600">
                  <Sparkles size={20} />
                  <span className="text-[10px] font-black uppercase tracking-[0.3em]">Official Onboarding</span>
                  <Sparkles size={20} />
                </div>
                <h1 className="text-4xl font-black text-blue-900 uppercase tracking-tighter serif leading-tight">
                  Welcome to the <br/> Srinidhi Family
                </h1>
                <p className="text-gray-500 font-medium text-lg max-w-md mx-auto">
                  Hello, <span className="text-blue-900 font-bold">{user.name}</span>. We're thrilled to have you join our world-class team of professionals.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full mb-10">
                <div className="p-6 bg-gray-50 rounded-3xl border border-gray-100 flex flex-col items-center text-center">
                  <div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-blue-900 mb-3">
                    <CheckCircle2 size={20} />
                  </div>
                  <h3 className="text-xs font-black text-blue-900 uppercase tracking-widest mb-1">Onboarding Active</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">Email dispatched to HR Desk</p>
                </div>
                <div className="p-6 bg-gray-50 rounded-3xl border border-gray-100 flex flex-col items-center text-center">
                  <div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-purple-600 mb-3">
                    <PartyPopper size={20} />
                  </div>
                  <h3 className="text-xs font-black text-blue-900 uppercase tracking-widest mb-1">Growth Ready</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight">Your digital workspace is primed</p>
                </div>
              </div>

              <button 
                onClick={handleFinishWelcome}
                className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 active:scale-95 group flex items-center justify-center gap-3"
              >
                Initialize Workspace
                <Sparkles size={18} className="group-hover:rotate-12 transition-transform" />
              </button>

              <p className="mt-6 text-[9px] text-gray-400 font-bold uppercase tracking-[0.2em]">
                Securely synchronized with saisurendra@srinidhiassociates.co.in
              </p>
            </div>
          </div>
        </div>
      )}

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        user={user} 
        disabled={!!currentEmployee?.mustChangePassword}
      />

      <main className="flex-1 md:ml-64 p-4 md:p-8">
        {currentEmployee?.mustChangePassword && (
          <div className="mb-6 p-4 bg-orange-50 border border-orange-200 rounded-2xl flex items-center justify-between animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-4 text-orange-800">
              <ShieldAlert size={20} className="shrink-0" />
              <p className="text-sm font-bold uppercase tracking-tight">Security Action Required: Mandatory access token update mandated by HR administration.</p>
            </div>
            <div className="px-3 py-1 bg-orange-100 text-orange-900 text-[10px] font-black rounded-lg uppercase">Restricted Mode</div>
          </div>
        )}

        <nav className="flex items-center justify-between mb-8 sticky top-0 bg-gray-50/80 backdrop-blur-md z-10 py-4">
          <div className="md:hidden flex items-center gap-2">
             <Logo className="w-8 h-8" />
             <span className="font-bold text-sm tracking-tight text-[#1e3a8a] uppercase">Srinidhi</span>
          </div>

          <div className="hidden md:flex items-center bg-white rounded-xl border border-gray-200 px-4 py-2 w-96 shadow-sm focus-within:ring-2 focus-within:ring-blue-500/20 transition-all">
            <Search className="text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Quick search records..." 
              className="bg-transparent border-none outline-none text-sm ml-2 w-full font-medium"
              disabled={!!currentEmployee?.mustChangePassword}
            />
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <button 
                onClick={() => {
                  setShowNotifications(!showNotifications);
                  if (!showNotifications) markAllAsRead();
                }}
                disabled={!!currentEmployee?.mustChangePassword}
                className="p-2 text-gray-400 hover:bg-white hover:text-blue-900 rounded-xl transition-all relative disabled:opacity-30"
              >
                <Bell size={20} />
                {unreadCount > 0 && (
                  <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-gray-50"></span>
                )}
              </button>

              {showNotifications && (
                <div className="absolute right-0 mt-4 w-80 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
                    <h3 className="font-bold text-sm">Notifications</h3>
                    <button onClick={() => setShowNotifications(false)}><X size={16} /></button>
                  </div>
                  <div className="max-h-96 overflow-y-auto no-scrollbar">
                    {userNotifications.length === 0 ? (
                      <div className="p-8 text-center text-gray-400 text-sm italic">No recent notifications.</div>
                    ) : (
                      userNotifications.map(notif => (
                        <div key={notif.id} className="p-4 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                          <p className="text-sm font-bold text-blue-900">{notif.title}</p>
                          <p className="text-xs text-gray-600 mt-1">{notif.message}</p>
                          <div className="flex items-center gap-1 text-[10px] text-gray-400 mt-2 uppercase font-bold">
                            <Clock size={10} /> {notif.timestamp}
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  <div className="p-3 text-center bg-gray-50">
                    <button className="text-[10px] font-bold uppercase tracking-widest text-blue-900 hover:underline">View All Notifications</button>
                  </div>
                </div>
              )}
            </div>

            <button onClick={handleLogout} className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-xl transition-all"><LogOut size={20} /></button>
            <div className="h-8 w-[1px] bg-gray-200 mx-1"></div>
            <div className="flex items-center gap-3 group cursor-pointer">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold group-hover:text-blue-900 transition-colors uppercase tracking-tight">{user.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{user.role}</p>
              </div>
              <div className="w-10 h-10 rounded-xl bg-blue-900 flex items-center justify-center text-white border-2 border-white shadow-md overflow-hidden">
                <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
              </div>
            </div>
          </div>
        </nav>

        <div className="max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  LogOut, 
  FileText, 
  Calendar, 
  Send, 
  CheckCircle, 
  XCircle, 
  AlertTriangle, 
  User as UserIcon, 
  Clock, 
  ShieldAlert, 
  ArrowRight, 
  Plus, 
  X,
  UserCheck,
  History,
  MessageSquare
} from 'lucide-react';
import { User, ResignationRequest, Employee, ResignationStatus } from '../types';

interface ExitManagementProps {
  user: User;
  resignationRequests: ResignationRequest[];
  setResignationRequests: React.Dispatch<React.SetStateAction<ResignationRequest[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
  employees: Employee[];
}

const ExitManagement: React.FC<ExitManagementProps> = ({ 
  user, 
  resignationRequests, 
  setResignationRequests, 
  addNotification, 
  employees 
}) => {
  const isHR = user.role === 'HR';
  const [isApplying, setIsApplying] = useState(false);
  const [formData, setFormData] = useState({
    reason: '',
    lastWorkingDate: ''
  });

  const myResignation = useMemo(() => 
    resignationRequests.find(req => req.employeeId === user.id), 
    [resignationRequests, user.id]
  );

  // For HR or Supervisors to see all relevant requests
  const allRequests = useMemo(() => resignationRequests, [resignationRequests]);

  const handleResign = (e: React.FormEvent) => {
    e.preventDefault();

    const newRequest: ResignationRequest = {
      id: `res-${Date.now()}`,
      employeeId: user.id,
      employeeName: user.name,
      reason: formData.reason,
      appliedDate: new Date().toISOString().split('T')[0],
      lastWorkingDate: formData.lastWorkingDate,
      status: 'Pending'
    };

    setResignationRequests(prev => [...prev, newRequest]);
    setIsApplying(false);
    setFormData({ reason: '', lastWorkingDate: '' });

    // Notify HR team
    employees.filter(e => e.role === 'HR').forEach(hr => {
      addNotification(hr.id, "Resignation Alert", `${user.name} has submitted a resignation request.`);
    });

    // Notify Supervisor (Alice acts as supervisor in this mock)
    if (user.id !== 'emp-alice') {
      addNotification('emp-alice', "Direct Report Resignation", `${user.name} has applied for resignation.`);
    }
  };

  const handleAction = (requestId: string, action: ResignationStatus) => {
    setResignationRequests(prev => prev.map(req => {
      if (req.id === requestId) {
        const updatedReq = { ...req, status: action };
        addNotification(req.employeeId, `Resignation ${action}`, `Your resignation request has been ${action.toLowerCase()} by HR.`);
        return updatedReq;
      }
      return req;
    }));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-blue-900 uppercase tracking-tighter">Exit Management</h1>
          <p className="text-gray-500 font-medium">Handle personnel separation and resignation protocols.</p>
        </div>
        {!isHR && !myResignation && (
          <button 
            onClick={() => setIsApplying(true)}
            className="flex items-center gap-2 px-6 py-3 bg-red-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-xl shadow-red-900/10 active:scale-95"
          >
            <Plus size={18} /> Apply for Resignation
          </button>
        )}
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Main Workspace */}
        <div className="xl:col-span-2 space-y-8">
          {/* Employee's Own Resignation Status */}
          {!isHR && myResignation && (
            <section className="bg-white p-8 rounded-[3rem] border border-red-100 shadow-sm relative overflow-hidden">
              <div className="absolute top-0 right-0 p-8 text-red-500/5 pointer-events-none">
                <LogOut size={160} />
              </div>
              <div className="relative z-10">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-xs font-black text-red-600 uppercase tracking-widest flex items-center gap-2">
                    <ShieldAlert size={16} /> Resignation Protocol Active
                  </h2>
                  <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase border ${
                    myResignation.status === 'Pending' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
                    myResignation.status === 'Accepted' ? 'bg-green-50 text-green-700 border-green-100' :
                    'bg-red-50 text-red-700 border-red-100'
                  }`}>
                    {myResignation.status}
                  </span>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Employee Name</p>
                      <p className="text-lg font-bold text-blue-900">{myResignation.employeeName}</p>
                    </div>
                    <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Last Working Date</p>
                      <p className="text-lg font-bold text-red-600 uppercase">{myResignation.lastWorkingDate}</p>
                    </div>
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Reason for Separation</p>
                    <div className="mt-2 p-4 bg-gray-50 rounded-2xl border border-gray-100 italic text-xs text-gray-500">
                      "{myResignation.reason}"
                    </div>
                  </div>
                </div>
              </div>
            </section>
          )}

          {/* Admin List of Resignations */}
          {isHR && (
            <section className="space-y-4">
              <h2 className="text-sm font-black text-blue-900 uppercase tracking-widest px-4 flex items-center gap-2">
                <History size={18} className="text-blue-900/30" /> Resignation Pipeline
              </h2>
              {allRequests.length === 0 ? (
                <div className="bg-white rounded-[2.5rem] p-16 text-center border border-dashed border-gray-200">
                  <FileText size={48} className="mx-auto text-gray-200 mb-4" />
                  <h3 className="text-lg font-bold text-blue-900">No resignation requests found</h3>
                  <p className="text-gray-400 text-xs font-bold uppercase tracking-widest mt-2">The separation registry is currently vacant.</p>
                </div>
              ) : (
                <div className="space-y-4">
                  {allRequests.map(req => (
                    <div key={req.id} className="bg-white rounded-[2.5rem] p-8 border border-gray-100 shadow-sm hover:shadow-md transition-all">
                      <div className="flex flex-col md:flex-row justify-between gap-6">
                        <div className="flex items-start gap-4">
                          <div className="w-12 h-12 bg-red-50 text-red-600 rounded-[1.5rem] flex items-center justify-center font-black text-lg shadow-inner">
                            {req.employeeName.charAt(0)}
                          </div>
                          <div>
                            <h3 className="font-black text-blue-900 uppercase tracking-tight">{req.employeeName}</h3>
                            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Separation Request &bull; Applied {req.appliedDate}</p>
                            <div className="flex items-center gap-4 mt-3">
                              <div className="flex items-center gap-1.5 text-[10px] font-bold text-red-500 uppercase">
                                <Calendar size={12} /> Expected Last Day: {req.lastWorkingDate}
                              </div>
                            </div>
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                          {req.status === 'Pending' && (
                            <>
                              <button 
                                onClick={() => handleAction(req.id, 'Accepted')}
                                className="flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-green-600 transition-all shadow-lg shadow-green-500/10 active:scale-95"
                              >
                                <CheckCircle size={14} /> Accept
                              </button>
                              <button 
                                onClick={() => handleAction(req.id, 'Rejected')}
                                className="flex items-center gap-2 px-4 py-2 bg-white border border-red-100 text-red-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-50 transition-all active:scale-95"
                              >
                                <XCircle size={14} /> Reject
                              </button>
                            </>
                          )}
                          {req.status !== 'Pending' && (
                            <span className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase border ${
                              req.status === 'Accepted' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-red-50 text-red-700 border-red-100'
                            }`}>
                              {req.status}
                            </span>
                          )}
                        </div>
                      </div>
                      <div className="mt-6 p-4 bg-gray-50 rounded-2xl border border-gray-100 italic text-xs text-gray-500">
                        "{req.reason}"
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}

          {!isHR && !myResignation && (
            <div className="bg-white rounded-[2.5rem] p-16 text-center border border-dashed border-gray-200">
              <LogOut size={48} className="mx-auto text-gray-200 mb-4" />
              <h3 className="text-lg font-bold text-blue-900">Career Continuum</h3>
              <p className="text-gray-400 text-xs font-bold uppercase tracking-widest mt-2 max-w-xs mx-auto">
                No active separation requests. Your professional status with Srinidhi Associates remains Active.
              </p>
            </div>
          )}
        </div>

        {/* Policies Section */}
        <div className="space-y-8">
          <section className="bg-slate-900 text-white rounded-[3rem] p-10 border border-slate-800 shadow-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-10 text-white/5 pointer-events-none group-hover:text-red-500/10 transition-all duration-700">
              <ShieldAlert size={160} />
            </div>
            <div className="relative z-10">
              <h2 className="text-sm font-black uppercase tracking-[0.2em] mb-8 flex items-center gap-3">
                <div className="p-2 bg-red-600 rounded-lg"><LogOut size={16}/></div>
                Exit Protocols
              </h2>
              <ul className="space-y-6">
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">01</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">A mandatory notice period of <span className="text-red-400 font-black">30 days</span> is required for all associates.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">02</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">Asset clearance and digital access revocation occurs on the <span className="text-red-400 font-black">final day</span>.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">03</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">Full & Final settlement is processed within <span className="text-red-400 font-black">45 days</span> of exit.</p>
                </li>
              </ul>

              <div className="mt-10 p-6 bg-white/5 rounded-[2rem] border border-white/10">
                <div className="flex items-center gap-3 text-red-500 mb-3">
                  <MessageSquare size={18} />
                  <p className="text-[10px] font-black uppercase tracking-widest">Exit Interview</p>
                </div>
                <p className="text-[10px] text-slate-400 font-bold uppercase leading-relaxed tracking-tight">
                  Upon acceptance, HR will schedule a formal exit interview to understand your experience.
                </p>
              </div>
            </div>
          </section>

          <section className="bg-white rounded-[3rem] p-10 border border-gray-100 shadow-sm flex items-center gap-6">
             <div className="w-14 h-14 bg-red-50 text-red-600 rounded-2xl flex items-center justify-center shrink-0">
               <ShieldAlert size={28} />
             </div>
             <div>
               <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Registry Status</p>
               <div className="flex items-baseline gap-2 mt-1">
                 <p className="text-xl font-black text-blue-900 uppercase">{user.role === 'HR' ? 'Admin Controller' : 'Permanent Associate'}</p>
               </div>
             </div>
          </section>
        </div>
      </div>

      {/* Resignation Application Modal */}
      {isApplying && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300" onClick={() => setIsApplying(false)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-w-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-red-600 text-white rounded-2xl shadow-lg shadow-red-900/20"><LogOut size={20}/></div>
                <h2 className="text-xl font-black text-blue-900 uppercase tracking-tighter">Submit Resignation</h2>
              </div>
              <button onClick={() => setIsApplying(false)} className="p-2 hover:bg-gray-100 rounded-xl transition-all"><X size={20}/></button>
            </div>

            <form onSubmit={handleResign} className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Proposed Last Working Date</label>
                <div className="relative group">
                  <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors" size={18} />
                  <input 
                    type="date" 
                    required
                    value={formData.lastWorkingDate}
                    onChange={e => setFormData({...formData, lastWorkingDate: e.target.value})}
                    className="w-full pl-12 pr-6 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-red-900/5 focus:bg-white transition-all font-bold text-sm text-blue-900"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Official Statement / Reason</label>
                <textarea 
                  required
                  placeholder="State the primary reason for your departure..."
                  value={formData.reason}
                  onChange={e => setFormData({...formData, reason: e.target.value})}
                  className="w-full h-32 px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-red-900/5 focus:bg-white transition-all font-bold text-sm text-blue-900 resize-none"
                />
              </div>

              <div className="p-4 bg-red-50 rounded-2xl border border-red-100 flex items-start gap-3">
                <ShieldAlert size={18} className="text-red-600 shrink-0 mt-0.5" />
                <p className="text-[10px] text-red-900 font-bold uppercase leading-relaxed">
                  Your supervisor and the HR team will be notified immediately upon submission.
                </p>
              </div>

              <button 
                type="submit"
                className="w-full py-5 bg-red-600 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-red-700 transition-all shadow-xl shadow-red-900/20 active:scale-95 flex items-center justify-center gap-3"
              >
                Apply for Resignation <ArrowRight size={18} />
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExitManagement;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Search, MoreVertical, Plus, Trash2, X, ClipboardList, CheckCircle, 
  UserPlus, Snowflake, Power, UserCheck,
  LayoutList, LayoutGrid, Rows3, ChevronDown, Fingerprint, Hash, UserCircle,
  Lock, ShieldAlert, AlertTriangle, 
  User as UserIcon, FileDown, Square, CheckSquare, 
  UserMinus, UserX,
  TriangleAlert,
  Activity,
  Clock,
  Eye,
  EyeOff,
  Unlock,
  MailCheck
} from 'lucide-react';
import { DEPARTMENTS } from '../constants';
import { Employee, Task } from '../types';

interface EmployeesProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

type ViewMode = 'list' | 'grid' | 'compact';
type TaskFilterType = 'All' | 'No Tasks' | 'Has Tasks';

const Employees: React.FC<EmployeesProps> = ({ employees, setEmployees, addNotification }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [idFilter, setIdFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [taskFilter, setTaskFilter] = useState<TaskFilterType>('All');
  const [viewingEmployee, setViewingEmployee] = useState<Employee | null>(null);
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [menuOpenId, setMenuOpenId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [showNewEmpPassword, setShowNewEmpPassword] = useState(false);

  // Deletion/Freeze States
  const [employeeToDelete, setEmployeeToDelete] = useState<Employee | null>(null);
  const [employeeToFreeze, setEmployeeToFreeze] = useState<Employee | null>(null);
  const [isDeleteConfirmed, setIsDeleteConfirmed] = useState(false);
  const [showBulkDeleteConfirm, setShowBulkDeleteConfirm] = useState(false);

  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskPriority, setNewTaskPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [newTaskDueDate, setNewTaskDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);
  const [newTaskStatus, setNewTaskStatus] = useState<Task['status']>('Pending');

  const [formError, setFormError] = useState<string | null>(null);
  const [adminResetPass, setAdminResetPass] = useState('');
  const [resetSuccess, setResetSuccess] = useState(false);

  // Task search state for the slide-over
  const [taskSearchTerm, setTaskSearchTerm] = useState('');

  const [newEmp, setNewEmp] = useState({
    employeeId: '',
    name: '',
    role: '',
    department: DEPARTMENTS[0],
    email: '',
    password: 'Password123!',
    status: 'Active' as const
  });

  // Real-time validation states
  // Relaxed regex to allow SA- followed by one or more digits
  const idRegex = /^SA-\d+$/;
  const isIdFormatValid = idRegex.test(newEmp.employeeId);
  const isIdUnique = !employees.some(emp => emp.employeeId.toUpperCase() === newEmp.employeeId.toUpperCase());
  const canSubmit = isIdFormatValid && isIdUnique && newEmp.name && newEmp.email && newEmp.role && newEmp.password;

  useEffect(() => {
    const handleClickOutside = () => setMenuOpenId(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const idTerm = idFilter.toLowerCase();

    const matchesSearch = 
      emp.name.toLowerCase().includes(term) ||
      emp.role.toLowerCase().includes(term) ||
      emp.department.toLowerCase().includes(term) ||
      emp.email.toLowerCase().includes(term) ||
      emp.employeeId.toLowerCase().includes(term);

    const matchesId = !idFilter || emp.employeeId.toLowerCase().includes(idTerm);
    const matchesStatus = statusFilter === 'All' || emp.status === statusFilter;
    const matchesDept = deptFilter === 'All' || emp.department === deptFilter;

    const hasTasks = emp.tasks && emp.tasks.length > 0;
    const matchesTasks = 
      taskFilter === 'All' ? true :
      taskFilter === 'No Tasks' ? !hasTasks :
      taskFilter === 'Has Tasks' ? hasTasks : true;

    return matchesSearch && matchesId && matchesStatus && matchesDept && matchesTasks;
  });

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredEmployees.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(filteredEmployees.map(e => e.id));
    }
  };

  const toggleSelect = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const updateEmployeeStatus = (id: string, newStatus: Employee['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === id) {
        const statusMap = {
          'Active': { title: 'Account Activated', msg: 'Your professional access has been restored by HR.' },
          'Inactive': { title: 'Account Deactivated', msg: 'Your account has been moved to inactive status.' },
          'Frozen': { title: 'Account Frozen', msg: 'Your account has been temporarily frozen for security purposes.' },
          'On Leave': { title: 'Leave Approved', msg: 'Your status has been updated to On Leave.' }
        };
        const notify = statusMap[newStatus];
        addNotification(id, notify.title, notify.msg);
        return { ...emp, status: newStatus };
      }
      return emp;
    }));
    setMenuOpenId(null);
  };

  const unlockEmployee = (id: string) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === id) {
        addNotification(id, "Security: Account Unlocked", "An HR Administrator has reset your failed login attempts and restored access.");
        return { ...emp, failedLoginAttempts: 0, lockoutUntil: null };
      }
      return emp;
    }));
    if (viewingEmployee?.id === id) {
      setViewingEmployee(prev => prev ? { ...prev, failedLoginAttempts: 0, lockoutUntil: null } : null);
    }
    setMenuOpenId(null);
  };

  const handleBulkDelete = () => {
    if (!isDeleteConfirmed) return;
    setEmployees(prev => prev.filter(emp => !selectedIds.includes(emp.id)));
    setSelectedIds([]);
    setShowBulkDeleteConfirm(false);
    setIsDeleteConfirmed(false);
  };

  const handleDeleteEmployee = () => {
    if (!employeeToDelete || !isDeleteConfirmed) return;
    setEmployees(prev => prev.filter(emp => emp.id !== employeeToDelete.id));
    setEmployeeToDelete(null);
    setIsDeleteConfirmed(false);
    setMenuOpenId(null);
  };

  const handleFreezeEmployee = () => {
    if (!employeeToFreeze || !isDeleteConfirmed) return;
    updateEmployeeStatus(employeeToFreeze.id, 'Frozen');
    setEmployeeToFreeze(null);
    setIsDeleteConfirmed(false);
  };

  const handleExportCSV = () => {
    const headers = ['Employee ID', 'Name', 'Role', 'Department', 'Status'];
    const rows = filteredEmployees.map(emp => [
      emp.employeeId,
      emp.name,
      emp.role,
      emp.department,
      emp.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `srinidhi_personnel_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleAddEmployee = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    if (!isIdFormatValid) {
      setFormError("Format Mismatch: Employee ID must follow the 'SA-XXXX' pattern.");
      return;
    }

    if (!isIdUnique) {
      setFormError(`Registry Conflict: The identifier '${newEmp.employeeId}' is already assigned.`);
      return;
    }

    const employee: Employee = {
      id: `emp-${Date.now()}`,
      ...newEmp,
      avatar: `https://picsum.photos/seed/${newEmp.name.replace(/\s+/g, '')}/100/100`,
      joinDate: new Date().toISOString().split('T')[0],
      tasks: [],
      documents: [],
      failedLoginAttempts: 0,
      lockoutUntil: null,
      hasLoggedInBefore: false
    };

    // Using functional state update to ensure we have the latest list
    setEmployees(prev => [employee, ...prev]);
    setIsAddingEmployee(false);

    setNewEmp({ employeeId: '', name: '', role: '', department: DEPARTMENTS[0], email: '', password: 'Password123!', status: 'Active' });
    setShowNewEmpPassword(false);

    alert(`Onboarding Initiated:\nPersonnel profile for ${employee.name} created successfully.`);
  };

  const handleAdminResetPassword = () => {
    if (!viewingEmployee || !adminResetPass.trim()) return;
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, password: adminResetPass, failedLoginAttempts: 0, lockoutUntil: null } : emp
    ));
    addNotification(viewingEmployee.id, "Security: Credentials Reset", "An HR Administrator has updated your organizational access token.");
    setResetSuccess(true);
    setTimeout(() => setResetSuccess(false), 3000);
    setAdminResetPass('');
  };

  const addTask = () => {
    if (!viewingEmployee || !newTaskTitle.trim()) return;
    const newTask: Task = {
      id: `t-${Date.now()}`,
      title: newTaskTitle,
      dueDate: newTaskDueDate,
      status: newTaskStatus,
      priority: newTaskPriority
    };
    setEmployees(prev => prev.map(emp => 
      emp.id === viewingEmployee.id ? { ...emp, tasks: [...(emp.tasks || []), newTask] } : emp
    ));
    setViewingEmployee(prev => prev ? { ...prev, tasks: [...(prev.tasks || []), newTask] } : null);
    addNotification(viewingEmployee.id, "New Assignment", `HR has assigned you a new task: ${newTaskTitle}`);
    setNewTaskTitle('');
  };

  const filteredMemberTasks = useMemo(() => {
    if (!viewingEmployee) return [];
    const tasks = viewingEmployee.tasks || [];
    if (!taskSearchTerm.trim()) return tasks;
    return tasks.filter(t => 
      t.title.toLowerCase().includes(taskSearchTerm.toLowerCase())
    );
  }, [viewingEmployee, taskSearchTerm]);

  const StatusBadge = ({ emp }: { emp: Employee }) => {
    const isLocked = emp.lockoutUntil && new Date(emp.lockoutUntil).getTime() > Date.now();
    return (
      <div className="flex flex-col gap-1 items-start">
        <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${
          emp.status === 'Active' ? 'bg-green-50 text-green-700 border-green-100' :
          emp.status === 'On Leave' ? 'bg-yellow-50 text-yellow-700 border-yellow-100' :
          emp.status === 'Frozen' ? 'bg-blue-50 text-blue-700 border-blue-100' :
          'bg-gray-100 text-gray-500 border-gray-200'
        }`}>
          {emp.status}
        </span>
        {isLocked && (
          <span className="bg-red-50 text-red-600 border border-red-100 px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest flex items-center gap-1">
            <Lock size={8} /> Locked Out
          </span>
        )}
      </div>
    );
  };

  const ActionMenu = ({ emp }: { emp: Employee }) => {
    const isLocked = emp.lockoutUntil && new Date(emp.lockoutUntil).getTime() > Date.now();
    return (
      <div className="relative inline-block text-left" onClick={(e) => e.stopPropagation()}>
        <button 
          onClick={(e) => { e.stopPropagation(); setMenuOpenId(menuOpenId === emp.id ? null : emp.id); }}
          className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 hover:text-blue-900 transition-all"
        >
          <MoreVertical size={18} />
        </button>

        {menuOpenId === emp.id && (
          <div className="absolute right-0 top-10 w-52 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-2 space-y-1">
              <button 
                onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }} 
                className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-500 hover:bg-gray-50 flex items-center gap-3"
              >
                <ClipboardList size={14}/> View Profile
              </button>

              <div className="h-[1px] bg-gray-50 my-1" />

              <p className="px-3 py-1 text-[9px] font-black text-gray-400 uppercase tracking-widest">Status Governance</p>

              {isLocked && (
                <button 
                  onClick={() => unlockEmployee(emp.id)} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-orange-600 hover:bg-orange-50 flex items-center gap-3"
                >
                  <Unlock size={14}/> Emergency Unlock
                </button>
              )}

              {emp.status !== 'Active' && (
                <button 
                  onClick={() => updateEmployeeStatus(emp.id, 'Active')} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-green-600 hover:bg-green-50 flex items-center gap-3"
                >
                  <UserCheck size={14}/> Activate
                </button>
              )}

              {emp.status !== 'Inactive' && (
                <button 
                  onClick={() => updateEmployeeStatus(emp.id, 'Inactive')} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-gray-600 hover:bg-gray-50 flex items-center gap-3"
                >
                  <UserX size={14}/> Deactivate
                </button>
              )}

              {emp.status !== 'Frozen' && (
                <button 
                  onClick={() => { setEmployeeToFreeze(emp); setIsDeleteConfirmed(false); }} 
                  className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-blue-600 hover:bg-blue-50 flex items-center gap-3"
                >
                  <Snowflake size={14}/> Freeze Account
                </button>
              )}

              <div className="h-[1px] bg-gray-50 my-1" />

              <button 
                onClick={() => { setEmployeeToDelete(emp); setIsDeleteConfirmed(false); }} 
                className="w-full text-left px-3 py-2 rounded-xl text-xs font-bold text-red-600 hover:bg-red-50 flex items-center gap-3"
              >
                <Trash2 size={14}/> Delete Permanently
              </button>
            </div>
          </div>
        )}
      </div>
    );
  };

  const renderListView = () => (
    <div key="list" className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden animate-in fade-in zoom-in-95 duration-500">
      <table className="w-full text-left">
        <thead>
          <tr className="bg-gray-50/50 border-b border-gray-100">
            <th className="px-6 py-5 w-10">
              <button onClick={toggleSelectAll} className={`w-5 h-5 rounded flex items-center justify-center transition-all ${selectedIds.length === filteredEmployees.length ? 'bg-blue-900 text-white' : 'bg-white border border-gray-300 text-transparent'}`}>
                {selectedIds.length === filteredEmployees.length ? <CheckSquare size={14} /> : <Square size={14} />}
              </button>
            </th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Employee ID</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Profile</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Department</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Status</th>
            <th className="px-6 py-5 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Actions</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-50">
          {filteredEmployees.map(emp => {
            const isSelected = selectedIds.includes(emp.id);
            return (
              <tr 
                key={emp.id} 
                onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }} 
                className={`hover:bg-blue-50/30 transition-all cursor-pointer ${isSelected ? 'bg-blue-50/50' : ''}`}
              >
                <td className="px-6 py-4">
                  <button onClick={(e) => toggleSelect(emp.id, e)} className={`w-5 h-5 rounded flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-white border border-gray-200 text-transparent'}`}>
                    {isSelected ? <CheckSquare size={14} /> : <Square size={14} />}
                  </button>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-xs font-bold text-gray-400">{emp.employeeId}</td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="flex items-center gap-4">
                    <img src={emp.avatar} alt="" className="w-10 h-10 rounded-2xl object-cover" />
                    <div>
                      <p className="text-sm font-bold text-blue-900">{emp.name}</p>
                      <p className="text-[11px] text-gray-400 font-bold uppercase">{emp.role}</p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-[11px] font-bold text-gray-500 uppercase">{emp.department}</td>
                <td className="px-6 py-4 whitespace-nowrap"><StatusBadge emp={emp} /></td>
                <td className="px-6 py-4 text-right"><ActionMenu emp={emp} /></td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );

  const renderGridView = () => (
    <div key="grid" className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 animate-in fade-in zoom-in-95 duration-500">
      {filteredEmployees.map(emp => {
        const isSelected = selectedIds.includes(emp.id);
        return (
          <div 
            key={emp.id} 
            onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }}
            className={`bg-white p-6 rounded-[2.5rem] border transition-all cursor-pointer relative group ${isSelected ? 'border-blue-900 bg-blue-50/20 ring-4 ring-blue-900/5 shadow-md' : 'border-gray-100 shadow-sm hover:border-blue-200 hover:shadow-lg'}`}
          >
            <div className="absolute top-4 left-4 z-10">
              <button 
                onClick={(e) => toggleSelect(emp.id, e)} 
                className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-white/80 border border-gray-200 text-transparent hover:border-blue-400 backdrop-blur-sm opacity-0 group-hover:opacity-100'}`}
              >
                {isSelected ? <CheckSquare size={16} /> : <Square size={16} />}
              </button>
            </div>
            <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
              <ActionMenu emp={emp} />
            </div>
            <div className="flex flex-col items-center text-center">
              <img src={emp.avatar} alt="" className="w-20 h-20 rounded-[2rem] object-cover mb-4 shadow-md border-4 border-white" />
              <h3 className="text-sm font-bold text-blue-900 mb-1">{emp.name}</h3>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">{emp.role}</p>
              <div className="flex flex-col gap-2 w-full">
                <div className="flex items-center justify-between bg-gray-50 p-2 rounded-xl">
                  <span className="text-[9px] font-black text-gray-400 uppercase">Dept</span>
                  <span className="text-[10px] font-bold text-blue-900">{emp.department}</span>
                </div>
                <div className="flex items-center justify-between bg-gray-50 p-2 rounded-xl">
                  <span className="text-[9px] font-black text-gray-400 uppercase">ID</span>
                  <span className="text-[10px] font-bold text-blue-900">{emp.employeeId}</span>
                </div>
              </div>
              <div className="mt-4">
                <StatusBadge emp={emp} />
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );

  const renderCompactView = () => (
    <div key="compact" className="space-y-2 animate-in fade-in zoom-in-95 duration-500">
      {filteredEmployees.map(emp => {
        const isSelected = selectedIds.includes(emp.id);
        return (
          <div 
            key={emp.id} 
            onClick={() => { setViewingEmployee(emp); setTaskSearchTerm(''); }}
            className={`px-6 py-3 rounded-2xl border transition-all cursor-pointer flex items-center justify-between ${isSelected ? 'bg-blue-50 border-blue-900 shadow-sm' : 'bg-white border-gray-100 shadow-sm hover:bg-blue-50/30'}`}
          >
            <div className="flex items-center gap-4 flex-1">
              <button 
                onClick={(e) => toggleSelect(emp.id, e)} 
                className={`w-5 h-5 rounded flex items-center justify-center transition-all ${isSelected ? 'bg-blue-900 text-white shadow-sm' : 'bg-gray-50 border border-gray-200 text-transparent'}`}
              >
                {isSelected ? <CheckSquare size={14} /> : <Square size={14} />}
              </button>
              <span className="text-[10px] font-black text-gray-300 w-16">{emp.employeeId}</span>
              <div className="flex items-center gap-3">
                <img src={emp.avatar} alt="" className="w-8 h-8 rounded-xl object-cover" />
                <p className="text-xs font-bold text-blue-900">{emp.name}</p>
              </div>
            </div>
            <div className="flex items-center gap-8">
              <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest hidden md:block">{emp.department}</span>
              <StatusBadge emp={emp} />
              <ActionMenu emp={emp} />
            </div>
          </div>
        );
      })}
    </div>
  );

  const isViewedEmpLocked = viewingEmployee?.lockoutUntil && new Date(viewingEmployee.lockoutUntil).getTime() > Date.now();

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-24 relative">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900 uppercase tracking-tighter">Personnel Profiles</h1>
          <p className="text-gray-500 font-medium">Browse and manage comprehensive organization profiles.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <button 
            onClick={() => setIsAddingEmployee(true)}
            className="flex items-center gap-2 px-5 py-2.5 bg-blue-900 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95"
          >
            <Plus size={18} /> Create Profile
          </button>
        </div>
      </header>

      {/* Search & Filters */}
      <div className="flex flex-col xl:flex-row gap-4 items-center">
        <div className="flex-1 relative w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search profiles by name, role, email..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm font-medium text-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex flex-wrap items-center gap-3 w-full xl:w-auto">
          <button 
            onClick={handleExportCSV}
            className="flex items-center gap-2 px-5 py-3 bg-white border border-gray-200 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-gray-50 text-blue-900 transition-all shadow-sm active:scale-95"
          >
            <FileDown size={16} /> Export CSV
          </button>
          <div className="flex items-center gap-1 p-1.5 bg-gray-100 rounded-[1.25rem]">
            {(['list', 'grid', 'compact'] as ViewMode[]).map((mode) => (
              <button 
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`p-2 rounded-xl transition-all duration-300 ${viewMode === mode ? 'bg-white text-blue-900 shadow-sm scale-110' : 'text-gray-400 hover:text-gray-600'}`}
                title={`${mode.charAt(0).toUpperCase() + mode.slice(1)} View`}
              >
                {mode === 'list' && <LayoutList size={20} />}
                {mode === 'grid' && <LayoutGrid size={20} />}
                {mode === 'compact' && <Rows3 size={20} />}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="min-h-[400px]">
        {filteredEmployees.length === 0 ? (
          <div className="bg-white rounded-[2.5rem] p-16 text-center border border-gray-100 shadow-sm animate-in fade-in duration-500">
            <UserCircle size={48} className="mx-auto text-gray-200 mb-4" />
            <h3 className="text-xl font-bold text-blue-900">No profiles found</h3>
          </div>
        ) : (
          <div className="transition-all duration-500">
            {viewMode === 'list' && renderListView()}
            {viewMode === 'grid' && renderGridView()}
            {viewMode === 'compact' && renderCompactView()}
          </div>
        )}
      </div>

      {/* Bulk Action Bar */}
      {selectedIds.length > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 w-full max-w-lg px-4 z-[100] animate-in slide-in-from-bottom-10 duration-500">
          <div className="bg-blue-900 text-white p-4 rounded-[2.5rem] shadow-2xl flex items-center justify-between border border-white/10 backdrop-blur-md">
            <div className="flex items-center gap-4 ml-4">
              <div className="w-10 h-10 bg-white/20 rounded-2xl flex items-center justify-center">
                <Hash size={20} />
              </div>
              <div>
                <p className="text-xs font-black uppercase tracking-widest">{selectedIds.length} Profiles Selected</p>
                <p className="text-[10px] font-bold text-white/60 uppercase">Bulk Registry Control</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={() => { setShowBulkDeleteConfirm(true); setIsDeleteConfirmed(false); }}
                className="px-6 py-3 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-50 transition-all active:scale-95 shadow-xl flex items-center gap-2"
              >
                <Trash2 size={14} /> Bulk Delete
              </button>
              <button 
                onClick={() => setSelectedIds([])}
                className="p-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl transition-all"
              >
                <X size={18} />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* FREEZE CONFIRMATION MODAL */}
      {employeeToFreeze && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-blue-900/40 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setEmployeeToFreeze(null)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex flex-col items-center text-center">
              <div className="w-24 h-24 bg-blue-50 text-blue-600 rounded-[2.5rem] flex items-center justify-center mb-8 shadow-inner">
                <Snowflake size={48} />
              </div>
              <h2 className="text-3xl font-black text-blue-900 mb-2 uppercase tracking-tighter leading-none">Freeze Access</h2>
              <p className="text-sm text-gray-500 mb-6 font-bold uppercase tracking-widest leading-relaxed">
                Immediately suspend access for <span className="text-blue-900 font-black">{employeeToFreeze.name}</span>?
              </p>

              <div className="w-full bg-blue-50 p-6 rounded-3xl border border-blue-100 mb-8 text-left">
                <p className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-2">Security Implications</p>
                <ul className="text-[11px] text-blue-900 font-bold space-y-2">
                  <li className="flex items-center gap-2">• Login will be instantly prohibited</li>
                  <li className="flex items-center gap-2">• Data modification will be locked</li>
                  <li className="flex items-center gap-2">• Task participation will be suspended</li>
                </ul>
              </div>

              <div className="w-full space-y-4 mb-10">
                <button 
                  onClick={() => setIsDeleteConfirmed(!isDeleteConfirmed)}
                  className="flex items-start gap-3 text-left group transition-all"
                >
                  <div className={`mt-0.5 shrink-0 transition-all ${isDeleteConfirmed ? 'text-blue-600' : 'text-gray-300 group-hover:text-blue-300'}`}>
                    {isDeleteConfirmed ? <CheckSquare size={20} /> : <Square size={20} />}
                  </div>
                  <span className={`text-[11px] font-bold uppercase tracking-tight leading-snug transition-all ${isDeleteConfirmed ? 'text-blue-700' : 'text-gray-400'}`}>
                    I authorize the immediate freezing of this personnel account.
                  </span>
                </button>
              </div>

              <div className="flex flex-col w-full gap-3">
                <button 
                  onClick={handleFreezeEmployee}
                  disabled={!isDeleteConfirmed}
                  className={`w-full py-5 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 ${
                    isDeleteConfirmed ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-600/20' : 'bg-gray-100 text-gray-300 cursor-not-allowed'
                  }`}
                >
                  Execute Freeze
                </button>
                <button 
                  onClick={() => setEmployeeToFreeze(null)}
                  className="w-full py-5 bg-gray-50 text-gray-400 rounded-2xl font-black uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* INDIVIDUAL DELETE MODAL */}
      {employeeToDelete && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-blue-900/40 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setEmployeeToDelete(null)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex flex-col items-center text-center">
              <div className="w-24 h-24 bg-red-50 text-red-600 rounded-[2.5rem] flex items-center justify-center mb-8 shadow-inner">
                <Trash2 size={48} />
              </div>
              <h2 className="text-3xl font-black text-blue-900 mb-2 uppercase tracking-tighter leading-none">Purge Profile</h2>
              <p className="text-sm text-gray-500 mb-6 font-bold uppercase tracking-widest leading-relaxed">
                Permanently remove <span className="text-blue-900 font-black">{employeeToDelete.name}</span> from the organizational registry?
              </p>

              <div className="w-full bg-red-50 p-6 rounded-3xl border border-red-100 mb-8 text-left">
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint size={18} className="text-red-600" />
                  <p className="text-sm font-black text-red-700">{employeeToDelete.employeeId}</p>
                </div>
                <p className="text-[10px] font-black text-red-400 uppercase tracking-widest ml-7">Registry UID: {employeeToDelete.id}</p>
              </div>

              <div className="w-full space-y-4 mb-10">
                <button 
                  onClick={() => setIsDeleteConfirmed(!isDeleteConfirmed)}
                  className="flex items-start gap-3 text-left group transition-all"
                >
                  <div className={`mt-0.5 shrink-0 transition-all ${isDeleteConfirmed ? 'text-red-600' : 'text-gray-300 group-hover:text-red-300'}`}>
                    {isDeleteConfirmed ? <CheckSquare size={20} /> : <Square size={20} />}
                  </div>
                  <span className={`text-[11px] font-bold uppercase tracking-tight leading-snug transition-all ${isDeleteConfirmed ? 'text-red-700' : 'text-gray-400'}`}>
                    I acknowledge that this personnel record and all associated history will be permanently erased. This action cannot be undone.
                  </span>
                </button>
              </div>

              <div className="flex flex-col w-full gap-3">
                <button 
                  onClick={handleDeleteEmployee}
                  disabled={!isDeleteConfirmed}
                  className={`w-full py-5 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 ${
                    isDeleteConfirmed ? 'bg-red-600 hover:bg-red-700 shadow-red-600/20' : 'bg-gray-100 text-gray-300 cursor-not-allowed'
                  }`}
                >
                  Authorize Purge
                </button>
                <button 
                  onClick={() => setEmployeeToDelete(null)}
                  className="w-full py-5 bg-gray-50 text-gray-400 rounded-2xl font-black uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* New Profile Modal */}
      {isAddingEmployee && (
        <div className="fixed inset-0 z-[150] overflow-hidden">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setIsAddingEmployee(false)} />
          <div className="absolute inset-y-0 right-0 max-w-md w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between bg-blue-900 text-white">
              <div className="flex items-center gap-4">
                <UserPlus size={24} />
                <h2 className="text-xl font-bold">New Profile</h2>
              </div>
              <button onClick={() => setIsAddingEmployee(false)} className="p-2 hover:bg-white/10 rounded-xl"><X size={24} /></button>
            </div>
            <form onSubmit={handleAddEmployee} className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              {formError && (
                <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 animate-in slide-in-from-top-2">
                  <AlertTriangle className="text-red-600 shrink-0" size={18} />
                  <p className="text-xs font-bold text-red-700">{formError}</p>
                </div>
              )}
              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Employee ID</label>
                  <div className="relative group mt-1">
                    <Fingerprint className={`absolute left-4 top-1/2 -translate-y-1/2 transition-colors ${!isIdFormatValid && newEmp.employeeId ? 'text-red-400' : 'text-gray-300 group-focus-within:text-blue-900'}`} size={18} />
                    <input 
                      required 
                      placeholder="e.g. SA-005" 
                      className={`w-full pl-12 pr-5 py-4 bg-gray-50 border rounded-2xl outline-none font-bold text-sm transition-all ${
                        !newEmp.employeeId ? 'border-gray-100' : 
                        (!isIdFormatValid || !isIdUnique) ? 'border-red-200 focus:ring-red-500/5 focus:bg-white' : 
                        'border-green-200 focus:ring-green-500/5 focus:bg-white'
                      }`} 
                      value={newEmp.employeeId} 
                      onChange={e => setNewEmp({...newEmp, employeeId: e.target.value.toUpperCase()})} 
                    />
                  </div>
                  {!isIdFormatValid && newEmp.employeeId && (
                    <p className="text-[10px] text-red-500 mt-1 font-bold">ID must start with 'SA-' followed by numbers.</p>
                  )}
                  {!isIdUnique && (
                    <p className="text-[10px] text-red-500 mt-1 font-bold">This ID is already taken.</p>
                  )}
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Full Legal Name</label>
                  <input required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all" value={newEmp.name} onChange={e => setNewEmp({...newEmp, name: e.target.value})} />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Professional Email</label>
                  <input type="email" required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all" value={newEmp.email} onChange={e => setNewEmp({...newEmp, email: e.target.value})} />
                </div>

                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Access Token (Password)</label>
                  <div className="relative group mt-1">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-blue-900 transition-colors" size={18} />
                    <input 
                      required 
                      type={showNewEmpPassword ? "text" : "password"}
                      className="w-full pl-12 pr-12 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all text-blue-900" 
                      value={newEmp.password} 
                      onChange={e => setNewEmp({...newEmp, password: e.target.value})} 
                    />
                    <button 
                      type="button"
                      onClick={() => setShowNewEmpPassword(!showNewEmpPassword)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 hover:text-blue-900 transition-colors"
                    >
                      {showNewEmpPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Position</label>
                    <input required className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all" value={newEmp.role} onChange={e => setNewEmp({...newEmp, role: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Department</label>
                    <select className="w-full px-5 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-sm focus:ring-4 focus:ring-blue-500/5 focus:bg-white transition-all" value={newEmp.department} onChange={e => setNewEmp({...newEmp, department: e.target.value})}>
                      {DEPARTMENTS.map(d => <option key={d}>{d}</option>)}
                    </select>
                  </div>
                </div>
              </div>
              <div className="pt-4 space-y-4">
                <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 flex items-center gap-3">
                  <MailCheck size={18} className="text-blue-600" />
                  <p className="text-[10px] text-blue-900 font-bold uppercase tracking-tight">Onboarding alert will be dispatched to saisurendra@srinidhiassociates.co.in</p>
                </div>
                <button 
                  type="submit" 
                  disabled={!canSubmit}
                  className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-bold text-sm uppercase tracking-widest shadow-xl shadow-blue-900/20 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale disabled:cursor-not-allowed"
                >
                  Initialize Profile
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {viewingEmployee && (
        <div className="fixed inset-0 z-[140] overflow-hidden">
          <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={() => setViewingEmployee(null)} />
          <div className="absolute inset-y-0 right-0 max-w-lg w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300 border-l border-gray-100">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between">
              <h2 className="text-xl font-bold text-blue-900 uppercase tracking-tighter">Personnel File</h2>
              <button onClick={() => setViewingEmployee(null)} className="p-2 hover:bg-gray-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-8 no-scrollbar space-y-12 pb-24">
              <div className="flex items-center gap-8">
                <img src={viewingEmployee.avatar} className="w-28 h-28 rounded-[2.5rem] object-cover shadow-2xl shadow-blue-900/10 border-4 border-white" alt="" />
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <Fingerprint size={12} className="text-blue-900/30" />
                    <span className="text-[10px] font-black text-blue-900/30 uppercase">{viewingEmployee.employeeId}</span>
                  </div>
                  <h3 className="text-2xl font-bold text-blue-900 tracking-tight">{viewingEmployee.name}</h3>
                  <p className="text-gray-500 font-medium">{viewingEmployee.role}</p>
                  <div className="flex items-center gap-2 mt-2">
                    <StatusBadge emp={viewingEmployee} />
                    <span className="text-[9px] font-black text-gray-400 uppercase border px-2 py-0.5 rounded-lg">{viewingEmployee.department}</span>
                  </div>
                </div>
              </div>

              {/* Status Governance Panel */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-gray-400 uppercase flex items-center gap-2">
                  <Activity size={16} className="text-blue-900" /> Lifecycle Controls
                </h4>
                <div className="grid grid-cols-2 gap-3">
                   {isViewedEmpLocked && (
                     <button 
                      onClick={() => unlockEmployee(viewingEmployee.id)} 
                      className="flex items-center justify-center gap-3 p-4 rounded-2xl border border-orange-200 bg-orange-50 text-orange-700 font-black text-[10px] uppercase tracking-widest hover:bg-orange-100 transition-all col-span-2"
                    >
                      <Unlock size={16} /> Force Unlock Account
                    </button>
                   )}
                   <button 
                    onClick={() => updateEmployeeStatus(viewingEmployee.id, 'Active')} 
                    className={`flex items-center justify-center gap-3 p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${
                      viewingEmployee.status === 'Active' ? 'bg-green-50 border-green-200 text-green-700' : 'bg-white border-gray-100 text-gray-400 hover:border-green-200 hover:text-green-600'
                    }`}
                  >
                    <UserCheck size={16} /> Active
                  </button>
                  <button 
                    onClick={() => updateEmployeeStatus(viewingEmployee.id, 'Inactive')} 
                    className={`flex items-center justify-center gap-3 p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${
                      viewingEmployee.status === 'Inactive' ? 'bg-gray-100 border-gray-200 text-gray-600' : 'bg-white border-gray-100 text-gray-400 hover:border-gray-200 hover:text-gray-600'
                    }`}
                  >
                    <Power size={16} /> Inactive
                  </button>
                  <button 
                    onClick={() => { setEmployeeToFreeze(viewingEmployee); setIsDeleteConfirmed(false); }} 
                    className={`flex items-center justify-center gap-3 p-4 rounded-2xl border font-black text-[10px] uppercase tracking-widest transition-all ${
                      viewingEmployee.status === 'Frozen' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-gray-100 text-gray-400 hover:border-blue-200 hover:text-blue-600'
                    }`}
                  >
                    <Snowflake size={16} /> Freeze
                  </button>
                  <button 
                    onClick={() => { setEmployeeToDelete(viewingEmployee); setIsDeleteConfirmed(false); }} 
                    className="flex items-center justify-center gap-3 p-4 rounded-2xl border border-red-50 text-red-400 font-black text-[10px] uppercase tracking-widest hover:bg-red-50 hover:text-red-600 transition-all"
                  >
                    <Trash2 size={16} /> Purge
                  </button>
                </div>
              </div>

              {/* Task Management */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-gray-400 uppercase flex items-center gap-2">
                  <ClipboardList size={16} className="text-blue-900" /> Assignments
                </h4>
                <div className="rounded-[2rem] p-6 border bg-gray-50 border-gray-100 space-y-5">
                   <div className="grid grid-cols-1 gap-4">
                     <div className="space-y-1">
                       <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Assigned To</label>
                       <input readOnly className="w-full px-5 py-3 bg-white/50 border border-gray-100 rounded-xl text-xs font-bold text-gray-500 cursor-not-allowed italic" value={viewingEmployee.name} />
                     </div>
                     <div className="space-y-1">
                       <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Task Definition</label>
                       <input 
                         type="text" 
                         placeholder="e.g. Q3 Performance Audit" 
                         className="w-full px-5 py-3 bg-white border border-gray-200 rounded-xl text-xs font-bold text-blue-900 outline-none"
                         value={newTaskTitle}
                         onChange={(e) => setNewTaskTitle(e.target.value)}
                       />
                     </div>
                     <button 
                       onClick={addTask}
                       disabled={!newTaskTitle.trim()}
                       className="w-full py-4 bg-blue-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-blue-800 disabled:opacity-50"
                     >
                       Initialize Assignment
                     </button>
                   </div>
                </div>

                {/* Task Search Bar */}
                <div className="space-y-4">
                  <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-900 transition-colors" size={14} />
                    <input 
                      type="text" 
                      placeholder="Search assignments..." 
                      className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-bold text-blue-900 outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white transition-all"
                      value={taskSearchTerm}
                      onChange={(e) => setTaskSearchTerm(e.target.value)}
                    />
                  </div>

                  <div className="space-y-3">
                    {filteredMemberTasks.length === 0 ? (
                      <div className="p-8 text-center bg-gray-50 rounded-2xl border border-dashed border-gray-200">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest italic">No assignments match your search</p>
                      </div>
                    ) : (
                      filteredMemberTasks.map(task => (
                        <div key={task.id} className={`p-4 rounded-2xl border transition-all flex items-center justify-between ${
                          task.status === 'Completed' ? 'bg-green-50/50 border-green-100' :
                          task.status === 'In Progress' ? 'bg-blue-50/50 border-blue-100' :
                          'bg-gray-50 border-gray-100'
                        }`}>
                          <div className="flex items-center gap-3">
                            <div className={`p-1.5 rounded-lg ${
                              task.status === 'Completed' ? 'bg-green-100 text-green-700' :
                              task.status === 'In Progress' ? 'bg-blue-100 text-blue-900' :
                              'bg-white text-gray-400 border border-gray-100'
                            }`}>
                              <Clock size={14} />
                            </div>
                            <div>
                              <span className={`text-xs font-bold ${task.status === 'Completed' ? 'text-green-800 line-through opacity-60' : 'text-blue-900'}`}>{task.title}</span>
                              <p className="text-[8px] font-bold text-gray-400 uppercase tracking-tight mt-0.5">Due: {task.dueDate}</p>
                            </div>
                          </div>
                          <span className={`text-[8px] font-black px-2 py-1 rounded uppercase tracking-widest ${
                            task.status === 'Completed' ? 'bg-green-500 text-white shadow-sm' :
                            task.status === 'In Progress' ? 'bg-blue-900 text-white shadow-sm' :
                            'bg-gray-200 text-gray-600'
                          }`}>{task.status}</span>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>

              {/* Security Overwrite */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-gray-400 uppercase flex items-center gap-2"><ShieldAlert size={16} className="text-orange-500" /> Security</h4>
                <div className="rounded-[2rem] p-6 border bg-orange-50/50 border-orange-100 space-y-4">
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-orange-200" size={18} />
                    <input 
                      type="password" 
                      placeholder="New access token..." 
                      className="w-full pl-12 pr-12 py-4 bg-white border border-orange-200 rounded-2xl text-sm outline-none font-bold" 
                      value={adminResetPass} 
                      onChange={(e) => setAdminResetPass(e.target.value)} 
                    />
                    <button onClick={handleAdminResetPassword} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-orange-600 text-white rounded-xl">
                      <UserCheck size={20}/>
                    </button>
                  </div>
                  {resetSuccess && (
                    <div className="flex items-center gap-2 text-[10px] font-black text-green-700 uppercase tracking-widest animate-in fade-in">
                      <CheckCircle size={14} /> Update Committed
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Employees;

