                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Statement Year</label>
                  <select 
                    value={payslipFormData.year}
                    onChange={e => setPayslipFormData({...payslipFormData, year: e.target.value})}
                    className="w-full px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-900/5 transition-all font-bold text-xs text-blue-900"
                  >
                    {['2023', '2024', '2025'].map(y => <option key={y}>{y}</option>)}
