                   <div className="space-y-1 mb-8">
                     <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{payslip.ownerName}</p>
                     <h3 className="text-xl font-black text-blue-900 uppercase tracking-tight">Period: {payslip.name}</h3>
                   </div>

                   <button 
                    onClick={() => handleDownloadPayslip(payslip)}
                    className="w-full py-4 bg-gray-50 text-blue-900 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-blue-900 hover:text-white transition-all active:scale-95 group-hover:shadow-lg group-hover:shadow-blue-900/10"
                   >
                     <Download size={16} /> Download PDF Statement
                   </button>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* HR Payslip Release Modal */}
      {isGeneratingPayslip && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300" onClick={() => setIsGeneratingPayslip(false)}></div>
          <div className="relative bg-white rounded-[3.5rem] p-12 max-w-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-900 text-white rounded-3xl shadow-lg shadow-blue-900/20"><CreditCard size={24} /></div>
                <div><h2 className="text-2xl font-black text-blue-900 uppercase tracking-tighter">Release Payslip</h2></div>
              </div>
              <button onClick={() => setIsGeneratingPayslip(false)} className="p-2 hover:bg-gray-100 rounded-xl transition-all"><X size={20}/></button>
            </div>
            <form onSubmit={handleGeneratePayslip} className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Target Personnel</label>
                <div className="relative group">
                  <UserCircle className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-blue-900" size={18} />
                  <input type="text" required placeholder="Personnel ID or Name" value={payslipFormData.employeeId} onChange={e => setPayslipFormData({...payslipFormData, employeeId: e.target.value})} className="w-full pl-12 pr-6 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-blue-900/5 focus:bg-white transition-all font-bold text-sm text-blue-900" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Period Month</label>
                  <select value={payslipFormData.month} onChange={e => setPayslipFormData({...payslipFormData, month: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-transparent rounded-2xl font-bold text-xs text-blue-900 outline-none">
                    {['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'].map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Period Year</label>
                  <select value={payslipFormData.year} onChange={e => setPayslipFormData({...payslipFormData, year: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-transparent rounded-2xl font-bold text-xs text-blue-900 outline-none">
                    {['2023', '2024', '2025'].map(y => <option key={y} value={y}>{y}</option>)}
                  </select>
                </div>
              </div>
              <button type="submit" className="w-full py-5 bg-blue-900 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-blue-800 transition-all shadow-xl shadow-blue-900/20 flex items-center justify-center gap-3">Commit to Registry <ArrowRight size={18} /></button>
            </form>
          </div>
        </div>
      )}

      {docToDelete && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-blue-900/20 backdrop-blur-sm" onClick={() => setDocToDelete(null)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-md w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-red-50 text-red-600 rounded-[2rem] flex items-center justify-center mb-8 shadow-inner"><TriangleAlert size={40} /></div>
              <h2 className="text-2xl font-bold text-blue-900 mb-2 uppercase tracking-tighter">Purge Authorization</h2>
              <p className="text-sm text-gray-400 mb-10 font-bold uppercase tracking-widest leading-relaxed">Permanently erase this record from the organizational file?</p>
              <div className="w-full space-y-4 mb-10">
                <button onClick={() => setIsDeleteConfirmed(!isDeleteConfirmed)} className="flex items-start gap-3 text-left group transition-all">
                  <div className={`mt-0.5 shrink-0 transition-all ${isDeleteConfirmed ? 'text-red-600' : 'text-gray-300 group-hover:text-red-300'}`}>{isDeleteConfirmed ? <CheckSquare size={20} /> : <Square size={20} />}</div>
                  <span className={`text-[11px] font-bold uppercase tracking-tight leading-snug transition-all ${isDeleteConfirmed ? 'text-red-700' : 'text-gray-400'}`}>I authorize this irreversible action and acknowledge all audit history will be deleted.</span>
                </button>
              </div>
              <div className="flex flex-col w-full gap-3">
                <button onClick={finalizeDelete} disabled={!isDeleteConfirmed} className={`w-full py-5 text-white rounded-2xl font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 ${isDeleteConfirmed ? 'bg-red-600 hover:bg-red-700' : 'bg-gray-100 text-gray-300 cursor-not-allowed'}`}>Authorize Purge</button>
                <button onClick={() => setDocToDelete(null)} className="w-full py-5 bg-gray-50 text-gray-400 rounded-2xl font-black uppercase tracking-widest hover:bg-gray-100 transition-all">Abort</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Documents;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import Employees from './pages/Employees';
import Recruitment from './pages/Recruitment';
import Performance from './pages/Performance';
import Documents from './pages/Documents';
import Attendance from './pages/Attendance';
import Security from './pages/Security';
import LeaveManagement from './pages/LeaveManagement';
import ExitManagement from './pages/ExitManagement';
import Login from './pages/Login';
import MyTasks from './pages/MyTasks';
import { Bell, Search, LogOut, X, Clock, ShieldAlert, Sparkles, PartyPopper, CheckCircle2 } from 'lucide-react';
import Logo from './components/Logo';
import { User, Employee, Notification, Task, LeaveRequest, ResignationRequest } from './types';
import { MOCK_EMPLOYEES } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [leaveRequests, setLeaveRequests] = useState<LeaveRequest[]>([]);
  const [resignationRequests, setResignationRequests] = useState<ResignationRequest[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showWelcome, setShowWelcome] = useState(false);

  const currentEmployee = employees.find(e => e.id === user?.id);

  // Enforcement logic: If password change is required, lock the user to the security tab
  useEffect(() => {
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      setActiveTab('security');
    }
  }, [currentEmployee?.mustChangePassword, activeTab]);

  // Handle welcome screen visibility
  useEffect(() => {
    if (user && currentEmployee && !currentEmployee.hasLoggedInBefore) {
      setShowWelcome(true);
    }
  }, [user, currentEmployee]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setShowNotifications(false);
    setShowWelcome(false);
  };

  const handleFinishWelcome = () => {
    if (user) {
      setEmployees(prev => prev.map(emp => 
        emp.id === user.id ? { ...emp, hasLoggedInBefore: true } : emp
      ));
    }
    setShowWelcome(false);
  };

  const addNotification = (userId: string, title: string, message: string) => {
    const newNotif: Notification = {
      id: `notif-${Date.now()}`,
      userId,
      title,
      message,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isRead: false
    };
    setNotifications(prev => [newNotif, ...prev]);
  };

  const markAllAsRead = () => {
    setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const userNotifications = notifications.filter(n => n.userId === user?.id || (user?.role === 'HR'));
  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleUpdateTaskStatus = (taskId: string, status: Task['status']) => {
    setEmployees(prev => prev.map(emp => {
      if (emp.id === user?.id) {
        return {
          ...emp,
          tasks: (emp.tasks || []).map(t => t.id === taskId ? { ...t, status } : t)
        };
      }
      return emp;
    }));
  };

  const renderContent = () => {
    if (!user) return null;

    // If user must change password, restrict access to other pages
    if (currentEmployee?.mustChangePassword && activeTab !== 'security') {
      return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'tasks': return currentEmployee ? <MyTasks employee={currentEmployee} onUpdateTask={handleUpdateTaskStatus} /> : <Dashboard />;
      case 'profiles': return user.role === 'HR' ? <Employees employees={employees} setEmployees={setEmployees} addNotification={addNotification} /> : <Dashboard />;
      case 'recruitment': return user.role === 'HR' ? <Recruitment /> : <Dashboard />;
      case 'performance': return <Performance />;
      case 'attendance': return <Attendance user={user} />;
      case 'leave': return (
        <LeaveManagement 
          user={user} 
          leaveRequests={leaveRequests} 
          setLeaveRequests={setLeaveRequests}
          addNotification={addNotification}
          employees={employees}
        />
      );
      case 'exit': return (
        <ExitManagement
          user={user}
          resignationRequests={resignationRequests}
          setResignationRequests={setResignationRequests}
          addNotification={addNotification}
          employees={employees}
          setEmployees={setEmployees}
        />
      );
      case 'documents': return (
        <Documents 
          user={user} 
          allEmployees={employees} 
          setEmployees={setEmployees} 
          addNotification={addNotification}
        />
      );
      case 'security': return <Security user={user} employees={employees} setEmployees={setEmployees} addNotification={addNotification} />;
      default: return <Dashboard />;
    }
  };

  // If user is not logged in, show the Login page
  if (!user) {
    return <Login onLogin={handleLogin} employees={employees} setEmployees={setEmployees} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Welcome Screen Modal */}
      {showWelcome && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-[#1e3a8a]/95 backdrop-blur-xl animate-in fade-in duration-700">
          <div className="max-w-2xl w-full bg-white rounded-[3rem] p-12 text-center relative overflow-hidden shadow-2xl animate-in zoom-in-95 duration-500">
            {/* Decorative background shapes */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-blue-50 rounded-full -mr-32 -mt-32 opacity-50 blur-3xl"></div>
            <div className="absolute bottom-0 left-0 w-64 h-64 bg-purple-50 rounded-full -ml-32 -mb-32 opacity-50 blur-3xl"></div>

            <div className="relative z-10 flex flex-col items-center">
