                              {req.clearanceCompleted && (
                                <span className="px-3 py-1 bg-blue-900 text-white rounded-lg text-[8px] font-black uppercase flex items-center gap-1">
                                  <FileBadge size={10} /> Letter Issued
                                </span>
                              )}
                            </div>
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                          {req.status === 'Pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, 'Accepted')} className="px-4 py-2 bg-green-500 text-white rounded-xl text-[10px] font-black uppercase hover:bg-green-600 transition-all">Accept</button>
                              <button onClick={() => handleAction(req.id, 'Rejected')} className="px-4 py-2 bg-white border border-red-100 text-red-600 rounded-xl text-[10px] font-black uppercase hover:bg-red-50 transition-all">Reject</button>
                            </>
                          )}
                          {req.status === 'Accepted' && !req.clearanceCompleted && (
                            <button 
                              onClick={() => finalizeClearance(req.id)}
                              className="flex items-center gap-2 px-6 py-2.5 bg-blue-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-800 shadow-xl shadow-blue-900/10 active:scale-95"
                            >
                              <ClipboardCheck size={14} /> Finalize Handover & Issue Letter
                            </button>
                          )}
                        </div>
                      </div>
                      <div className="mt-6 p-4 bg-gray-50 rounded-2xl border border-gray-100 italic text-xs text-gray-500">
                        "{req.reason}"
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}
        </div>

        <div className="space-y-8">
          <section className="bg-slate-900 text-white rounded-[3rem] p-10 border border-slate-800 shadow-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-10 text-white/5 pointer-events-none group-hover:text-red-500/10 transition-all duration-700">
              <ShieldAlert size={160} />
            </div>
            <div className="relative z-10">
              <h2 className="text-sm font-black uppercase tracking-[0.2em] mb-8 flex items-center gap-3">
                <div className="p-2 bg-red-600 rounded-lg"><LogOut size={16}/></div>
                Exit Protocols
              </h2>
              <ul className="space-y-6">
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">01</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">Acceptance starts the <span className="text-red-400 font-black">handover period</span>.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[10px] font-black shrink-0">02</div>
                  <p className="text-xs text-slate-300 font-medium leading-relaxed">Relieving letters are generated <span className="text-blue-400 font-black">ONLY</span> after final work completion confirmation by HR.</p>
                </li>
              </ul>

              <div className="mt-10 p-6 bg-white/5 rounded-[2rem] border border-white/10">
                <div className="flex items-center gap-3 text-blue-400 mb-3">
                  <BadgeCheck size={18} />
                  <p className="text-[10px] font-black uppercase tracking-widest">Document Registry</p>
                </div>
                <p className="text-[10px] text-slate-400 font-bold uppercase leading-relaxed tracking-tight">
                  The Relieving Letter will be reflected in the "Documents" page as a verified PDF upon clearance.
                </p>
              </div>
            </div>
          </section>
        </div>
      </div>

      {isApplying && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300" onClick={() => setIsApplying(false)}></div>
          <div className="relative bg-white rounded-[3rem] p-10 max-md w-full shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-400">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-red-600 text-white rounded-2xl"><LogOut size={20}/></div>
                <h2 className="text-xl font-black text-blue-900 uppercase tracking-tighter">Submit Resignation</h2>
              </div>
              <button onClick={() => setIsApplying(false)} className="p-2 hover:bg-gray-100 rounded-xl transition-all"><X size={20}/></button>
            </div>

            <form onSubmit={handleResign} className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Proposed Last Working Date</label>
                <div className="relative group">
                  <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-red-600 transition-colors" size={18} />
                  <input 
                    type="date" 
                    required
                    value={formData.lastWorkingDate}
                    onChange={e => setFormData({...formData, lastWorkingDate: e.target.value})}
                    className="w-full pl-12 pr-6 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-red-900/5 focus:bg-white transition-all font-bold text-sm text-blue-900"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Work Transition Note / Reason</label>
                <textarea 
                  required
                  placeholder="State the primary reason and confirm status of current work assignments..."
                  value={formData.reason}
                  onChange={e => setFormData({...formData, reason: e.target.value})}
                  className="w-full h-32 px-5 py-4 bg-gray-50 border border-transparent rounded-2xl outline-none focus:ring-4 focus:ring-red-900/5 focus:bg-white transition-all font-bold text-sm text-blue-900 resize-none"
                />
              </div>

              <button 
                type="submit"
                className="w-full py-5 bg-red-600 text-white rounded-[2rem] font-black uppercase tracking-widest hover:bg-red-700 transition-all shadow-xl shadow-blue-900/20 active:scale-95 flex items-center justify-center gap-3"
              >
                Apply for Resignation <ArrowRight size={18} />
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExitManagement;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { 
  Upload, 
  FileText, 
  Clock, 
  Trash2, 
  ChevronDown, 
  History, 
  Edit2, 
  Save, 
  ShieldCheck, 
  AlertCircle, 
  TriangleAlert, 
  Loader2, 
  FileUp, 
  X, 
  FileSearch, 
  Search, 
  UserCircle, 
  Hash, 
  Filter, 
  User, 
  ShieldHalf, 
  Download, 
  Info,
  Files,
  UserCheck,
  CheckSquare,
  Square,
  ArrowRight,
  CalendarDays,
  Activity,
  CreditCard,
  CheckCircle2,
  FileBadge,
  CalendarClock,
  Briefcase
} from 'lucide-react';
import { Document, Employee, User as UserType } from '../types';

interface DocumentsProps {
  user: UserType;
  allEmployees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  addNotification: (userId: string, title: string, message: string) => void;
}

interface UploadingFile {
  id: string;
  name: string;
  progress: number;
  size: string;
  status: 'uploading' | 'completed' | 'cancelled';
  intervalId?: number;
}

const Documents: React.FC<DocumentsProps> = ({ user, allEmployees, setEmployees, addNotification }) => {
  const isHR = user.role === 'HR';

  // States for search and filter
  const [searchTerm, setSearchTerm] = useState('');
  const [personnelSearch, setPersonnelSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | 'Verified' | 'Pending'>('All');
  const [activeTab, setActiveTab] = useState<'general' | 'payslips'>('general');

  // UI States
  const [uploadQueue, setUploadQueue] = useState<UploadingFile[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [expandedDocId, setExpandedDocId] = useState<string | null>(null);
  const [editingDocId, setEditingDocId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editType, setEditType] = useState('');
  const [docToDelete, setDocToDelete] = useState<{ docId: string; ownerId: string; name: string } | null>(null);
  const [isDeleteConfirmed, setIsDeleteConfirmed] = useState(false);

  // Payslip generation state (HR)
  const [isGeneratingPayslip, setIsGeneratingPayslip] = useState(false);
  const [payslipFormData, setPayslipFormData] = useState({
    employeeId: '',
    month: new Date().toLocaleString('default', { month: 'long' }),
    year: new Date().getFullYear().toString()
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return () => {
      uploadQueue.forEach(u => {
        if (u.intervalId) clearInterval(u.intervalId);
      });
    };
  }, [uploadQueue]);

  useEffect(() => {
    if (!docToDelete) {
      setIsDeleteConfirmed(false);
    }
  }, [docToDelete]);

  // Utility to check if a payslip period is within the last 3 months
  const isWithinLast3Months = (payslipName: string) => {
    const parts = payslipName.split(' ');
    if (parts.length < 2) return false;

    const monthName = parts[0];
    const year = parseInt(parts[1]);

    const monthMap: { [key: string]: number } = {
      'January': 0, 'February': 1, 'March': 2, 'April': 3, 'May': 4, 'June': 5,
      'July': 6, 'August': 7, 'September': 8, 'October': 9, 'November': 10, 'December': 11
    };

    const payslipMonth = monthMap[monthName];
    if (payslipMonth === undefined || isNaN(year)) return false;

    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();

    const totalPayslipMonths = year * 12 + payslipMonth;
    const totalCurrentMonths = currentYear * 12 + currentMonth;

    const diff = totalCurrentMonths - totalPayslipMonths;
    return diff >= 0 && diff < 3;
  };

  const processedDocs = useMemo(() => {
    let list: Array<Document & { ownerName: string; ownerId: string; ownerEmployeeId: string }> = [];

    if (isHR) {
      allEmployees.forEach(emp => {
        (emp.documents || []).forEach(doc => {
          if (doc.type !== 'Payslip') {
            list.push({
              ...doc,
              ownerName: emp.name,
              ownerId: emp.id,
              ownerEmployeeId: emp.employeeId
            });
          }
        });
      });
    } else {
      const currentEmp = allEmployees.find(e => e.id === user.id);
      if (currentEmp) {
        (currentEmp.documents || []).forEach(doc => {
          if (doc.type !== 'Payslip') {
            list.push({
              ...doc,
              ownerName: currentEmp.name,
              ownerId: currentEmp.id,
              ownerEmployeeId: currentEmp.employeeId
            });
          }
        });
      }
    }

    return list.filter(doc => {
      const matchesSearch = doc.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesPersonnel = isHR ? (
        doc.ownerName.toLowerCase().includes(personnelSearch.toLowerCase()) ||
        doc.ownerEmployeeId.toLowerCase().includes(personnelSearch.toLowerCase())
      ) : true;
      const matchesStatus = statusFilter === 'All' || doc.status === statusFilter;

      return matchesSearch && matchesPersonnel && matchesStatus;
    });
  }, [allEmployees, isHR, user.id, searchTerm, personnelSearch, statusFilter]);

  const payslips = useMemo(() => {
    let list: Array<Document & { ownerName: string; ownerId: string; ownerEmployeeId: string }> = [];

    if (isHR) {
      allEmployees.forEach(emp => {
        (emp.documents || []).forEach(doc => {
          if (doc.type === 'Payslip') {
            list.push({
              ...doc,
              ownerName: emp.name,
              ownerId: emp.id,
              ownerEmployeeId: emp.employeeId
            });
          }
        });
      });
    } else {
      const currentEmp = allEmployees.find(e => e.id === user.id);
      if (currentEmp) {
        (currentEmp.documents || []).forEach(doc => {
          if (doc.type === 'Payslip') {
            list.push({
              ...doc,
              ownerName: currentEmp.name,
              ownerId: currentEmp.id,
              ownerEmployeeId: currentEmp.employeeId
            });
          }
        });
      }
    }

    return list.filter(p => {
      const matchesPersonnel = isHR ? (
        p.ownerName.toLowerCase().includes(personnelSearch.toLowerCase()) ||
        p.ownerEmployeeId.toLowerCase().includes(personnelSearch.toLowerCase())
      ) : true;

      if (!matchesPersonnel) return false;

      if (!isHR) {
        return isWithinLast3Months(p.name);
      }

      return true;
    }).sort((a, b) => new Date(b.uploadDate).getTime() - new Date(a.uploadDate).getTime());
  }, [allEmployees, isHR, user.id, personnelSearch]);

  const handleDownloadPayslip = (payslip: Document & { ownerName: string }) => {
    const content = `
      SRINIDHI ASSOCIATES - OFFICIAL PAYSLIP
      -------------------------------------
      Employee: ${payslip.ownerName}
      Document ID: ${payslip.id}
      Reference Month: ${payslip.name}
      Issue Date: ${payslip.uploadDate}
      Registry Status: VERIFIED
      Format: PDF (Security Enforced)

      This document is a digitally signed electronic record.
      Generated via Srinidhi HRMS Core.
    `;
    const blob = new Blob([content], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Payslip_${payslip.name.replace(/\s+/g, '_')}.pdf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleDownloadRelievingLetter = (doc: Document & { ownerName: string }) => {
    const content = `
      SRINIDHI ASSOCIATES - OFFICIAL RELIEVING LETTER
      ----------------------------------------------
      Issue Date: ${doc.uploadDate}
      Registry UID: ${doc.id}

      To Whom It May Concern,

      This is to certify that ${doc.ownerName} was employed with Srinidhi Associates. 
      Their resignation has been processed, all work handovers are confirmed completed, 
      and they have been relieved of their duties as of ${doc.uploadDate}.

      We wish them success in their future endeavors.

      Digitally Signed: 
      Clearance Authority - Srinidhi Associates
      Verification Token: ${doc.id}
    `;
    const blob = new Blob([content], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Relieving_Letter_${doc.ownerName.replace(/\s+/g, '_')}.pdf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleGeneratePayslip = (e: React.FormEvent) => {
    e.preventDefault();
    if (!payslipFormData.employeeId) return;

    const targetEmp = allEmployees.find(emp => emp.id === payslipFormData.employeeId || emp.employeeId === payslipFormData.employeeId);
    if (!targetEmp) {
      alert("Employee ID not found in registry.");
      return;
    }

    const newPayslip: Document = {
      id: `ps-${Date.now()}`,
      name: `${payslipFormData.month} ${payslipFormData.year}`,
      type: 'Payslip',
      uploadDate: new Date().toISOString().split('T')[0],
      status: 'Verified',
      verifiedBy: `Auto-System [Admin: ${user.name}]`,
      statusHistory: [{ 
        status: 'Verified', 
        timestamp: new Date().toLocaleString(),
        verifiedBy: `System Generator`
      }]
    };

    setEmployees(prev => prev.map(emp => 
      emp.id === targetEmp.id ? { ...emp, documents: [newPayslip, ...(emp.documents || [])] } : emp
    ));

    addNotification(targetEmp.id, "Payslip Released", `Your payslip for ${newPayslip.name} is now available for PDF download.`);
    setIsGeneratingPayslip(false);
    setPayslipFormData({ ...payslipFormData, employeeId: '' });
  };

  const handleFiles = (files: FileList | null) => {
    if (!files || files.length === 0) return;
    const selectedFiles = Array.from(files);
    selectedFiles.forEach(file => {
      const uploadId = `upload-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const newUpload: UploadingFile = {
        id: uploadId,
        name: file.name,
        progress: 0,
        size: 'N/A',
        status: 'uploading'
      };

      let progress = 0;
      const interval = window.setInterval(() => {
        progress += Math.floor(Math.random() * 20) + 5;
        if (progress >= 100) {
          progress = 100;
          clearInterval(interval);
          setTimeout(() => {
            const now = new Date();
            const timestamp = now.toLocaleString('en-US', { 
              month: 'short', day: '2-digit', year: 'numeric', 
              hour: '2-digit', minute: '2-digit', hour12: true 
            });

            const newDoc: Document = {
              id: `doc-${Date.now()}-${Math.random()}`,
              name: file.name.split('.').slice(0, -1).join('.') || file.name,
              type: 'Registry Record',
              uploadDate: now.toISOString().split('T')[0],
              status: 'Pending',
              statusHistory: [{ status: 'Pending', timestamp }]
            };

            setEmployees(prev => prev.map(emp => 
              emp.id === user.id ? { ...emp, documents: [newDoc, ...(emp.documents || [])] } : emp
            ));
            setUploadQueue(prev => prev.filter(u => u.id !== uploadId));
            addNotification(user.id, "Registry Deposit", `"${newDoc.name}" uploaded successfully.`);
          }, 600);
        }
        setUploadQueue(prev => prev.map(u => u.id === uploadId ? { ...u, progress } : u));
      }, 400);
      newUpload.intervalId = interval;
      setUploadQueue(prev => [...prev, newUpload]);
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const cancelUpload = (id: string) => {
    setUploadQueue(prev => {
      const target = prev.find(u => u.id === id);
      if (target?.intervalId) clearInterval(target.intervalId);
      return prev.filter(u => u.id !== id);
    });
  };

  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave = () => { setIsDragging(false); };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    handleFiles(e.dataTransfer.files);
  };

  const toggleHistory = (docId: string) => { setExpandedDocId(expandedDocId === docId ? null : docId); };

  const startEditing = (doc: Document & { ownerId: string }) => {
    if (doc.ownerId !== user.id) return;
    setEditingDocId(doc.id);
    setEditName(doc.name);
    setEditType(doc.type);
  };

  const saveEdit = (docId: string, ownerId: string) => {
    if (!editName.trim()) return;
    setEmployees(prev => prev.map(emp => {
      if (emp.id === ownerId) {
        return {
          ...emp,
          documents: (emp.documents || []).map(d => 
            d.id === docId ? { ...d, name: editName, type: editType } : d
          )
        };
      }
      return emp;
    }));
    setEditingDocId(null);
  };

  const verifyDoc = (docId: string, ownerId: string) => {
    if (!isHR) return;
    const now = new Date();
    const timestamp = now.toLocaleString('en-US', { 
      month: 'short', day: '2-digit', year: 'numeric', 
      hour: '2-digit', minute: '2-digit', hour12: true 
    });
    const verifierIdentity = `${user.name} [HR Master]`;

    setEmployees(prev => prev.map(emp => {
      if (emp.id === ownerId) {
        const docName = emp.documents?.find(d => d.id === docId)?.name;
        addNotification(ownerId, "Record Verified", `HR has finalized verification for "${docName}".`);
        return {
          ...emp,
          documents: (emp.documents || []).map(d => {
            if (d.id === docId) {
              const history = d.statusHistory || [];
              return {
                ...d,
                status: 'Verified' as const,
                verifiedBy: verifierIdentity,
                statusHistory: [...history, { status: 'Verified' as const, timestamp, verifiedBy: verifierIdentity }]
              };
            }
            return d;
          })
        };
      }
      return emp;
    }));
  };

  const finalizeDelete = () => {
    if (docToDelete && isDeleteConfirmed) {
      const { docId, ownerId } = docToDelete;
      if (isHR || ownerId === user.id) {
        setEmployees(prev => prev.map(emp => {
          if (emp.id === ownerId) {
            return {
              ...emp,
              documents: (emp.documents || []).filter(d => d.id !== docId)
            };
          }
          return emp;
        }));
      }
      setDocToDelete(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-blue-900 uppercase tracking-tighter">
            {isHR ? 'Global Registry' : 'My Personnel File'}
          </h1>
          <p className="text-gray-500 font-medium tracking-tight">
            {isHR 
              ? 'Administrative Audit: Oversee and verify organizational compliance documents.' 
              : 'Professional Dossier: Manage your records and certifications.'}
          </p>
        </div>
        <div className="flex gap-3">
          {isHR && activeTab === 'payslips' ? (
            <button 
              onClick={() => setIsGeneratingPayslip(true)}
              className="flex items-center gap-2 px-6 py-3 bg-blue-900 text-white rounded-xl font-bold hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95 text-xs uppercase tracking-widest"
            >
              <CreditCard size={16} />
              Release Payslip
            </button>
          ) : (
            <>
              <input type="file" id="file-upload" multiple className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <label htmlFor="file-upload" className="cursor-pointer flex items-center gap-2 px-6 py-3 bg-blue-900 text-white rounded-xl font-bold hover:bg-blue-800 shadow-lg shadow-blue-900/10 transition-all active:scale-95 text-xs uppercase tracking-widest">
                <Upload size={16} /> Quick Upload
              </label>
            </>
          )}
        </div>
      </header>

      <div className="flex items-center gap-2 p-1.5 bg-gray-100/50 rounded-2xl w-fit">
        <button onClick={() => setActiveTab('general')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'general' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
          <Files size={16} /> General Records
