import React, { useState, useMemo, useEffect } from 'react';
import { 
  Plane, 
  Calendar, 
  CheckCircle, 
  XCircle, 
  Clock, 
  Plus, 
  X, 
  ShieldAlert, 
  Layers, 
  ArrowRight, 
