import React, { useState, useRef, useMemo, useEffect } from 'react';
import { 
  Upload, 
  FileText, 
  Clock, 
  Trash2, 
  ChevronDown, 
  History, 
  Edit2, 
  Save, 
  ShieldCheck, 
  AlertCircle, 
