                            task.status === 'Completed' ? 'bg-green-500 text-white shadow-sm' :
                            task.status === 'In Progress' ? 'bg-blue-900 text-white shadow-sm' :
                            'bg-gray-200 text-gray-600'
                          }`}>{task.status}</span>
                        </div>
                      ))
                    )}
                  </div>
