                        <UserCheck size={20}/>
                      </button>
                    </div>
                  </div>
                  {resetSuccess && (
                    <div className="flex items-center gap-2 text-[10px] font-black text-green-700 uppercase tracking-widest animate-in fade-in">
                      <CheckCircle size={14} /> Update Committed
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Employees;
